//! Global message/exit-status state and logging macros.

use std::sync::atomic::{AtomicBool, AtomicU8, Ordering};

static MESSAGES: AtomicBool = AtomicBool::new(true);
static IGNORE_MESSAGES: AtomicBool = AtomicBool::new(true);
static ERRORED: AtomicBool = AtomicBool::new(false);
/// 0 = off, 1 = debug, 2 = trace
static LOG_LEVEL: AtomicU8 = AtomicU8::new(0);

pub fn messages() -> bool {
    MESSAGES.load(Ordering::SeqCst)
}
pub fn set_messages(yes: bool) {
    MESSAGES.store(yes, Ordering::SeqCst)
}
pub fn ignore_messages() -> bool {
    IGNORE_MESSAGES.load(Ordering::SeqCst)
}
pub fn set_ignore_messages(yes: bool) {
    IGNORE_MESSAGES.store(yes, Ordering::SeqCst)
}
pub fn errored() -> bool {
    ERRORED.load(Ordering::SeqCst)
}
pub fn set_errored() {
    ERRORED.store(true, Ordering::SeqCst);
}
pub fn log_level() -> u8 {
    LOG_LEVEL.load(Ordering::SeqCst)
}
pub fn set_log_level(level: u8) {
    LOG_LEVEL.store(level, Ordering::SeqCst)
}
pub fn debug_enabled() -> bool {
    log_level() >= 1
}
pub fn trace_enabled() -> bool {
    log_level() >= 2
}

/// Emit a message to stderr with the `rg: ` prefix (always).
#[macro_export]
macro_rules! eprintln_locked {
    ($($tt:tt)*) => {{
        use std::io::Write;
        let stderr = std::io::stderr();
        let mut stderr = stderr.lock();
        let _ = write!(stderr, "rg: ");
        let _ = writeln!(stderr, $($tt)*);
    }}
}

/// Emit a non-fatal error message, unless --no-messages. Marks errored.
#[macro_export]
macro_rules! err_message {
    ($($tt:tt)*) => {
        $crate::messages::set_errored();
        $crate::message!($($tt)*);
    }
}

/// Emit a message unless --no-messages. Does not mark errored.
#[macro_export]
macro_rules! message {
    ($($tt:tt)*) => {
        if $crate::messages::messages() {
            $crate::eprintln_locked!($($tt)*);
        }
    }
}

/// Emit an ignore-related message unless --no-ignore-messages or --no-messages.
#[macro_export]
macro_rules! ignore_message {
    ($($tt:tt)*) => {
        if $crate::messages::messages() && $crate::messages::ignore_messages() {
            $crate::eprintln_locked!($($tt)*);
        }
    }
}

#[macro_export]
macro_rules! log_debug {
    ($target:expr, $loc:expr, $($tt:tt)*) => {
        if $crate::messages::debug_enabled() {
            use std::io::Write;
            let stderr = std::io::stderr();
            let mut stderr = stderr.lock();
            let _ = write!(stderr, "rg: DEBUG|{}|{}: ", $target, $loc);
            let _ = writeln!(stderr, $($tt)*);
        }
    }
}

#[macro_export]
macro_rules! log_trace {
    ($target:expr, $loc:expr, $($tt:tt)*) => {
        if $crate::messages::trace_enabled() {
            use std::io::Write;
            let stderr = std::io::stderr();
            let mut stderr = stderr.lock();
            let _ = write!(stderr, "rg: TRACE|{}|{}: ", $target, $loc);
            let _ = writeln!(stderr, $($tt)*);
        }
    }
}
EOF
echo done"}

