//! Miscellaneous utilities shared across modules.

use std::ffi::{OsStr, OsString};

use crate::error::{Error, Result};

/// Unescape a string with `\t`, `\n`, `\r`, `\0`, `\\` and `\xHH` escapes.
pub fn unescape(s: &[u8]) -> Vec<u8> {
    enum State {
        Escape,
        HexFirst,
        HexSecond(u8),
        Literal,
    }
    use State::*;
    let mut bytes = vec![];
    let mut state = Literal;
    for &c in s {
        match state {
            Escape => match c {
                b'\\' => {
                    bytes.push(b'\\');
                    state = Literal;
                }
                b'n' => {
                    bytes.push(b'\n');
                    state = Literal;
                }
                b'r' => {
                    bytes.push(b'\r');
                    state = Literal;
                }
                b't' => {
                    bytes.push(b'\t');
                    state = Literal;
                }
                b'0' => {
                    bytes.push(b'\x00');
                    state = Literal;
                }
                b'x' => {
                    state = HexFirst;
                }
                c => {
                    bytes.push(b'\\');
                    bytes.push(c);
                    state = Literal;
                }
            },
            HexFirst => match c {
