//! A simple string-based error type that mimics anyhow's `{:#}` display.

use std::fmt;

#[derive(Debug, Clone)]
pub struct Error(pub String);

pub type Result<T> = std::result::Result<T, Error>;

impl Error {
    pub fn new<S: Into<String>>(s: S) -> Error {
        Error(s.into())
    }
    pub fn context<S: AsRef<str>>(self, ctx: S) -> Error {
        Error(format!("{}: {}", ctx.as_ref(), self.0))
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Error {}

impl From<std::io::Error> for Error {
    fn from(err: std::io::Error) -> Error {
        Error(err.to_string())
    }
}

impl From<String> for Error {
    fn from(s: String) -> Error {
        Error(s)
    }
}

impl From<&str> for Error {
    fn from(s: &str) -> Error {
        Error(s.to_string())
    }
}

#[macro_export]
macro_rules! bail {
    ($($tt:tt)*) => { return Err($crate::error::Error::new(format!($($tt)*))) }
}

#[macro_export]
macro_rules! err {
    ($($tt:tt)*) => { $crate::error::Error::new(format!($($tt)*)) }
}

pub trait Context<T> {
    fn context<S: AsRef<str>>(self, ctx: S) -> Result<T>;
    fn with_context<S: AsRef<str>, F: FnOnce() -> S>(self, f: F) -> Result<T>;
}

impl<T, E: fmt::Display> Context<T> for std::result::Result<T, E> {
    fn context<S: AsRef<str>>(self, ctx: S) -> Result<T> {
        self.map_err(|e| Error(format!("{}: {}", ctx.as_ref(), e)))
    }
    fn with_context<S: AsRef<str>, F: FnOnce() -> S>(self, f: F) -> Result<T> {
        self.map_err(|e| Error(format!("{}: {}", f().as_ref(), e)))
    }
}
