//! Color specifications and ANSI escape writing (termcolor-compatible).

use std::io::{self, Write};
use std::str::FromStr;

use crate::error::{Error, Result};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Black,
    Blue,
    Green,
    Red,
    Cyan,
    Magenta,
    Yellow,
    White,
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

fn parse_number(s: &str) -> Option<u8> {
    if let Some(hex) = s.strip_prefix("0x") {
        u8::from_str_radix(hex, 16).ok()
    } else {
        u8::from_str_radix(s, 10).ok()
    }
}

impl FromStr for Color {
    type Err = Error;
    fn from_str(s: &str) -> Result<Color> {
        let codes: Vec<&str> = s.split(',').collect();
        if codes.len() == 1 {
            if let Ok(n) = codes[0].parse::<u8>() {
                return Ok(Color::Ansi256(n));
            }
            if let Some(n) = parse_number(codes[0]) {
                return Ok(Color::Ansi256(n));
            }
            match s {
                "black" => Ok(Color::Black),
                "blue" => Ok(Color::Blue),
                "green" => Ok(Color::Green),
                "red" => Ok(Color::Red),
                "cyan" => Ok(Color::Cyan),
                "magenta" => Ok(Color::Magenta),
                "yellow" => Ok(Color::Yellow),
                "white" => Ok(Color::White),
                _ => {
                    if s.chars().all(|c| c.is_digit(16)) {
                        Err(invalid_ansi256(s))
                    } else {
                        Err(invalid_name(s))
                    }
                }
            }
        } else if codes.len() == 3 {
            let mut v = vec![];
            for code in codes {
                let n = parse_number(code).ok_or_else(|| invalid_rgb(s))?;
                v.push(n);
            }
            Ok(Color::Rgb(v[0], v[1], v[2]))
        } else if s.contains(',') {
            Err(invalid_rgb(s))
        } else {
            Err(invalid_name(s))
        }
    }
}

fn invalid_name(s: &str) -> Error {
    Error::new(format!(
        "unrecognized color name '{}'. Choose from: \
         black, blue, green, red, cyan, magenta, yellow, white",
        s
    ))
}
fn invalid_ansi256(s: &str) -> Error {
    Error::new(format!(
        "unrecognized ansi256 color number, \
         should be '[0-255]' (or a hex number), but is '{}'",
        s
    ))
}
fn invalid_rgb(s: &str) -> Error {
    Error::new(format!(
        "unrecognized RGB color triple, \
         should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
        s
    ))
}

/// A color specification (subset of termcolor's ColorSpec).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ColorSpec {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub intense: bool,
    pub underline: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub reset: bool,
}

impl Default for ColorSpec {
    fn default() -> ColorSpec {
        ColorSpec {
            fg: None,
            bg: None,
            bold: false,
            intense: false,
            underline: false,
            dimmed: false,
            italic: false,
            reset: true,
        }
    }
}

impl ColorSpec {
    pub fn new() -> ColorSpec {
        ColorSpec::default()
    }
    pub fn is_none(&self) -> bool {
        self.fg.is_none()
            && self.bg.is_none()
            && !self.bold
            && !self.intense
            && !self.underline
            && !self.dimmed
            && !self.italic
    }
}

/// Write the ANSI escape sequence for setting a color spec.
pub fn write_set_color<W: Write>(wtr: &mut W, spec: &ColorSpec) -> io::Result<()> {
    if spec.reset {
        wtr.write_all(b"\x1b[0m")?;
    }
    if spec.bold {
        wtr.write_all(b"\x1b[1m")?;
    }
    if spec.dimmed {
        wtr.write_all(b"\x1b[2m")?;
    }
    if spec.italic {
        wtr.write_all(b"\x1b[3m")?;
    }
    if spec.underline {
        wtr.write_all(b"\x1b[4m")?;
    }
    if let Some(ref c) = spec.fg {
        write_color(wtr, true, c, spec.intense)?;
    }
    if let Some(ref c) = spec.bg {
        write_color(wtr, false, c, spec.intense)?;
    }
    Ok(())
}

pub fn write_reset<W: Write>(wtr: &mut W) -> io::Result<()> {
    wtr.write_all(b"\x1b[0m")
}

fn write_color<W: Write>(wtr: &mut W, fg: bool, c: &Color, intense: bool) -> io::Result<()> {
    let normal = |wtr: &mut W, code: &str| -> io::Result<()> {
        if fg {
            write!(wtr, "\x1b[3{}m", code)
        } else {
            write!(wtr, "\x1b[4{}m", code)
        }
    };
    let intense_named = |wtr: &mut W, code: &str| -> io::Result<()> {
        if fg {
            write!(wtr, "\x1b[38;5;{}m", code)
        } else {
            write!(wtr, "\x1b[48;5;{}m", code)
        }
    };
    if intense {
        match *c {
            Color::Black => intense_named(wtr, "8"),
            Color::Blue => intense_named(wtr, "12"),
            Color::Green => intense_named(wtr, "10"),
            Color::Red => intense_named(wtr, "9"),
            Color::Cyan => intense_named(wtr, "14"),
            Color::Magenta => intense_named(wtr, "13"),
            Color::Yellow => intense_named(wtr, "11"),
            Color::White => intense_named(wtr, "15"),
            Color::Ansi256(n) => {
                if fg {
                    write!(wtr, "\x1b[38;5;{}m", n)
                } else {
                    write!(wtr, "\x1b[48;5;{}m", n)
                }
            }
            Color::Rgb(r, g, b) => {
                if fg {
                    write!(wtr, "\x1b[38;2;{};{};{}m", r, g, b)
                } else {
                    write!(wtr, "\x1b[48;2;{};{};{}m", r, g, b)
                }
            }
        }
    } else {
        match *c {
            Color::Black => normal(wtr, "0"),
            Color::Blue => normal(wtr, "4"),
            Color::Green => normal(wtr, "2"),
            Color::Red => normal(wtr, "1"),
            Color::Cyan => normal(wtr, "6"),
            Color::Magenta => normal(wtr, "5"),
            Color::Yellow => normal(wtr, "3"),
            Color::White => normal(wtr, "7"),
            Color::Ansi256(n) => {
                if fg {
                    write!(wtr, "\x1b[38;5;{}m", n)
                } else {
                    write!(wtr, "\x1b[48;5;{}m", n)
                }
            }
            Color::Rgb(r, g, b) => {
                if fg {
                    write!(wtr, "\x1b[38;2;{};{};{}m", r, g, b)
                } else {
                    write!(wtr, "\x1b[48;2;{};{};{}m", r, g, b)
                }
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OutType {
    Path,
    Line,
    Column,
    Match,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SpecType {
    Fg,
    Bg,
    Style,
    None,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Style {
    Bold,
    NoBold,
    Intense,
    NoIntense,
    Underline,
    NoUnderline,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum SpecValue {
    None,
    Fg(Color),
    Bg(Color),
    Style(Style),
}

/// A single user color spec like `match:fg:red`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UserColorSpec {
    ty: OutType,
    value: SpecValue,
}

impl FromStr for UserColorSpec {
    type Err = Error;
    fn from_str(s: &str) -> Result<UserColorSpec> {
        let pieces: Vec<&str> = s.split(':').collect();
        if pieces.len() <= 1 || pieces.len() > 3 {
            return Err(invalid_format(s));
        }
        let otype = match pieces[0] {
            "path" => OutType::Path,
            "line" => OutType::Line,
            "column" => OutType::Column,
            "match" => OutType::Match,
            other => {
                return Err(Error::new(format!(
                    "unrecognized output type '{}'. Choose from: \
                     path, line, column, match.",
                    other
                )))
            }
        };
        let stype = match pieces[1] {
            "fg" => SpecType::Fg,
            "bg" => SpecType::Bg,
            "style" => SpecType::Style,
            "none" => SpecType::None,
            other => {
                return Err(Error::new(format!(
                    "unrecognized spec type '{}'. Choose from: \
                     fg, bg, style, none.",
                    other
                )))
            }
        };
        match stype {
            SpecType::None => Ok(UserColorSpec { ty: otype, value: SpecValue::None }),
