//! Hyperlink format parsing and URL construction.

use std::path::Path;
use std::str::FromStr;

use crate::error::{Error, Result};

#[derive(Debug, Clone, PartialEq, Eq)]
enum Part {
    Text(Vec<u8>),
    Host,
    WslPrefix,
    Path,
    Line,
    Column,
}

/// A parsed hyperlink format.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct HyperlinkFormat {
    parts: Vec<Part>,
    is_line_dependent: bool,
}

impl HyperlinkFormat {
    pub fn empty() -> HyperlinkFormat {
        HyperlinkFormat::default()
    }
    pub fn is_empty(&self) -> bool {
        self.parts.is_empty()
    }
    pub fn is_line_dependent(&self) -> bool {
        self.is_line_dependent
    }

    pub fn from_alias(alias: &str) -> Option<&'static str> {
        Some(match alias {
            "default" => "file://{host}{path}",
            "file" => "file://{host}{path}",
            "grep+" => "grep+://{path}:{line}",
            "kitty" => "file://{host}{path}#{line}",
            "macvim" => "mvim://open?url=file://{path}&line={line}&column={column}",
            "none" => "",
            "textmate" => "txmt://open?url=file://{path}&line={line}&column={column}",
            "vscode" => "vscode://file{path}:{line}:{column}",
            "vscode-insiders" => "vscode-insiders://file{path}:{line}:{column}",
            "vscodium" => "vscodium://file{path}:{line}:{column}",
            _ => return None,
        })
    }

    /// Returns the format string for display (as in --debug output).
    pub fn to_format_string(&self) -> String {
        let mut s = String::new();
        for part in &self.parts {
            match part {
                Part::Text(t) => s.push_str(&String::from_utf8_lossy(t)),
                Part::Host => s.push_str("{host}"),
                Part::WslPrefix => s.push_str("{wslprefix}"),
                Part::Path => s.push_str("{path}"),
                Part::Line => s.push_str("{line}"),
                Part::Column => s.push_str("{column}"),
            }
        }
        s
    }
}

impl FromStr for HyperlinkFormat {
    type Err = Error;
    fn from_str(s: &str) -> Result<HyperlinkFormat> {
        use std::os::unix::ffi::OsStrExt;
        let _ = OsStrExt::as_bytes;
        let fmt = match HyperlinkFormat::from_alias(s) {
            Some(fmt) => fmt,
            None => s,
        };
        let mut builder = Builder::default();
        let bytes = fmt.as_bytes();
        let mut i = 0;
        let mut var_start: Option<usize> = None;
        let mut text: Vec<u8> = vec![];
        while i < bytes.len() {
            let b = bytes[i];
            match var_start {
                None => {
                    if b == b'{' {
                        if !text.is_empty() {
                            builder.parts.push(Part::Text(std::mem::take(&mut text)));
                        }
                        var_start = Some(i + 1);
                    } else if b == b'}' {
                        return Err(Error::new(
                            "invalid hyperlink format: unopened variable: \
                             found '}' without a corresponding '{' preceding it",
                        ));
                    } else {
                        text.push(b);
                    }
                }
                Some(start) => {
                    if b == b'}' {
                        let name = &fmt[start..i];
                        let part = match name {
                            "host" => Part::Host,
                            "wslprefix" => Part::WslPrefix,
                            "path" => Part::Path,
                            "line" => Part::Line,
                            "column" => Part::Column,
                            other => {
                                return Err(Error::new(format!(
                                    "invalid hyperlink format: invalid hyperlink format \
                                     variable: '{}', choose from: path, line, column, \
                                     host, wslprefix",
                                    other
                                )))
                            }
                        };
                        builder.parts.push(part);
                        var_start = None;
                    } else if b == b'{' {
                        return Err(Error::new(
                            "invalid hyperlink format: unclosed variable: \
                             found '{' without a corresponding '}' following it",
                        ));
                    }
                }
            }
            i += 1;
        }
        if var_start.is_some() {
            return Err(Error::new(
                "invalid hyperlink format: unclosed variable: \
                 found '{' without a corresponding '}' following it",
            ));
        }
        if !text.is_empty() {
            builder.parts.push(Part::Text(text));
        }
        builder.build()
    }
}

#[derive(Default)]
struct Builder {
    parts: Vec<Part>,
}

impl Builder {
    fn build(self) -> Result<HyperlinkFormat> {
        if self.parts.is_empty() {
            return Ok(HyperlinkFormat::empty());
        }
        let has_var = self.parts.iter().any(|p| !matches!(p, Part::Text(_)));
        if !has_var {
            return Err(Error::new(
                "invalid hyperlink format: at least a {path} variable is required in a \
                 hyperlink format, or otherwise use a valid alias: default, file, grep+, \
                 kitty, macvim, none, textmate, vscode, vscode-insiders, vscodium",
            ));
        }
        let has_path = self.parts.iter().any(|p| matches!(p, Part::Path));
        if !has_path {
            return Err(Error::new(
                "invalid hyperlink format: the {path} variable is required in a hyperlink format",
            ));
        }
        let has_line = self.parts.iter().any(|p| matches!(p, Part::Line));
        let has_column = self.parts.iter().any(|p| matches!(p, Part::Column));
        if has_column && !has_line {
            return Err(Error::new(
                "invalid hyperlink format: the hyperlink format contains a {column} variable, \
                 but no {line} variable is present",
            ));
        }
        // Must start with a valid scheme.
        let scheme_ok = match self.parts.first() {
            Some(Part::Text(t)) => {
                let colon = t.iter().position(|&b| b == b':');
                match colon {
                    Some(0) | None => false,
                    Some(idx) => t[..idx].iter().all(|&b| {
                        b.is_ascii_alphanumeric() || b == b'+' || b == b'-' || b == b'.'
                    }),
                }
            }
            _ => false,
        };
        if !scheme_ok {
            return Err(Error::new(
                "invalid hyperlink format: the hyperlink format must start with a valid URL \
                 scheme, i.e., [0-9A-Za-z+-.]+:",
            ));
        }
        Ok(HyperlinkFormat { parts: self.parts, is_line_dependent: has_line })
    }
}

/// Environment used for building hyperlinks.
#[derive(Debug, Clone, Default)]
pub struct HyperlinkEnvironment {
    pub host: Option<Vec<u8>>,
    pub wsl_prefix: Option<Vec<u8>>,
}

/// Configuration for generating hyperlinks (format + environment).
#[derive(Debug, Clone, Default)]
pub struct HyperlinkConfig {
    pub env: HyperlinkEnvironment,
    pub format: HyperlinkFormat,
}

impl HyperlinkConfig {
    pub fn is_empty(&self) -> bool {
        self.format.is_empty()
    }
}

/// A path prepared for hyperlinking: absolute and percent-encoded.
#[derive(Debug, Clone)]
pub struct HyperlinkPath(Vec<u8>);

impl HyperlinkPath {
    pub fn from_path(original: &Path) -> Option<HyperlinkPath> {
        use std::os::unix::ffi::OsStrExt;
        let path = if original.is_absolute() {
            original.to_path_buf()
        } else {
            match std::env::current_dir() {
                Ok(cwd) => cwd.join(original),
                Err(_) => return None,
            }
        };
        let bytes = path.as_os_str().as_bytes();
        // Normalize "/./" components? ripgrep uses the joined path mostly as-is
        // but strips any leading "./" components via Path::join semantics.
        let mut encoded = Vec::with_capacity(bytes.len());
        for &b in bytes {
            match b {
