fn push_char(out: &mut Vec<u8>, cp: u32) {
    let c = char::from_u32(cp).unwrap_or('\u{FFFD}');
    let mut buf = [0u8; 4];
    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
}

/// Streaming decoder state.
#[derive(Debug)]
enum DecoderState {
    Utf8 { pending: Vec<u8> },
    Utf16 { le: bool, pending: Vec<u8>, high: Option<u16> },
    SingleByte(usize),
    XUserDefined,
    Passthru,
}

/// A reader that transcodes its input to UTF-8, with BOM sniffing.
pub struct DecodeReader<R: Read> {
    rdr: R,
    state: Option<DecoderState>,
    /// Explicit encoding (None for auto).
    explicit: Option<Encoding>,
    /// Buffered decoded output not yet handed to the caller.
    out: Vec<u8>,
    out_pos: usize,
    /// Buffer for raw reads.
    raw: Vec<u8>,
    /// Bytes read during BOM sniffing but not yet processed.
    sniffed: Vec<u8>,
    eof: bool,
    done: bool,
}

impl<R: Read> DecodeReader<R> {
    /// Create a new transcoding reader. `explicit` is the explicitly chosen
    /// encoding (if any). BOM sniffing is always performed.
    pub fn new(rdr: R, explicit: Option<Encoding>) -> DecodeReader<R> {
        DecodeReader {
            rdr,
            state: None,
            explicit,
            out: vec![],
            out_pos: 0,
            raw: vec![0; 64 * 1024],
            sniffed: vec![],
            eof: false,
            done: false,
        }
    }

    fn init_state(&mut self) -> io::Result<()> {
        // Read at least 3 bytes (or until EOF) for BOM sniffing.
        while self.sniffed.len() < 3 && !self.eof {
            let mut tmp = [0u8; 3];
            let n = self.rdr.read(&mut tmp[..3 - self.sniffed.len()])?;
            if n == 0 {
                self.eof = true;
            } else {
                self.sniffed.extend_from_slice(&tmp[..n]);
            }
        }
        let s = &self.sniffed;
        let (state, strip) = if s.len() >= 3 && s[0] == 0xEF && s[1] == 0xBB && s[2] == 0xBF {
            // UTF-8 BOM.
            match self.explicit {
                None => (DecoderState::Passthru, 3),
                Some(_) => (DecoderState::Utf8 { pending: vec![] }, 3),
            }
        } else if s.len() >= 2 && s[0] == 0xFF && s[1] == 0xFE {
            (DecoderState::Utf16 { le: true, pending: vec![], high: None }, 2)
        } else if s.len() >= 2 && s[0] == 0xFE && s[1] == 0xFF {
            (DecoderState::Utf16 { le: false, pending: vec![], high: None }, 2)
        } else {
            let st = match self.explicit {
                None => DecoderState::Passthru,
                Some(Encoding::Utf8) => DecoderState::Utf8 { pending: vec![] },
                Some(Encoding::Utf16Le) => {
                    DecoderState::Utf16 { le: true, pending: vec![], high: None }
                }
                Some(Encoding::Utf16Be) => {
                    DecoderState::Utf16 { le: false, pending: vec![], high: None }
                }
                Some(Encoding::SingleByte(i)) => DecoderState::SingleByte(i),
                Some(Encoding::XUserDefined) => DecoderState::XUserDefined,
                Some(Encoding::Unsupported(_)) => DecoderState::Passthru,
            };
            (st, 0)
        };
        self.state = Some(state);
        let rest: Vec<u8> = self.sniffed[strip..].to_vec();
        self.sniffed.clear();
        if !rest.is_empty() {
            self.decode_chunk(&rest);
        }
        Ok(())
    }

    fn decode_chunk(&mut self, chunk: &[u8]) {
        let out = &mut self.out;
        match self.state.as_mut().unwrap() {
            DecoderState::Passthru => out.extend_from_slice(chunk),
            DecoderState::SingleByte(i) => {
                let table = &SINGLE_BYTE_TABLES[*i].1;
                for &b in chunk {
                    if b < 0x80 {
                        out.push(b);
                    } else {
                        let cp = table[(b - 0x80) as usize];
                        if cp == 0 {
                            push_char(out, 0xFFFD);
                        } else {
                            push_char(out, cp as u32);
                        }
                    }
                }
            }
            DecoderState::XUserDefined => {
                for &b in chunk {
                    if b < 0x80 {
                        out.push(b);
                    } else {
                        push_char(out, 0xF780 + (b as u32 - 0x80));
                    }
                }
            }
            DecoderState::Utf8 { pending } => {
                let mut data = std::mem::take(pending);
                data.extend_from_slice(chunk);
                // Decode as much as possible, keeping an incomplete trailing
                // sequence pending.
                let mut i = 0;
                while i < data.len() {
                    match std::str::from_utf8(&data[i..]) {
                        Ok(s) => {
                            out.extend_from_slice(s.as_bytes());
                            i = data.len();
                        }
                        Err(e) => {
                            let valid = e.valid_up_to();
                            out.extend_from_slice(&data[i..i + valid]);
                            i += valid;
                            match e.error_len() {
                                Some(bad) => {
                                    push_char(out, 0xFFFD);
                                    i += bad;
                                }
                                None => {
                                    // incomplete sequence at end
                                    *pending = data[i..].to_vec();
                                    i = data.len();
                                    return;
                                }
                            }
                        }
                    }
                }
            }
            DecoderState::Utf16 { le, pending, high } => {
                let mut data = std::mem::take(pending);
                data.extend_from_slice(chunk);
                let mut i = 0;
                while i + 1 < data.len() {
                    let unit = if *le {
                        u16::from_le_bytes([data[i], data[i + 1]])
                    } else {
                        u16::from_be_bytes([data[i], data[i + 1]])
                    };
                    i += 2;
                    if let Some(h) = high.take() {
                        if (0xDC00..=0xDFFF).contains(&unit) {
                            let cp = 0x10000
                                + (((h as u32) - 0xD800) << 10)
                                + ((unit as u32) - 0xDC00);
                            push_char(out, cp);
                            continue;
                        } else {
                            push_char(out, 0xFFFD);
                            // fall through to process unit normally
                        }
                    }
                    if (0xD800..=0xDBFF).contains(&unit) {
                        *high = Some(unit);
                    } else if (0xDC00..=0xDFFF).contains(&unit) {
                        push_char(out, 0xFFFD);
                    } else {
                        push_char(out, unit as u32);
                    }
                }
                if i < data.len() {
                    *pending = data[i..].to_vec();
                }
            }
        }
    }

    fn finish(&mut self) {
        let out = &mut self.out;
        match self.state.as_mut().unwrap() {
            DecoderState::Utf8 { pending } => {
                if !pending.is_empty() {
                    push_char(out, 0xFFFD);
                    pending.clear();
                }
            }
            DecoderState::Utf16 { pending, high, .. } => {
                if high.take().is_some() {
                    push_char(out, 0xFFFD);
                }
                if !pending.is_empty() {
                    push_char(out, 0xFFFD);
                    pending.clear();
                }
            }
            _ => {}
        }
    }
}

impl<R: Read> Read for DecodeReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        if self.state.is_none() {
            self.init_state()?;
        }
        loop {
            if self.out_pos < self.out.len() {
                let n = std::cmp::min(buf.len(), self.out.len() - self.out_pos);
                buf[..n].copy_from_slice(&self.out[self.out_pos..self.out_pos + n]);
                self.out_pos += n;
                if self.out_pos == self.out.len() {
                    self.out.clear();
                    self.out_pos = 0;
                }
                return Ok(n);
            }
            if self.done {
                return Ok(0);
            }
            if self.eof {
                self.finish();
                self.done = true;
                continue;
            }
            // Passthru fast path: read directly into the caller's buffer.
            if matches!(self.state, Some(DecoderState::Passthru)) {
                let n = self.rdr.read(buf)?;
                if n == 0 {
                    self.eof = true;
                    self.done = true;
                }
                return Ok(n);
            }
            let n = self.rdr.read(&mut self.raw)?;
            if n == 0 {
                self.eof = true;
                continue;
            }
            let chunk: Vec<u8> = self.raw[..n].to_vec();
            self.decode_chunk(&chunk);
        }
    }
}

/// Transcode an entire byte slice to UTF-8 (used for the slice/mmap search
/// path). Returns None if no transcoding is necessary (passthrough with no
/// BOM to strip).
pub fn transcode_slice(bytes: &[u8], explicit: Option<Encoding>) -> Option<Vec<u8>> {
    let has_utf8_bom = bytes.len() >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF;
    let has_utf16_bom = bytes.len() >= 2
        && ((bytes[0] == 0xFF && bytes[1] == 0xFE) || (bytes[0] == 0xFE && bytes[1] == 0xFF));
    if explicit.is_none() && !has_utf8_bom && !has_utf16_bom {
        return None;
    }
    if let Some(Encoding::Unsupported(_)) = explicit {
        if !has_utf8_bom && !has_utf16_bom {
            return None;
        }
    }
    let mut rdr = DecodeReader::new(bytes, explicit);
    let mut out = Vec::with_capacity(bytes.len());
    let _ = rdr.read_to_end(&mut out);
    Some(out)
}
