#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Encoding {
    Utf8,
    Utf16Le,
    Utf16Be,
    SingleByte(usize),
    XUserDefined,
    /// Multi-byte legacy encodings we recognize but cannot fully decode.
    Unsupported(&'static str),
}

impl Encoding {
    pub fn name(&self) -> &'static str {
        match *self {
            Encoding::Utf8 => "UTF-8",
            Encoding::Utf16Le => "UTF-16LE",
            Encoding::Utf16Be => "UTF-16BE",
            Encoding::SingleByte(i) => SINGLE_BYTE_TABLES[i].0,
