            if matches!(self.state, Some(DecoderState::Passthru)) {
                let n = self.rdr.read(buf)?;
                if n == 0 {
                    self.eof = true;
                    self.done = true;
                }
                return Ok(n);
            }
            let n = self.rdr.read(&mut self.raw)?;
            if n == 0 {
                self.eof = true;
                continue;
            }
            let chunk: Vec<u8> = self.raw[..n].to_vec();
            self.decode_chunk(&chunk);
        }
    }
}

/// Transcode an entire byte slice to UTF-8 (used for the slice/mmap search
/// path). Returns None if no transcoding is necessary (passthrough with no
/// BOM to strip).
pub fn transcode_slice(bytes: &[u8], explicit: Option<Encoding>) -> Option<Vec<u8>> {
    let has_utf8_bom = bytes.len() >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF;
    let has_utf16_bom = bytes.len() >= 2
        && ((bytes[0] == 0xFF && bytes[1] == 0xFE) || (bytes[0] == 0xFE && bytes[1] == 0xFF));
    if explicit.is_none() && !has_utf8_bom && !has_utf16_bom {
        return None;
    }
    if let Some(Encoding::Unsupported(_)) = explicit {
        if !has_utf8_bom && !has_utf16_bom {
            return None;
        }
    }
    let mut rdr = DecodeReader::new(bytes, explicit);
    let mut out = Vec::with_capacity(bytes.len());
    let _ = rdr.read_to_end(&mut out);
