//! Glob parsing and matching with gitignore-like semantics.

use std::fmt;

use regex_automata::meta::Regex;
use regex_automata::{Input, PatternSet};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GlobErrorKind {
    UnclosedClass,
    InvalidRange(char, char),
    UnopenedAlternates,
    UnclosedAlternates,
    NestedAlternates,
    DanglingEscape,
    Regex(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GlobError {
    pub glob: Option<String>,
    pub kind: GlobErrorKind,
}

impl fmt::Display for GlobErrorKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            GlobErrorKind::UnclosedClass => {
                write!(f, "unclosed character class; missing ']'")
            }
            GlobErrorKind::InvalidRange(s, e) => {
