                 (maybe escape '{{' with '[{{]'?)"
            ),
            GlobErrorKind::NestedAlternates => {
                write!(f, "nested alternate groups are not allowed")
            }
            GlobErrorKind::DanglingEscape => write!(f, "dangling '\\'"),
            GlobErrorKind::Regex(ref err) => write!(f, "{}", err),
        }
    }
}

impl fmt::Display for GlobError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.glob {
            None => self.kind.fmt(f),
            Some(ref glob) => {
                write!(f, "error parsing glob '{}': {}", glob, self.kind)
            }
        }
