}

impl std::error::Error for GlobError {}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Token {
    Literal(char),
    Any,
    ZeroOrMore,
    RecursivePrefix,
    RecursiveSuffix,
    RecursiveZeroOrMore,
    Class { negated: bool, ranges: Vec<(char, char)> },
    Alternates(Vec<Vec<Token>>),
}

#[derive(Debug, Clone, Copy, Default)]
pub struct GlobOptions {
    pub case_insensitive: bool,
    pub literal_separator: bool,
    pub backslash_escape: bool,
}

impl GlobOptions {
    pub fn new() -> GlobOptions {
        GlobOptions { case_insensitive: false, literal_separator: false, backslash_escape: true }
    }
}

#[derive(Debug, Clone)]
pub struct Glob {
    glob: String,
    re: String,
    opts: GlobOptions,
    tokens: Vec<Token>,
}

impl Glob {
    pub fn new(glob: &str, opts: GlobOptions) -> Result<Glob, GlobError> {
        let mut p = Parser {
            glob,
            stack: vec![vec![]],
            chars: glob.chars().peekable(),
            prev: None,
            cur: None,
            opts,
        };
        p.parse()?;
        if p.stack.is_empty() {
            return Err(GlobError { glob: Some(glob.to_string()), kind: GlobErrorKind::UnopenedAlternates });
        } else if p.stack.len() > 1 {
            return Err(GlobError { glob: Some(glob.to_string()), kind: GlobErrorKind::UnclosedAlternates });
        }
        let tokens = p.stack.pop().unwrap();
        let re = tokens_to_regex_full(&tokens, &opts);
        Ok(Glob { glob: glob.to_string(), re, opts, tokens })
    }

    pub fn glob(&self) -> &str {
        &self.glob
    }

    pub fn regex(&self) -> &str {
        &self.re
    }

    /// Compile this single glob into a matcher.
    pub fn compile_matcher(&self) -> GlobMatcher {
        let re = Regex::builder()
            .syntax(regex_automata::util::syntax::Config::new().utf8(false))
            .configure(Regex::config().utf8_empty(false))
            .build(&self.re)
            .expect("valid glob regex");
        GlobMatcher { re }
    }
}

pub struct GlobMatcher {
    re: Regex,
}

impl GlobMatcher {
    pub fn is_match(&self, path: &[u8]) -> bool {
        self.re.is_match(path)
    }
}

fn char_to_escaped_literal(c: char) -> String {
    let mut s = String::new();
    s.push(c);
    regex_syntax::escape(&s)
}

fn tokens_to_regex_full(tokens: &[Token], opts: &GlobOptions) -> String {
    let mut re = String::new();
    re.push_str("(?-u)");
    if opts.case_insensitive {
        re.push_str("(?i)");
    }
    re.push('^');
    if tokens.len() == 1 && tokens[0] == Token::RecursivePrefix {
        re.push_str(".*");
        re.push('$');
        return re;
    }
    tokens_to_regex(tokens, opts, &mut re);
    re.push('$');
    re
}

fn tokens_to_regex(tokens: &[Token], opts: &GlobOptions, re: &mut String) {
    for tok in tokens {
        match *tok {
            Token::Literal(c) => re.push_str(&char_to_escaped_literal(c)),
            Token::Any => {
                if opts.literal_separator {
                    re.push_str("[^/]");
                } else {
                    re.push('.');
                }
            }
            Token::ZeroOrMore => {
                if opts.literal_separator {
                    re.push_str("[^/]*");
                } else {
                    re.push_str(".*");
                }
            }
            Token::RecursivePrefix => re.push_str("(?:/?|.*/)"),
            Token::RecursiveSuffix => re.push_str("/.*"),
            Token::RecursiveZeroOrMore => re.push_str("(?:/|/.*/)"),
            Token::Class { negated, ref ranges } => {
                re.push('[');
                if negated {
                    re.push('^');
                }
                for r in ranges {
                    if r.0 == r.1 {
                        re.push_str(&char_to_escaped_literal(r.0));
                    } else {
                        re.push_str(&char_to_escaped_literal(r.0));
                        re.push('-');
                        re.push_str(&char_to_escaped_literal(r.1));
                    }
                }
                re.push(']');
            }
            Token::Alternates(ref patterns) => {
                let mut parts = vec![];
                for pat in patterns {
                    let mut altre = String::new();
                    tokens_to_regex(pat, opts, &mut altre);
                    if !altre.is_empty() {
                        parts.push(altre);
                    }
                }
                if !parts.is_empty() {
                    re.push('(');
                    re.push_str(&parts.join("|"));
                    re.push(')');
                }
            }
        }
    }
}

struct Parser<'a> {
    glob: &'a str,
    stack: Vec<Vec<Token>>,
    chars: std::iter::Peekable<std::str::Chars<'a>>,
    prev: Option<char>,
    cur: Option<char>,
    opts: GlobOptions,
}

fn is_separator(c: char) -> bool {
    c == '/'
}

impl<'a> Parser<'a> {
    fn error(&self, kind: GlobErrorKind) -> GlobError {
        GlobError { glob: Some(self.glob.to_string()), kind }
    }

    fn parse(&mut self) -> Result<(), GlobError> {
        while let Some(c) = self.bump() {
            match c {
                '?' => self.push_token(Token::Any)?,
                '*' => self.parse_star()?,
                '[' => self.parse_class()?,
                '{' => self.push_alternate()?,
                '}' => self.pop_alternate()?,
                ',' => self.parse_comma()?,
                '\\' => self.parse_backslash()?,
                c => self.push_token(Token::Literal(c))?,
            }
        }
        Ok(())
    }

    fn push_alternate(&mut self) -> Result<(), GlobError> {
        if self.stack.len() > 1 {
            return Err(self.error(GlobErrorKind::NestedAlternates));
        }
        self.stack.push(vec![]);
        Ok(())
    }

    fn pop_alternate(&mut self) -> Result<(), GlobError> {
        let mut alts = vec![];
        while self.stack.len() >= 2 {
            alts.push(self.stack.pop().unwrap());
        }
        self.push_token(Token::Alternates(alts))
    }

    fn push_token(&mut self, tok: Token) -> Result<(), GlobError> {
        if let Some(ref mut pat) = self.stack.last_mut() {
            pat.push(tok);
            return Ok(());
        }
        Err(self.error(GlobErrorKind::UnopenedAlternates))
    }

    fn pop_token(&mut self) -> Result<Token, GlobError> {
        if let Some(ref mut pat) = self.stack.last_mut() {
            return Ok(pat.pop().unwrap());
        }
        Err(self.error(GlobErrorKind::UnopenedAlternates))
    }

    fn have_tokens(&self) -> Result<bool, GlobError> {
        match self.stack.last() {
            None => Err(self.error(GlobErrorKind::UnopenedAlternates)),
            Some(ref pat) => Ok(!pat.is_empty()),
        }
    }

    fn parse_comma(&mut self) -> Result<(), GlobError> {
        if self.stack.len() <= 1 {
            self.push_token(Token::Literal(','))
        } else {
            self.stack.push(vec![]);
            Ok(())
        }
    }

    fn parse_backslash(&mut self) -> Result<(), GlobError> {
        if self.opts.backslash_escape {
            match self.bump() {
                None => Err(self.error(GlobErrorKind::DanglingEscape)),
                Some(c) => self.push_token(Token::Literal(c)),
            }
        } else {
            self.push_token(Token::Literal('\\'))
        }
    }

    fn parse_star(&mut self) -> Result<(), GlobError> {
        let prev = self.prev;
        if self.peek() != Some('*') {
            self.push_token(Token::ZeroOrMore)?;
            return Ok(());
        }
        assert!(self.bump() == Some('*'));
        if !self.have_tokens()? {
            if !self.peek().map_or(true, is_separator) {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
            } else {
                self.push_token(Token::RecursivePrefix)?;
                assert!(self.bump().map_or(true, is_separator));
            }
            return Ok(());
        }
        if !prev.map(is_separator).unwrap_or(false) {
            if self.stack.len() <= 1 || (prev != Some(',') && prev != Some('{')) {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
                return Ok(());
            }
        }
        let is_suffix = match self.peek() {
            None => {
                assert!(self.bump().is_none());
                true
            }
            Some(',') | Some('}') if self.stack.len() >= 2 => true,
            Some(c) if is_separator(c) => {
                assert!(self.bump().map(is_separator).unwrap_or(false));
                false
            }
            _ => {
                self.push_token(Token::ZeroOrMore)?;
                self.push_token(Token::ZeroOrMore)?;
                return Ok(());
            }
        };
        match self.pop_token()? {
            Token::RecursivePrefix => {
                self.push_token(Token::RecursivePrefix)?;
            }
            Token::RecursiveSuffix => {
                self.push_token(Token::RecursiveSuffix)?;
            }
            _ => {
                if is_suffix {
                    self.push_token(Token::RecursiveSuffix)?;
                } else {
                    self.push_token(Token::RecursiveZeroOrMore)?;
                }
            }
        }
        Ok(())
    }

    fn parse_class(&mut self) -> Result<(), GlobError> {
        fn add_to_last_range(
            glob: &str,
            r: &mut (char, char),
            add: char,
        ) -> Result<(), GlobError> {
            r.1 = add;
            if r.1 < r.0 {
                Err(GlobError {
                    glob: Some(glob.to_string()),
                    kind: GlobErrorKind::InvalidRange(r.0, r.1),
                })
            } else {
                Ok(())
            }
        }
        let mut ranges = vec![];
        let negated = match self.chars.peek() {
            Some(&'!') | Some(&'^') => {
                let bump = self.bump();
                assert!(bump == Some('!') || bump == Some('^'));
                true
            }
            _ => false,
        };
        let mut first = true;
        let mut in_range = false;
        loop {
            let c = match self.bump() {
                Some(c) => c,
                None => return Err(self.error(GlobErrorKind::UnclosedClass)),
            };
            match c {
                ']' => {
                    if first {
                        ranges.push((']', ']'));
                    } else {
                        break;
                    }
                }
                '-' => {
                    if first {
                        ranges.push(('-', '-'));
                    } else if in_range {
                        let r = ranges.last_mut().unwrap();
                        add_to_last_range(self.glob, r, '-')?;
                        in_range = false;
                    } else {
                        assert!(!ranges.is_empty());
                        in_range = true;
                    }
                }
                c => {
                    if in_range {
                        add_to_last_range(self.glob, ranges.last_mut().unwrap(), c)?;
                    } else {
                        ranges.push((c, c));
                    }
                    in_range = false;
                }
            }
            first = false;
        }
        if in_range {
            ranges.push(('-', '-'));
        }
        self.push_token(Token::Class { negated, ranges })
    }

    fn bump(&mut self) -> Option<char> {
        self.prev = self.cur;
        self.cur = self.chars.next();
        self.cur
    }

    fn peek(&mut self) -> Option<char> {
        self.chars.peek().map(|&ch| ch)
    }
}

/// A set of globs that can report all matching globs for a path.
pub struct GlobSet {
    re: Option<Regex>,
    len: usize,
}

impl GlobSet {
    pub fn empty() -> GlobSet {
        GlobSet { re: None, len: 0 }
    }

    pub fn new(globs: &[Glob]) -> Result<GlobSet, GlobError> {
        if globs.is_empty() {
            return Ok(GlobSet::empty());
        }
        let pats: Vec<&str> = globs.iter().map(|g| g.regex()).collect();
        let re = Regex::builder()
            .syntax(regex_automata::util::syntax::Config::new().utf8(false))
            .configure(
                Regex::config()
                    .utf8_empty(false)
                    .match_kind(regex_automata::MatchKind::All),
            )
            .build_many(&pats)
            .map_err(|e| GlobError { glob: None, kind: GlobErrorKind::Regex(e.to_string()) })?;
        Ok(GlobSet { re: Some(re), len: globs.len() })
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_match(&self, path: &[u8]) -> bool {
        match self.re {
            None => false,
            Some(ref re) => re.is_match(path),
        }
    }

    /// Returns the indices (ascending) of all globs that match the path.
    pub fn matches_into(&self, path: &[u8], into: &mut Vec<usize>) {
        into.clear();
        let re = match self.re {
            None => return,
            Some(ref re) => re,
        };
        let mut patset = PatternSet::new(re.pattern_len());
        re.which_overlapping_matches(&Input::new(path), &mut patset);
        for pid in patset.iter() {
            into.push(pid.as_usize());
        }
    }
}
