use crate::glob::{Glob, GlobOptions, GlobSet};

/// The result of matching a path against a set of globs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Match<T> {
    None,
    Ignore(T),
    Whitelist(T),
}

impl<T> Match<T> {
    pub fn is_none(&self) -> bool {
        matches!(*self, Match::None)
    }
    pub fn is_ignore(&self) -> bool {
        matches!(*self, Match::Ignore(_))
    }
    pub fn is_whitelist(&self) -> bool {
        matches!(*self, Match::Whitelist(_))
    }
    pub fn invert(self) -> Match<T> {
        match self {
            Match::None => Match::None,
            Match::Ignore(t) => Match::Whitelist(t),
            Match::Whitelist(t) => Match::Ignore(t),
        }
    }
    pub fn map<U, F: FnOnce(T) -> U>(self, f: F) -> Match<U> {
        match self {
            Match::None => Match::None,
            Match::Ignore(t) => Match::Ignore(f(t)),
            Match::Whitelist(t) => Match::Whitelist(f(t)),
        }
    }
    pub fn or(self, other: Match<T>) -> Match<T> {
        if self.is_none() {
            other
        } else {
            self
        }
    }
}

/// A single glob from a gitignore file.
#[derive(Debug, Clone)]
pub struct GitignoreGlob {
    pub from: Option<PathBuf>,
    pub original: String,
    pub actual: String,
    pub is_whitelist: bool,
    pub is_only_dir: bool,
}

impl GitignoreGlob {
    fn has_doublestar_prefix(&self) -> bool {
        self.actual.starts_with("**/") || self.actual == "**"
    }
}

/// An error that can occur when parsing ignore files.
#[derive(Debug, Clone)]
pub enum IgnoreError {
    Partial(Vec<IgnoreError>),
    WithLineNumber { line: u64, err: Box<IgnoreError> },
    WithPath { path: PathBuf, err: Box<IgnoreError> },
    WithDepth { depth: usize, err: Box<IgnoreError> },
    Loop { ancestor: PathBuf, child: PathBuf },
    Io(String),
    Glob { glob: Option<String>, err: String },
    UnrecognizedFileType(String),
    InvalidDefinition,
}

impl std::fmt::Display for IgnoreError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match *self {
            IgnoreError::Partial(ref errs) => {
                let msgs: Vec<String> = errs.iter().map(|err| err.to_string()).collect();
                write!(f, "{}", msgs.join("\n"))
            }
            IgnoreError::WithLineNumber { line, ref err } => {
                write!(f, "line {}: {}", line, err)
            }
            IgnoreError::WithPath { ref path, ref err } => {
                write!(f, "{}: {}", path.display(), err)
            }
            IgnoreError::WithDepth { ref err, .. } => err.fmt(f),
            IgnoreError::Loop { ref ancestor, ref child } => write!(
                f,
                "File system loop found: \
                 {} points to an ancestor {}",
                child.display(),
                ancestor.display()
            ),
            IgnoreError::Io(ref err) => err.fmt(f),
            IgnoreError::Glob { glob: None, ref err } => write!(f, "{}", err),
            IgnoreError::Glob { glob: Some(ref glob), ref err } => {
                write!(f, "error parsing glob '{}': {}", glob, err)
            }
            IgnoreError::UnrecognizedFileType(ref ty) => {
                write!(f, "unrecognized file type: {}", ty)
            }
            IgnoreError::InvalidDefinition => write!(
                f,
                "invalid definition (format is type:glob, e.g., \
                 html:*.html)"
            ),
        }
    }
}

impl IgnoreError {
    pub fn with_path<P: AsRef<Path>>(self, path: P) -> IgnoreError {
        IgnoreError::WithPath { path: path.as_ref().to_path_buf(), err: Box::new(self) }
    }
    pub fn with_line_number(self, line: u64) -> IgnoreError {
        IgnoreError::WithLineNumber { line, err: Box::new(self) }
    }
    pub fn with_depth(self, depth: usize) -> IgnoreError {
        IgnoreError::WithDepth { depth, err: Box::new(self) }
    }
    pub fn is_partial(&self) -> bool {
        matches!(*self, IgnoreError::Partial(_))
    }
    pub fn is_io(&self) -> bool {
        match *self {
            IgnoreError::Partial(ref errs) => errs.iter().any(|e| e.is_io()),
            IgnoreError::WithLineNumber { ref err, .. } => err.is_io(),
            IgnoreError::WithPath { ref err, .. } => err.is_io(),
            IgnoreError::WithDepth { ref err, .. } => err.is_io(),
            IgnoreError::Io(_) => true,
            _ => false,
        }
    }
}

/// Accumulates errors into a partial error.
#[derive(Default, Debug)]
pub struct PartialErrorBuilder(Vec<IgnoreError>);

impl PartialErrorBuilder {
    pub fn push(&mut self, err: IgnoreError) {
        self.0.push(err);
    }
    pub fn push_ignore_io(&mut self, err: IgnoreError) {
        if !err.is_io() {
            self.push(err);
        }
    }
    pub fn maybe_push(&mut self, err: Option<IgnoreError>) {
        if let Some(err) = err {
            self.push(err);
        }
    }
    pub fn maybe_push_ignore_io(&mut self, err: Option<IgnoreError>) {
        if let Some(err) = err {
            self.push_ignore_io(err);
        }
    }
    pub fn into_error_option(mut self) -> Option<IgnoreError> {
        if self.0.is_empty() {
            None
        } else if self.0.len() == 1 {
            Some(self.0.pop().unwrap())
        } else {
            Some(IgnoreError::Partial(self.0))
        }
    }
}

/// A compiled gitignore matcher.
#[derive(Debug)]
pub struct Gitignore {
    set: GlobSet,
    root: PathBuf,
    globs: Vec<GitignoreGlob>,
    num_ignores: u64,
    num_whitelists: u64,
}

impl Gitignore {
    pub fn empty() -> Gitignore {
        Gitignore {
            set: GlobSet::empty(),
            root: PathBuf::from(""),
            globs: vec![],
            num_ignores: 0,
            num_whitelists: 0,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.set.is_empty()
    }

    pub fn len(&self) -> usize {
        self.set.len()
    }

    pub fn num_ignores(&self) -> u64 {
        self.num_ignores
    }

    pub fn num_whitelists(&self) -> u64 {
        self.num_whitelists
    }

    pub fn path(&self) -> &Path {
        &self.root
    }

    pub fn matched<P: AsRef<Path>>(&self, path: P, is_dir: bool) -> Match<&GitignoreGlob> {
        if self.is_empty() {
            return Match::None;
        }
        self.matched_stripped(self.strip(path.as_ref()), is_dir)
    }

    pub fn matched_path_or_any_parents<P: AsRef<Path>>(
        &self,
        path: P,
        is_dir: bool,
    ) -> Match<&GitignoreGlob> {
        if self.is_empty() {
            return Match::None;
        }
        let mut path = self.strip(path.as_ref());
        match self.matched_stripped(path, is_dir) {
            Match::None => (),
            a_match => return a_match,
        }
        while let Some(parent) = path.parent() {
            match self.matched_stripped(parent, true) {
                Match::None => path = parent,
                a_match => return a_match,
            }
        }
        Match::None
    }

    fn matched_stripped(&self, path: &Path, is_dir: bool) -> Match<&GitignoreGlob> {
        use std::os::unix::ffi::OsStrExt;
        if self.is_empty() {
            return Match::None;
        }
        let mut matches = vec![];
        self.set.matches_into(path.as_os_str().as_bytes(), &mut matches);
        for &i in matches.iter().rev() {
            let glob = &self.globs[i];
            if !glob.is_only_dir || is_dir {
                return if glob.is_whitelist {
                    Match::Whitelist(glob)
                } else {
                    Match::Ignore(glob)
                };
            }
        }
        Match::None
    }

    fn strip<'a>(&'a self, path: &'a Path) -> &'a Path {
        let mut path = path;
        if let Some(p) = strip_prefix("./", path) {
            path = p;
        }
        if self.root != Path::new(".") && !is_file_name(path) {
            if let Some(p) = strip_prefix(&self.root, path) {
                path = p;
                if let Some(p) = strip_prefix("/", path) {
                    path = p;
                }
            }
        }
        path
    }
}

pub fn strip_prefix<'a, P: AsRef<Path> + ?Sized>(prefix: &'a P, path: &'a Path) -> Option<&'a Path> {
    use std::os::unix::ffi::OsStrExt;
    let prefix = prefix.as_ref().as_os_str().as_bytes();
    let path = path.as_os_str().as_bytes();
    if prefix.len() > path.len() || &path[..prefix.len()] != prefix {
        None
    } else {
        Some(Path::new(std::ffi::OsStr::from_bytes(&path[prefix.len()..])))
    }
}

pub fn is_file_name(path: &Path) -> bool {
    use std::os::unix::ffi::OsStrExt;
    let path = path.as_os_str().as_bytes();
    !path.contains(&b'/')
}

/// Builds a gitignore matcher.
pub struct GitignoreBuilder {
    globs: Vec<Glob>,
    gi_globs: Vec<GitignoreGlob>,
    root: PathBuf,
    case_insensitive: bool,
}

impl GitignoreBuilder {
    pub fn new<P: AsRef<Path>>(root: P) -> GitignoreBuilder {
        let root = root.as_ref();
        GitignoreBuilder {
            globs: vec![],
            gi_globs: vec![],
            root: strip_prefix("./", root).unwrap_or(root).to_path_buf(),
            case_insensitive: false,
        }
    }

    pub fn case_insensitive(&mut self, yes: bool) -> &mut GitignoreBuilder {
        self.case_insensitive = yes;
        self
    }

    pub fn build(&self) -> Result<Gitignore, IgnoreError> {
        let nignore = self.gi_globs.iter().filter(|g| !g.is_whitelist).count();
        let nwhite = self.gi_globs.iter().filter(|g| g.is_whitelist).count();
        let set = GlobSet::new(&self.globs)
            .map_err(|err| IgnoreError::Glob { glob: None, err: err.to_string() })?;
        Ok(Gitignore {
            set,
            root: self.root.clone(),
            globs: self.gi_globs.clone(),
            num_ignores: nignore as u64,
            num_whitelists: nwhite as u64,
        })
    }

    /// Add a gitignore file. Returns a (non-fatal) error if the file couldn't
    /// be read or parsed. IO errors are returned as `IgnoreError::Io`.
    pub fn add<P: AsRef<Path>>(&mut self, path: P) -> Option<IgnoreError> {
        let path = path.as_ref();
        let file = match File::open(path) {
            Err(err) => return Some(IgnoreError::Io(err.to_string()).with_path(path)),
            Ok(file) => file,
        };
        let rdr = BufReader::new(file);
        let mut errs = PartialErrorBuilder::default();
        for (i, line) in rdr.split(b'\n').enumerate() {
            let lineno = (i + 1) as u64;
            let line = match line {
                Ok(line) => line,
                Err(err) => {
                    errs.push(IgnoreError::Io(err.to_string()).with_line_number(lineno).with_path(path));
                    break;
                }
            };
            // Strip trailing CR.
            let line = if line.last() == Some(&b'\r') { &line[..line.len() - 1] } else { &line[..] };
            let line = match std::str::from_utf8(line) {
                Ok(line) => line,
                Err(_) => {
                    // Non-UTF-8 lines are skipped (lossy convert).
                    continue;
                }
            };
            if let Err(err) = self.add_line(Some(path.to_path_buf()), line) {
                errs.push(err.with_line_number(lineno).with_path(path));
            }
        }
        errs.into_error_option()
    }

    pub fn add_str(&mut self, from: Option<PathBuf>, gitignore: &str) -> Result<&mut GitignoreBuilder, IgnoreError> {
        for line in gitignore.lines() {
            self.add_line(from.clone(), line)?;
        }
        Ok(self)
    }

    pub fn add_line(&mut self, from: Option<PathBuf>, mut line: &str) -> Result<&mut GitignoreBuilder, IgnoreError> {
        if line.starts_with('#') {
            return Ok(self);
        }
        if !line.ends_with("\\ ") {
            line = line.trim_end();
        }
        if line.is_empty() {
            return Ok(self);
        }
        let mut glob = GitignoreGlob {
            from,
            original: line.to_string(),
            actual: String::new(),
            is_whitelist: false,
            is_only_dir: false,
        };
        let mut is_absolute = false;
        if line.starts_with("\\!") || line.starts_with("\\#") {
            line = &line[1..];
            is_absolute = line.starts_with('/');
        } else {
            if line.starts_with('!') {
                glob.is_whitelist = true;
                line = &line[1..];
            }
            if line.starts_with('/') {
                line = &line[1..];
                is_absolute = true;
            }
        }
        if line.as_bytes().last() == Some(&b'/') {
            glob.is_only_dir = true;
            line = &line[..line.len() - 1];
            if line.as_bytes().last() == Some(&b'\\') {
                line = &line[..line.len() - 1];
            }
        }
        glob.actual = line.to_string();
        if !is_absolute && !line.chars().any(|c| c == '/') {
            if !glob.has_doublestar_prefix() {
                glob.actual = format!("**/{}", glob.actual);
            }
        }
        if glob.actual.ends_with("/**") {
            glob.actual = format!("{}/*", glob.actual);
        }
        let opts = GlobOptions {
            case_insensitive: self.case_insensitive,
            literal_separator: true,
            backslash_escape: true,
        };
        let parsed = Glob::new(&glob.actual, opts).map_err(|err| IgnoreError::Glob {
            glob: Some(glob.original.clone()),
            err: err.kind.to_string(),
        })?;
        self.globs.push(parsed);
        self.gi_globs.push(glob);
        Ok(self)
    }
}

/// Returns the path to the global gitignore file, if any, by consulting
/// `core.excludesFile` in git's configuration.
pub fn gitconfig_excludes_path() -> Option<PathBuf> {
    // XDG config first? git uses: core.excludesFile from any config
    // (home ~/.gitconfig, then $XDG_CONFIG_HOME/git/config), falling back to
    // $XDG_CONFIG_HOME/git/ignore.
    match gitconfig_home_contents().and_then(|data| parse_excludes_file(&data)) {
        Some(path) => return Some(path),
        None => {}
    }
    match gitconfig_xdg_contents().and_then(|data| parse_excludes_file(&data)) {
        Some(path) => return Some(path),
        None => {}
    }
    excludes_file_default()
}

fn gitconfig_home_contents() -> Option<Vec<u8>> {
    let home = std::env::var_os("HOME")?;
    let mut file = PathBuf::from(home);
    file.push(".gitconfig");
    std::fs::read(file).ok()
}

fn gitconfig_xdg_contents() -> Option<Vec<u8>> {
    let path = std::env::var_os("XDG_CONFIG_HOME")
        .and_then(|x| if x.is_empty() { None } else { Some(PathBuf::from(x)) })
        .or_else(|| std::env::var_os("HOME").map(|p| PathBuf::from(p).join(".config")))
        .map(|x| x.join("git/config"));
    path.and_then(|p| std::fs::read(p).ok())
}

fn excludes_file_default() -> Option<PathBuf> {
    std::env::var_os("XDG_CONFIG_HOME")
        .and_then(|x| if x.is_empty() { None } else { Some(PathBuf::from(x)) })
        .or_else(|| std::env::var_os("HOME").map(|p| PathBuf::from(p).join(".config")))
        .map(|x| x.join("git/ignore"))
}

fn parse_excludes_file(data: &[u8]) -> Option<PathBuf> {
    use std::os::unix::ffi::OsStrExt;
    // Find `excludesfile = <value>` within a `[core]` section (case-insensitive
    // key). This mimics the regex used by the ignore crate:
    // (?xim-u)^[[:space:]]*excludesfile[[:space:]]*=[[:space:]]*(?P<value>[^\n]*?)[[:space:]]*$
    let mut result = None;
    for line in data.split(|&b| b == b'\n') {
        let trimmed = trim_ascii_space(line);
        let lower: Vec<u8> = trimmed.iter().map(|b| b.to_ascii_lowercase()).collect();
        if !lower.starts_with(b"excludesfile") {
            continue;
        }
        let rest = trim_ascii_space(&trimmed[b"excludesfile".len()..]);
        if !rest.starts_with(b"=") {
            continue;
        }
        let value = trim_ascii_space(&rest[1..]);
        if value.is_empty() {
            continue;
        }
        let path = expand_tilde(std::ffi::OsStr::from_bytes(value));
        result = Some(path);
    }
    result
}

fn trim_ascii_space(mut b: &[u8]) -> &[u8] {
    while let Some((&f, rest)) = b.split_first() {
        if f.is_ascii_whitespace() {
            b = rest;
        } else {
            break;
        }
    }
    while let Some((&l, rest)) = b.split_last() {
        if l.is_ascii_whitespace() {
            b = rest;
        } else {
            break;
        }
    }
    b
}

fn expand_tilde(path: &std::ffi::OsStr) -> PathBuf {
    use std::os::unix::ffi::{OsStrExt, OsStringExt};
    let bytes = path.as_bytes();
    if bytes.starts_with(b"~") {
        if let Some(home) = std::env::var_os("HOME") {
            let mut out = home.into_vec();
            out.extend_from_slice(&bytes[1..]);
            return PathBuf::from(std::ffi::OsString::from_vec(out));
        }
    }
    PathBuf::from(path)
}

/// Options for building a glob set for the gitignore file(s).
pub fn gitignore_from_file(dir: &Path, name: &str, case_insensitive: bool) -> (Gitignore, Option<IgnoreError>) {
    let mut builder = GitignoreBuilder::new(dir);
    builder.case_insensitive(case_insensitive);
    let mut errs = PartialErrorBuilder::default();
    let gipath = dir.join(name);
    // Only add the file if it exists, to avoid IO errors. (Mimics
    // `if gipath.exists()`.)
    if gipath.exists() {
        errs.maybe_push_ignore_io(builder.add(gipath));
    }
    let gi = match builder.build() {
        Ok(gi) => gi,
        Err(err) => {
            errs.push(err);
            Gitignore::empty()
        }
    };
    (gi, errs.into_error_option())
}

/// Builds the global gitignore matcher.
pub fn gitignore_global(case_insensitive: bool) -> (Gitignore, Option<IgnoreError>) {
    let mut builder = GitignoreBuilder::new("");
    builder.case_insensitive(case_insensitive);
    let mut errs = PartialErrorBuilder::default();
    let path = match gitconfig_excludes_path() {
        None => return (Gitignore::empty(), None),
        Some(path) => path,
    };
    if !path.is_file() {
        return (Gitignore::empty(), None);
    }
    errs.maybe_push_ignore_io(builder.add(path));
    match builder.build() {
        Ok(gi) => (gi, errs.into_error_option()),
        Err(err) => {
            errs.push(err);
            (Gitignore::empty(), errs.into_error_option())
        }
    }
}
