                    return Err(IgnoreError::InvalidDefinition);
                }
                for type_name in types {
                    let globs = self.types.get(type_name).unwrap().globs.clone();
                    for glob in globs {
                        self.add(name, &glob)?;
                    }
                }
                Ok(())
            }
            _ => Err(IgnoreError::InvalidDefinition),
        }
    }

    pub fn add_defaults(&mut self) -> &mut TypesBuilder {
        for line in DEFAULT_TYPES.lines() {
            let (name, globs) = match line.split_once(": ") {
                Some(x) => x,
                None => continue,
            };
            for glob in globs.split(", ") {
                self.add(name, glob).expect("valid default type");
            }
        }
