//! File type definitions and matching.

use std::collections::HashMap;
use std::path::Path;

use crate::gitignore::{IgnoreError, Match};
use crate::glob::{Glob, GlobOptions, GlobSet};

static DEFAULT_TYPES: &str = include_str!("../data/types.txt");

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileTypeDef {
    name: String,
    globs: Vec<String>,
}

impl FileTypeDef {
    pub fn name(&self) -> &str {
        &self.name
    }
    pub fn globs(&self) -> &[String] {
        &self.globs
    }
}

#[derive(Debug, Clone)]
enum Selection<T> {
    Select(String, T),
    Negate(String, T),
}

impl<T> Selection<T> {
    fn is_negated(&self) -> bool {
        matches!(*self, Selection::Negate(..))
    }
    fn name(&self) -> &str {
        match *self {
            Selection::Select(ref name, _) => name,
            Selection::Negate(ref name, _) => name,
        }
    }
    fn inner(&self) -> &T {
        match *self {
            Selection::Select(_, ref inner) => inner,
            Selection::Negate(_, ref inner) => inner,
        }
    }
}

/// A compiled set of file type selections.
#[derive(Debug)]
pub struct Types {
    defs: Vec<FileTypeDef>,
    selections: Vec<Selection<FileTypeDef>>,
    has_selected: bool,
    glob_to_selection: Vec<(usize, usize)>,
    set: GlobSet,
}

#[derive(Debug, Clone)]
pub struct TypeGlob {
    pub def_name: String,
    pub glob: String,
    pub negated: bool,
}

impl Types {
    pub fn empty() -> Types {
        Types {
            defs: vec![],
            selections: vec![],
            has_selected: false,
            glob_to_selection: vec![],
            set: GlobSet::empty(),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.set.is_empty()
    }

    pub fn len(&self) -> usize {
        self.set.len()
    }

    pub fn definitions(&self) -> &[FileTypeDef] {
        &self.defs
    }

    pub fn matched<P: AsRef<Path>>(&self, path: P, is_dir: bool) -> Match<TypeGlob> {
        use std::os::unix::ffi::OsStrExt;
        if is_dir || self.set.is_empty() {
            return Match::None;
        }
        let name = match path.as_ref().file_name() {
            Some(name) => name,
            None if self.has_selected => {
                return Match::Ignore(TypeGlob {
                    def_name: String::new(),
                    glob: String::new(),
                    negated: false,
                })
            }
            None => return Match::None,
        };
        let mut matches = vec![];
        self.set.matches_into(name.as_bytes(), &mut matches);
        if let Some(&i) = matches.last() {
            let (isel, iglob) = self.glob_to_selection[i];
            let sel = &self.selections[isel];
            let glob = TypeGlob {
                def_name: sel.inner().name.clone(),
                glob: sel.inner().globs[iglob].clone(),
                negated: sel.is_negated(),
            };
            return if sel.is_negated() { Match::Ignore(glob) } else { Match::Whitelist(glob) };
        }
        if self.has_selected {
            Match::Ignore(TypeGlob { def_name: String::new(), glob: String::new(), negated: false })
        } else {
            Match::None
        }
    }
}

/// Builds file type matchers.
#[derive(Debug, Clone)]
pub struct TypesBuilder {
    types: HashMap<String, FileTypeDef>,
    selections: Vec<Selection<()>>,
}

impl TypesBuilder {
    pub fn new() -> TypesBuilder {
        TypesBuilder { types: HashMap::new(), selections: vec![] }
    }

    pub fn build(&self) -> Result<Types, IgnoreError> {
        let defs = self.definitions();
        let has_selected = self.selections.iter().any(|s| !s.is_negated());
        let mut selections = vec![];
        let mut glob_to_selection = vec![];
        let mut globs = vec![];
        for (isel, selection) in self.selections.iter().enumerate() {
            let def = match self.types.get(selection.name()) {
                Some(def) => def.clone(),
                None => {
                    let name = selection.name().to_string();
                    return Err(IgnoreError::UnrecognizedFileType(name));
                }
            };
            for (iglob, glob) in def.globs.iter().enumerate() {
                globs.push(Glob::new(glob, GlobOptions::new()).map_err(|err| {
                    IgnoreError::Glob { glob: Some(glob.to_string()), err: err.kind.to_string() }
                })?);
                glob_to_selection.push((isel, iglob));
            }
            selections.push(match *selection {
                Selection::Select(ref name, _) => Selection::Select(name.clone(), def),
                Selection::Negate(ref name, _) => Selection::Negate(name.clone(), def),
            });
        }
        let set = GlobSet::new(&globs)
            .map_err(|err| IgnoreError::Glob { glob: None, err: err.to_string() })?;
        Ok(Types { defs, selections, has_selected, glob_to_selection, set })
    }

    /// Return the currently defined types, sorted by name (with globs sorted).
    pub fn definitions(&self) -> Vec<FileTypeDef> {
        let mut defs = vec![];
