//! Directory-level ignore matcher chain (gitignore, .ignore, overrides, types).

use std::collections::HashMap;
use std::ffi::{OsStr, OsString};
use std::fs::{File, FileType};
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};

use crate::gitignore::{
    gitignore_global, strip_prefix, Gitignore, GitignoreBuilder, IgnoreError, Match,
    PartialErrorBuilder,
};
use crate::types::Types;

/// Overrides from -g/--glob and --iglob.
#[derive(Debug)]
pub struct Override(Gitignore);

impl Override {
    pub fn empty() -> Override {
        Override(Gitignore::empty())
    }
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
    pub fn num_ignores(&self) -> u64 {
        self.0.num_whitelists()
    }
    pub fn num_whitelists(&self) -> u64 {
        self.0.num_ignores()
    }
    pub fn matched<P: AsRef<Path>>(&self, path: P, is_dir: bool) -> Match<()> {
        if self.is_empty() {
            return Match::None;
        }
        let mat = self.0.matched(path, is_dir).invert();
        if mat.is_none() && self.num_whitelists() > 0 && !is_dir {
            return Match::Ignore(());
        }
        mat.map(|_| ())
    }
}

pub struct OverrideBuilder {
    builder: GitignoreBuilder,
}

impl OverrideBuilder {
    pub fn new<P: AsRef<Path>>(path: P) -> OverrideBuilder {
        OverrideBuilder { builder: GitignoreBuilder::new(path) }
    }
    pub fn build(&self) -> Result<Override, IgnoreError> {
        Ok(Override(self.builder.build()?))
    }
    pub fn add(&mut self, glob: &str) -> Result<&mut OverrideBuilder, IgnoreError> {
        self.builder.add_line(None, glob)?;
        Ok(self)
    }
    pub fn case_insensitive(&mut self, yes: bool) -> &mut OverrideBuilder {
        self.builder.case_insensitive(yes);
        self
    }
}

#[derive(Debug, Clone, Copy)]
pub struct IgnoreOptions {
    pub hidden: bool,
    pub ignore: bool,
    pub parents: bool,
    pub git_global: bool,
    pub git_ignore: bool,
    pub git_exclude: bool,
    pub ignore_case_insensitive: bool,
    pub require_git: bool,
}

impl IgnoreOptions {
    fn has_any_ignore_options(&self) -> bool {
        self.ignore || self.git_global || self.git_ignore || self.git_exclude
    }
}

/// Describes what matched (for debug output).
#[derive(Debug, Clone)]
pub enum IgnoreMatchKind {
    Override,
    Gitignore(String),
    Types(String),
    Hidden,
}

#[derive(Debug, Clone)]
pub struct Ignore(Arc<IgnoreInner>);

#[derive(Debug)]
struct IgnoreInner {
    compiled: Arc<RwLock<HashMap<OsString, Ignore>>>,
    dir: PathBuf,
    overrides: Arc<Override>,
    types: Arc<Types>,
    parent: Option<Ignore>,
    is_absolute_parent: bool,
    absolute_base: Option<Arc<PathBuf>>,
    explicit_ignores: Arc<Vec<Gitignore>>,
    custom_ignore_filenames: Arc<Vec<OsString>>,
    custom_ignore_matcher: Gitignore,
    ignore_matcher: Gitignore,
    git_global_matcher: Arc<Gitignore>,
    git_ignore_matcher: Gitignore,
    git_exclude_matcher: Gitignore,
    has_git: bool,
    opts: IgnoreOptions,
}

impl Ignore {
    pub fn path(&self) -> &Path {
        &self.0.dir
    }

    pub fn is_root(&self) -> bool {
        self.0.parent.is_none()
    }

    pub fn is_absolute_parent(&self) -> bool {
        self.0.is_absolute_parent
    }

    pub fn parent(&self) -> Option<Ignore> {
        self.0.parent.clone()
    }

    /// Create a new Ignore matcher with the parent directories of `dir`.
    pub fn add_parents<P: AsRef<Path>>(&self, path: P) -> (Ignore, Option<IgnoreError>) {
        if !self.0.opts.parents
            && !self.0.opts.git_ignore
            && !self.0.opts.git_exclude
            && !self.0.opts.git_global
        {
            return (self.clone(), None);
        }
        let absolute_base = match path.as_ref().canonicalize() {
            Ok(path) => Arc::new(path),
            Err(_) => return (self.clone(), None),
        };
        let mut errs = PartialErrorBuilder::default();
        let mut ig = self.clone();
        for parent in absolute_base.ancestors().skip(1) {
            {
                let compiled = self.0.compiled.read().unwrap();
                if let Some(prebuilt) = compiled.get(parent.as_os_str()) {
                    ig = prebuilt.clone();
                    continue;
                }
            }
            let (mut igtmp, err) = ig.add_child_path(parent);
            errs.maybe_push(err);
            igtmp.is_absolute_parent = true;
            igtmp.absolute_base = Some(absolute_base.clone());
            igtmp.has_git = if self.0.opts.require_git && self.0.opts.git_ignore {
                parent.join(".git").exists()
            } else {
                false
            };
            let ig_arc = Ignore(Arc::new(igtmp));
            ig = ig_arc.clone();
            let mut compiled = self.0.compiled.write().unwrap();
            compiled.insert(parent.as_os_str().to_os_string(), ig_arc);
        }
        (ig, errs.into_error_option())
    }

    /// Create a new Ignore matcher for the given child directory.
    pub fn add_child<P: AsRef<Path>>(&self, dir: P) -> (Ignore, Option<IgnoreError>) {
        let (ig, err) = self.add_child_path(dir.as_ref());
        (Ignore(Arc::new(ig)), err)
    }

    fn add_child_path(&self, dir: &Path) -> (IgnoreInner, Option<IgnoreError>) {
        let git_type = if self.0.opts.require_git
            && (self.0.opts.git_ignore || self.0.opts.git_exclude)
        {
            dir.join(".git").metadata().ok().map(|md| md.file_type())
        } else {
            None
        };
        let has_git = git_type.is_some();
        let mut errs = PartialErrorBuilder::default();
        let custom_ig_matcher = if self.0.custom_ignore_filenames.is_empty() {
            Gitignore::empty()
        } else {
            let (m, err) = create_gitignore(
                dir,
                dir,
                &self.0.custom_ignore_filenames,
                self.0.opts.ignore_case_insensitive,
            );
            errs.maybe_push(err);
            m
        };
        let ig_matcher = if !self.0.opts.ignore {
            Gitignore::empty()
        } else {
            let (m, err) = create_gitignore(
                dir,
                dir,
                &[OsString::from(".ignore")],
                self.0.opts.ignore_case_insensitive,
            );
            errs.maybe_push(err);
            m
        };
        let gi_matcher = if !self.0.opts.git_ignore {
            Gitignore::empty()
        } else {
            let (m, err) = create_gitignore(
                dir,
                dir,
                &[OsString::from(".gitignore")],
                self.0.opts.ignore_case_insensitive,
            );
            errs.maybe_push(err);
            m
        };
        let gi_exclude_matcher = if !self.0.opts.git_exclude {
            Gitignore::empty()
        } else {
            match resolve_git_commondir(dir, git_type) {
                Ok(git_dir) => {
                    let (m, err) = create_gitignore(
                        dir,
                        &git_dir,
                        &[OsString::from("info/exclude")],
                        self.0.opts.ignore_case_insensitive,
                    );
                    errs.maybe_push(err);
                    m
                }
                Err(err) => {
                    errs.maybe_push(err);
                    Gitignore::empty()
                }
            }
        };
        let ig = IgnoreInner {
            compiled: self.0.compiled.clone(),
            dir: dir.to_path_buf(),
            overrides: self.0.overrides.clone(),
            types: self.0.types.clone(),
            parent: Some(self.clone()),
            is_absolute_parent: false,
            absolute_base: self.0.absolute_base.clone(),
            explicit_ignores: self.0.explicit_ignores.clone(),
            custom_ignore_filenames: self.0.custom_ignore_filenames.clone(),
            custom_ignore_matcher: custom_ig_matcher,
            ignore_matcher: ig_matcher,
            git_global_matcher: self.0.git_global_matcher.clone(),
            git_ignore_matcher: gi_matcher,
            git_exclude_matcher: gi_exclude_matcher,
            has_git,
            opts: self.0.opts,
        };
        (ig, errs.into_error_option())
    }

    fn has_any_ignore_rules(&self) -> bool {
        let opts = self.0.opts;
        let has_custom_ignore_files = !self.0.custom_ignore_filenames.is_empty();
        let has_explicit_ignores = !self.0.explicit_ignores.is_empty();
        opts.ignore
            || opts.git_global
            || opts.git_ignore
            || opts.git_exclude
            || has_custom_ignore_files
            || has_explicit_ignores
    }

    /// Returns a match for the given path. Also checks hidden-ness.
    pub fn matched_dir_entry(&self, path: &Path, is_dir: bool, is_hidden: bool) -> Match<IgnoreMatchKind> {
        let m = self.matched(path, is_dir);
        if m.is_none() && self.0.opts.hidden && is_hidden {
            return Match::Ignore(IgnoreMatchKind::Hidden);
        }
        m
    }

    pub fn matched<P: AsRef<Path>>(&self, path: P, is_dir: bool) -> Match<IgnoreMatchKind> {
        let mut path = path.as_ref();
        if let Some(p) = strip_prefix("./", path) {
            path = p;
        }
        if !self.0.overrides.is_empty() {
            let mat = self.0.overrides.matched(path, is_dir).map(|_| IgnoreMatchKind::Override);
            if !mat.is_none() {
                return mat;
            }
        }
        let mut whitelisted = Match::None;
        if self.has_any_ignore_rules() {
            let mat = self.matched_ignore(path, is_dir);
            if mat.is_ignore() {
                return mat;
            } else if mat.is_whitelist() {
                whitelisted = mat;
            }
        }
        if !self.0.types.is_empty() {
            let mat = self
                .0
                .types
                .matched(path, is_dir)
                .map(|g| IgnoreMatchKind::Types(format!("{:?}", g)));
            if mat.is_ignore() {
                return mat;
            } else if mat.is_whitelist() {
                whitelisted = mat;
            }
        }
        whitelisted
    }

    fn matched_ignore(&self, path: &Path, is_dir: bool) -> Match<IgnoreMatchKind> {
        let (mut m_custom_ignore, mut m_ignore, mut m_gi, mut m_gi_exclude, mut m_explicit) =
            (Match::None, Match::None, Match::None, Match::None, Match::None);
        let any_git = !self.0.opts.require_git || self.parents().any(|ig| ig.0.has_git);
        let mut saw_git = false;
        for ig in self.parents().take_while(|ig| !ig.0.is_absolute_parent) {
            if m_custom_ignore.is_none() {
                m_custom_ignore = ig.0.custom_ignore_matcher.matched(path, is_dir).map(gi_kind);
            }
            if m_ignore.is_none() {
                m_ignore = ig.0.ignore_matcher.matched(path, is_dir).map(gi_kind);
            }
            if any_git && !saw_git && m_gi.is_none() {
                m_gi = ig.0.git_ignore_matcher.matched(path, is_dir).map(gi_kind);
            }
            if any_git && !saw_git && m_gi_exclude.is_none() {
                m_gi_exclude = ig.0.git_exclude_matcher.matched(path, is_dir).map(gi_kind);
            }
            saw_git = saw_git || ig.0.has_git;
        }
        if self.0.opts.parents {
            if let Some(abs_parent_path) = self.absolute_base() {
                let path = abs_parent_path.join(path);
                for ig in self.parents().skip_while(|ig| !ig.0.is_absolute_parent) {
                    if m_custom_ignore.is_none() {
                        m_custom_ignore =
                            ig.0.custom_ignore_matcher.matched(&path, is_dir).map(gi_kind);
                    }
                    if m_ignore.is_none() {
                        m_ignore = ig.0.ignore_matcher.matched(&path, is_dir).map(gi_kind);
                    }
                    if any_git && !saw_git && m_gi.is_none() {
                        m_gi = ig.0.git_ignore_matcher.matched(&path, is_dir).map(gi_kind);
                    }
                    if any_git && !saw_git && m_gi_exclude.is_none() {
                        m_gi_exclude =
                            ig.0.git_exclude_matcher.matched(&path, is_dir).map(gi_kind);
                    }
                    saw_git = saw_git || ig.0.has_git;
                }
            }
        }
        for gi in self.0.explicit_ignores.iter().rev() {
            if !m_explicit.is_none() {
                break;
            }
            m_explicit = gi.matched(path, is_dir).map(gi_kind);
        }
        let m_global = if any_git {
            self.0.git_global_matcher.matched(path, is_dir).map(gi_kind)
        } else {
            Match::None
        };
        m_custom_ignore.or(m_ignore).or(m_gi).or(m_gi_exclude).or(m_global).or(m_explicit)
    }

    fn parents(&self) -> Parents<'_> {
        Parents(Some(self))
    }

    fn absolute_base(&self) -> Option<&Path> {
