}

fn gi_kind(g: &crate::gitignore::GitignoreGlob) -> IgnoreMatchKind {
    IgnoreMatchKind::Gitignore(format!(
        "Glob {{ from: {:?}, original: {:?}, actual: {:?}, is_whitelist: {}, is_only_dir: {} }}",
