fn describe_match(m: &crate::gitignore::Match<crate::ignore::IgnoreMatchKind>) -> String {
    use crate::gitignore::Match;
    use crate::ignore::IgnoreMatchKind;
    let inner = |k: &IgnoreMatchKind| -> String {
        match k {
            IgnoreMatchKind::Override => "Override(Glob(Matched(...)))".to_string(),
            IgnoreMatchKind::Gitignore(g) => format!("Gitignore({})", g),
            IgnoreMatchKind::Types(t) => format!("Types({})", t),
            IgnoreMatchKind::Hidden => "Hidden".to_string(),
        }
    };
    match m {
        Match::None => "None".to_string(),
        Match::Ignore(k) => format!("Ignore(IgnoreMatch({}))", inner(k)),
        Match::Whitelist(k) => format!("Whitelist(IgnoreMatch({}))", inner(k)),
