/// Read and (optionally) sort the entries of a directory.
fn read_dir_entries(
    path: &Path,
    depth: usize,
    follow_links: bool,
    sorter: &Option<Sorter>,
) -> Result<Vec<Result<DirEntry, WalkError>>, WalkError> {
    let rd = fs::read_dir(path).map_err(|err| WalkError::with_path(depth, path.to_path_buf(), err))?;
    let mut entries: Vec<Result<DirEntry, WalkError>> = vec![];
    for ent in rd {
        match ent {
            Err(err) => entries.push(Err(WalkError::with_path(depth, path.to_path_buf(), err))),
            Ok(ent) => {
                use std::os::unix::fs::DirEntryExt;
                let ft = match ent.file_type() {
                    Ok(ft) => ft,
                    Err(err) => {
                        entries.push(Err(WalkError::with_path(depth, ent.path(), err)));
                        continue;
                    }
                };
                let dent = DirEntry {
                    path: ent.path(),
                    file_type: Some(ft),
                    depth,
                    path_is_symlink: ft.is_symlink(),
                    follow_link: false,
                    ino: ent.ino(),
                    err: None,
                    is_stdin: false,
                };
                entries.push(Ok(dent));
            }
        }
    }
    let _ = follow_links;
    if let Some(Sorter::ByName(cmp)) = sorter {
        entries.sort_by(|a, b| match (a, b) {
            (Ok(a), Ok(b)) => cmp(a.file_name().unwrap_or_default(), b.file_name().unwrap_or_default()),
            (Ok(_), Err(_)) => std::cmp::Ordering::Less,
            (Err(_), Ok(_)) => std::cmp::Ordering::Greater,
            (Err(_), Err(_)) => std::cmp::Ordering::Equal,
        });
    }
    Ok(entries)
}

/// Follow a symlink entry, checking for loops against the ancestor stack.
fn follow_symlink(
    dent: DirEntry,
    ancestors: &[(PathBuf, u64, u64)],
) -> Result<DirEntry, WalkError> {
    use std::os::unix::fs::MetadataExt;
    let depth = dent.depth;
    let md = fs::metadata(&dent.path)
        .map_err(|err| WalkError::with_path(depth, dent.path.clone(), err))?;
    let new = DirEntry {
        path: dent.path,
        file_type: Some(md.file_type()),
        depth,
        path_is_symlink: true,
        follow_link: true,
        ino: md.ino(),
        err: None,
        is_stdin: false,
    };
    if md.file_type().is_dir() {
        // Loop check.
        let (dev, ino) = (md.dev(), md.ino());
        for (apath, adev, aino) in ancestors.iter().rev() {
            if *adev == dev && *aino == ino {
                return Err(WalkError {
                    depth,
                    inner: WalkErrorInner::Loop { ancestor: apath.clone(), child: new.path.clone() },
                });
            }
        }
    }
    Ok(new)
}

struct Frame {
    entries: std::vec::IntoIter<Result<DirEntry, WalkError>>,
    ig: Ignore,
    /// (path, dev, ino) of this directory for loop detection.
    ancestor: (PathBuf, u64, u64),
}

/// A sequential walker.
pub struct Walk {
    paths: std::vec::IntoIter<PathBuf>,
    ig_root: Ignore,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    sorter: Option<Sorter>,
    skip: Option<Arc<StdoutHandle>>,
    stack: Vec<Frame>,
    root_device: Option<u64>,
    cur_ig: Option<Ignore>,
    pending_root: Option<PathBuf>,
}

impl Walk {
    fn ancestors(&self) -> Vec<(PathBuf, u64, u64)> {
        self.stack.iter().map(|f| f.ancestor.clone()).collect()
    }

    /// Push a directory frame for `dent` (already determined to be a dir).
    fn push_dir(&mut self, dent: &DirEntry, ig: Ignore) -> Option<WalkError> {
        use std::os::unix::fs::MetadataExt;
        let depth = dent.depth + 1;
        if let Some(md) = self.max_depth {
            if depth > md {
                // Don't descend, but we still need a frame to pop ig? No:
                // we never pushed, so just return.
                return None;
            }
        }
        let (dev, ino) = match fs::metadata(dent.path()) {
            Ok(md) => (md.dev(), md.ino()),
            Err(_) => (0, 0),
        };
        match read_dir_entries(dent.path(), depth, self.follow_links, &self.sorter) {
            Ok(entries) => {
                self.stack.push(Frame {
                    entries: entries.into_iter(),
                    ig,
                    ancestor: (dent.path().to_path_buf(), dev, ino),
                });
                None
            }
            Err(err) => Some(err),
        }
    }
}

impl Iterator for Walk {
    type Item = Result<DirEntry, IgnoreError>;

    fn next(&mut self) -> Option<Result<DirEntry, IgnoreError>> {
        loop {
            // Process the top frame.
            if let Some(frame) = self.stack.last_mut() {
                let next = frame.entries.next();
                let ig = frame.ig.clone();
                match next {
                    None => {
                        self.stack.pop();
                        continue;
                    }
                    Some(Err(err)) => return Some(Err(err.into_ignore_error())),
                    Some(Ok(mut dent)) => {
                        // Follow symlinks if requested.
                        if self.follow_links && dent.file_type.map_or(false, |ft| ft.is_symlink()) {
                            let ancestors = self.ancestors();
                            dent = match follow_symlink(dent, &ancestors) {
                                Ok(d) => d,
                                Err(err) => return Some(Err(err.into_ignore_error())),
                            };
                        }
                        let is_dir = dent.is_dir();
                        if is_dir {
                            if let Ok(should_skip) = skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                if should_skip {
                                    continue;
                                }
                            } else if let Err(err) = skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                return Some(Err(err));
                            }
                            // same file system check
                            if self.same_file_system {
                                if let Some(root_dev) = self.root_device {
                                    match device_num(dent.path()) {
                                        Ok(dev) => {
                                            if dev != root_dev {
                                                // Don't descend, but still yield? walkdir yields the dir entry.
                                                let (igtmp, err) = ig.add_child(dent.path());
                                                let _ = igtmp;
                                                dent.err = err;
                                                return Some(Ok(dent));
                                            }
                                        }
                                        Err(err) => {
                                            return Some(Err(WalkError::with_path(dent.depth, dent.path.clone(), err).into_ignore_error()));
                                        }
                                    }
                                }
                            }
                            let (igtmp, err) = ig.add_child(dent.path());
                            dent.err = err;
                            if let Some(werr) = self.push_dir(&dent, igtmp) {
                                // Yield the dir entry first, then the error.
                                self.cur_ig = None;
                                let e = werr.into_ignore_error();
                                // We emulate walkdir: the directory entry is yielded,
                                // then the read_dir error on the next call.
                                self.pending_err = Some(e);
                                return Some(Ok(dent));
                            }
                            return Some(Ok(dent));
                        } else {
                            match skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                Err(err) => return Some(Err(err)),
                                Ok(true) => continue,
                                Ok(false) => return Some(Ok(dent)),
                            }
                        }
                    }
                }
            }
            if let Some(err) = self.pending_err.take() {
                return Some(Err(err));
            }
            // Start the next root path.
            let path = match self.paths.next() {
                None => return None,
                Some(path) => path,
            };
            if path == Path::new("-") {
                return Some(Ok(DirEntry::new_stdin()));
            }
            self.root_device = None;
            if self.same_file_system {
                match device_num(&path) {
                    Ok(dev) => self.root_device = Some(dev),
                    Err(err) => {
                        return Some(Err(WalkError::with_path(0, path.clone(), err).into_ignore_error()));
                    }
                }
            }
            let follow_root = self.follow_links || path.is_file();
            let dent = match DirEntry::from_path(0, path.clone(), false) {
                Ok(d) => d,
                Err(err) => return Some(Err(err.into_ignore_error())),
            };
            // Determine the ignore matcher for this root.
            let ig = if path.is_dir() {
                let (ig, err) = self.ig_root.add_parents(&path);
                if let Some(err) = err {
                    // Yield the error, but we must still process the path.
                    self.pending_root = Some(path.clone());
                    self.cur_ig = Some(ig);
                    return Some(Err(err));
                }
                ig
            } else {
                self.ig_root.clone()
            };
            if let Some(r) = self.start_root(dent, ig, follow_root) {
                return Some(r);
            }
        }
    }
}

impl Walk {
    fn start_root(
        &mut self,
        mut dent: DirEntry,
        ig: Ignore,
        follow_root: bool,
    ) -> Option<Result<DirEntry, IgnoreError>> {
        // Root symlinks are always followed.
        let is_symlink = dent.file_type.map_or(false, |ft| ft.is_symlink());
        if is_symlink {
            match fs::metadata(dent.path()) {
                Ok(md) => {
                    use std::os::unix::fs::MetadataExt;
                    if follow_root {
                        dent.file_type = Some(md.file_type());
                        dent.follow_link = true;
                        dent.ino = md.ino();
                    }
                    if md.file_type().is_dir() {
                        let (igtmp, err) = ig.add_child(dent.path());
                        dent.err = err;
                        // Make the entry look like a directory for consumers.
                        dent.file_type = Some(md.file_type());
                        if let Some(werr) = self.push_dir(&dent, igtmp) {
                            self.pending_err = Some(werr.into_ignore_error());
                        }
                        return Some(Ok(dent));
                    }
                    return Some(Ok(dent));
                }
                Err(err) => {
                    return Some(Err(WalkError::with_path(0, dent.path.clone(), err).into_ignore_error()));
                }
            }
        }
        if dent.is_dir() {
            let (igtmp, err) = ig.add_child(dent.path());
            dent.err = err;
            if let Some(werr) = self.push_dir(&dent, igtmp) {
                self.pending_err = Some(werr.into_ignore_error());
            }
            return Some(Ok(dent));
        }
        Some(Ok(dent))
    }
}

/// Parallel walker.
pub struct WalkParallel {
    paths: Vec<PathBuf>,
    ig_root: Ignore,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    skip: Option<Arc<StdoutHandle>>,
    threads: usize,
}

/// A visitor for the parallel walker.
pub trait ParallelVisitor: Send {
    fn visit(&mut self, entry: Result<DirEntry, IgnoreError>) -> WalkState;
}

pub trait ParallelVisitorBuilder<'s> {
    fn build(&mut self) -> Box<dyn ParallelVisitor + 's>;
}

struct Work {
    dent: DirEntry,
    ig: Ignore,
    root_device: Option<u64>,
    ancestors: Arc<Vec<(PathBuf, u64, u64)>>,
}

struct Shared {
    stack: Mutex<Vec<Work>>,
    cond: Condvar,
    active: AtomicUsize,
    quit: AtomicBool,
}

impl WalkParallel {
    pub fn threads(&self) -> usize {
        if self.threads == 0 {
            2
        } else {
            self.threads
        }
    }

    pub fn visit(self, builder: &mut dyn ParallelVisitorBuilder<'_>) {
        let threads = self.threads();
        let shared = Arc::new(Shared {
            stack: Mutex::new(vec![]),
            cond: Condvar::new(),
            active: AtomicUsize::new(0),
            quit: AtomicBool::new(false),
        });
        // Seed the stack with roots, processing roots sequentially through a
        // single visitor first (errors and files).
        {
            let mut visitor = builder.build();
            let mut stack = vec![];
            for path in self.paths.iter() {
                if path == Path::new("-") {
                    if visitor.visit(Ok(DirEntry::new_stdin())) == WalkState::Quit {
                        shared.quit.store(true, Ordering::SeqCst);
                        break;
                    }
                    continue;
                }
                let mut root_device = None;
                if self.same_file_system {
                    match device_num(path) {
                        Ok(dev) => root_device = Some(dev),
                        Err(err) => {
                            if visitor.visit(Err(
                                WalkError::with_path(0, path.clone(), err).into_ignore_error(),
                            )) == WalkState::Quit
                            {
                                shared.quit.store(true, Ordering::SeqCst);
                                break;
                            }
                            continue;
                        }
                    }
                }
                let dent = match DirEntry::from_path(0, path.clone(), false) {
                    Ok(d) => d,
                    Err(err) => {
                        if visitor.visit(Err(err.into_ignore_error())) == WalkState::Quit {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                        continue;
                    }
                };
                let ig = if path.is_dir() {
                    let (ig, err) = self.ig_root.add_parents(path);
                    if let Some(err) = err {
                        if visitor.visit(Err(err)) == WalkState::Quit {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                    }
                    ig
                } else {
                    self.ig_root.clone()
                };
                // Resolve root symlinks.
                let mut dent = dent;
                let is_symlink = dent.file_type.map_or(false, |ft| ft.is_symlink());
                let follow_root = self.follow_links || path.is_file();
                if is_symlink {
                    match fs::metadata(dent.path()) {
                        Ok(md) => {
                            use std::os::unix::fs::MetadataExt;
                            if follow_root || md.file_type().is_dir() {
                                dent.file_type = Some(md.file_type());
                                dent.follow_link = follow_root;
                                dent.ino = md.ino();
                            }
                        }
                        Err(err) => {
                            if visitor.visit(Err(
                                WalkError::with_path(0, dent.path.clone(), err).into_ignore_error(),
                            )) == WalkState::Quit
                            {
                                shared.quit.store(true, Ordering::SeqCst);
                                break;
                            }
                            continue;
                        }
                    }
                }
                if dent.is_dir() {
                    let (igtmp, err) = ig.add_child(dent.path());
                    dent.err = err;
                    let state = visitor.visit(Ok(dent.clone()));
                    match state {
                        WalkState::Quit => {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                        WalkState::Skip => continue,
                        WalkState::Continue => {}
                    }
                    if let Some(md) = self.max_depth {
                        if 1 > md {
                            continue;
                        }
                    }
                    stack.push(Work { dent, ig: igtmp, root_device, ancestors: Arc::new(vec![]) });
                } else {
                    if visitor.visit(Ok(dent)) == WalkState::Quit {
                        shared.quit.store(true, Ordering::SeqCst);
                        break;
                    }
                }
            }
            *shared.stack.lock().unwrap() = stack;
        }
        if shared.quit.load(Ordering::SeqCst) {
            return;
        }
        // Spawn workers.
        let mut handles = vec![];
        std::thread::scope(|scope| {
            for _ in 0..threads {
                let visitor = builder.build();
                let shared = shared.clone();
                let worker = Worker {
                    visitor,
                    shared,
                    max_depth: self.max_depth,
                    max_filesize: self.max_filesize,
                    follow_links: self.follow_links,
                    same_file_system: self.same_file_system,
                    skip: self.skip.clone(),
                    threads,
                };
                handles.push(scope.spawn(move || worker.run()));
            }
        });
    }
}

struct Worker<'s> {
    visitor: Box<dyn ParallelVisitor + 's>,
    shared: Arc<Shared>,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    skip: Option<Arc<StdoutHandle>>,
    threads: usize,
}

impl<'s> Worker<'s> {
    fn run(mut self) {
        loop {
            let work = match self.get_work() {
                None => return,
                Some(w) => w,
            };
            let state = self.run_one(work);
            self.shared.active.fetch_sub(1, Ordering::SeqCst);
            self.shared.cond.notify_all();
            if state == WalkState::Quit {
                self.shared.quit.store(true, Ordering::SeqCst);
                self.shared.cond.notify_all();
                return;
            }
        }
    }

    fn get_work(&self) -> Option<Work> {
        let mut stack = self.shared.stack.lock().unwrap();
        loop {
            if self.shared.quit.load(Ordering::SeqCst) {
                return None;
            }
            if let Some(w) = stack.pop() {
                self.shared.active.fetch_add(1, Ordering::SeqCst);
                return Some(w);
            }
            if self.shared.active.load(Ordering::SeqCst) == 0 {
                return None;
            }
            stack = self.shared.cond.wait(stack).unwrap();
        }
    }

    fn run_one(&mut self, work: Work) -> WalkState {
        use std::os::unix::fs::MetadataExt;
        let depth = work.dent.depth() + 1;
        let (dev, ino) = match fs::metadata(work.dent.path()) {
            Ok(md) => (md.dev(), md.ino()),
            Err(_) => (0, 0),
        };
        let mut ancestors: Vec<(PathBuf, u64, u64)> = (*work.ancestors).clone();
        ancestors.push((work.dent.path().to_path_buf(), dev, ino));
        let ancestors = Arc::new(ancestors);
        let entries = match read_dir_entries(work.dent.path(), depth, self.follow_links, &None) {
            Ok(entries) => entries,
            Err(err) => {
                return self.visitor.visit(Err(err.into_ignore_error()));
            }
        };
        let _ = self.threads;
        for ent in entries {
            if self.shared.quit.load(Ordering::SeqCst) {
                return WalkState::Quit;
            }
            let mut dent = match ent {
                Ok(d) => d,
                Err(err) => {
                    match self.visitor.visit(Err(err.into_ignore_error())) {
                        WalkState::Quit => return WalkState::Quit,
                        _ => continue,
                    }
                }
            };
            if self.follow_links && dent.file_type.map_or(false, |ft| ft.is_symlink()) {
                dent = match follow_symlink(dent, &ancestors) {
                    Ok(d) => d,
                    Err(err) => match self.visitor.visit(Err(err.into_ignore_error())) {
                        WalkState::Quit => return WalkState::Quit,
                        _ => continue,
                    },
                };
            }
            let is_dir = dent.is_dir();
            match skip_entry(&work.ig, &dent, &self.skip, self.max_filesize) {
                Err(err) => match self.visitor.visit(Err(err)) {
                    WalkState::Quit => return WalkState::Quit,
                    _ => continue,
                },
                Ok(true) => continue,
                Ok(false) => {}
            }
            if is_dir {
                let mut descend = true;
                if self.same_file_system {
                    if let Some(root_dev) = work.root_device {
                        match device_num(dent.path()) {
                            Ok(dev) => {
                                if dev != root_dev {
                                    descend = false;
                                }
                            }
                            Err(err) => {
                                match self.visitor.visit(Err(
                                    WalkError::with_path(depth, dent.path.clone(), err).into_ignore_error(),
                                )) {
                                    WalkState::Quit => return WalkState::Quit,
                                    _ => continue,
                                }
                            }
                        }
                    }
                }
                let (igtmp, err) = work.ig.add_child(dent.path());
                dent.err = err;
                let state = self.visitor.visit(Ok(dent.clone()));
                match state {
                    WalkState::Quit => return WalkState::Quit,
                    WalkState::Skip => continue,
                    WalkState::Continue => {}
                }
                if !descend {
                    continue;
                }
                if let Some(md) = self.max_depth {
                    if depth + 1 > md {
                        continue;
                    }
                }
                let w = Work {
                    dent,
                    ig: igtmp,
                    root_device: work.root_device,
                    ancestors: ancestors.clone(),
                };
                let mut stack = self.shared.stack.lock().unwrap();
                stack.push(w);
                self.shared.cond.notify_one();
            } else {
                match self.visitor.visit(Ok(dent)) {
                    WalkState::Quit => return WalkState::Quit,
                    _ => {}
                }
            }
        }
        WalkState::Continue
    }
}

