//! Recursive directory traversal with ignore rules (sequential + parallel).

use std::ffi::OsString;
use std::fs::{self, FileType, Metadata};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};

use crate::gitignore::{Gitignore, IgnoreError};
use crate::ignore::{Ignore, IgnoreBuilder, Override};
use crate::types::Types;

/// A directory entry produced by the walker.
#[derive(Debug, Clone)]
pub struct DirEntry {
    path: PathBuf,
    /// None for stdin.
    file_type: Option<FileType>,
    depth: usize,
    /// Whether the path itself is a symlink (before following).
    path_is_symlink: bool,
    /// Whether the entry was reached by following a symlink.
    follow_link: bool,
    ino: u64,
    err: Option<IgnoreError>,
    is_stdin: bool,
}

impl DirEntry {
    pub fn new_stdin() -> DirEntry {
        DirEntry {
            path: PathBuf::from("<stdin>"),
            file_type: None,
            depth: 0,
            path_is_symlink: false,
            follow_link: false,
            ino: 0,
            err: None,
            is_stdin: true,
        }
    }

    fn from_path(depth: usize, path: PathBuf, follow: bool) -> Result<DirEntry, WalkError> {
        use std::os::unix::fs::MetadataExt;
        let md = if follow {
            fs::metadata(&path).map_err(|err| WalkError::with_path(depth, path.clone(), err))?
        } else {
            fs::symlink_metadata(&path)
                .map_err(|err| WalkError::with_path(depth, path.clone(), err))?
        };
        Ok(DirEntry {
            path,
            file_type: Some(md.file_type()),
            depth,
            path_is_symlink: md.file_type().is_symlink(),
            follow_link: follow,
            ino: md.ino(),
            err: None,
            is_stdin: false,
        })
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
    pub fn into_path(self) -> PathBuf {
        self.path
    }
    pub fn depth(&self) -> usize {
        self.depth
    }
    pub fn file_type(&self) -> Option<FileType> {
        self.file_type
    }
    pub fn is_stdin(&self) -> bool {
        self.is_stdin
    }
    pub fn path_is_symlink(&self) -> bool {
        self.path_is_symlink
    }
    pub fn error(&self) -> Option<&IgnoreError> {
        self.err.as_ref()
    }
    pub fn take_error(&mut self) -> Option<IgnoreError> {
        self.err.take()
    }
    pub fn file_name(&self) -> Option<&std::ffi::OsStr> {
        self.path.file_name()
    }
    pub fn metadata(&self) -> io::Result<Metadata> {
        if self.follow_link {
            fs::metadata(&self.path)
        } else {
            fs::symlink_metadata(&self.path)
        }
    }
    pub fn is_dir(&self) -> bool {
        self.file_type.map_or(false, |ft| ft.is_dir())
    }
    pub fn ino(&self) -> u64 {
        self.ino
    }
}

/// A walk error (mirrors walkdir::Error semantics).
#[derive(Debug)]
pub struct WalkError {
    depth: usize,
    inner: WalkErrorInner,
}

#[derive(Debug)]
enum WalkErrorInner {
    Io { path: Option<PathBuf>, err: io::Error },
    Loop { ancestor: PathBuf, child: PathBuf },
}

impl WalkError {
    fn with_path(depth: usize, path: PathBuf, err: io::Error) -> WalkError {
        WalkError { depth, inner: WalkErrorInner::Io { path: Some(path), err } }
    }
    fn io(depth: usize, err: io::Error) -> WalkError {
        WalkError { depth, inner: WalkErrorInner::Io { path: None, err } }
    }
    pub fn depth(&self) -> usize {
        self.depth
    }
    /// Convert to the ignore-crate style error.
    pub fn into_ignore_error(self) -> IgnoreError {
        match self.inner {
            WalkErrorInner::Loop { ancestor, child } => {
                IgnoreError::Loop { ancestor, child }.with_depth(self.depth)
            }
            WalkErrorInner::Io { path, err } => {
                let msg = match path {
                    Some(ref p) => {
                        format!("IO error for operation on {}: {}", p.display(), err)
                    }
                    None => format!("IO error: {}", err),
                };
                let ig_err = IgnoreError::Io(msg);
                match path {
                    Some(p) => ig_err.with_path(p),
                    None => ig_err,
                }
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WalkState {
    Continue,
    Skip,
    Quit,
}

#[derive(Clone)]
enum Sorter {
    ByName(Arc<dyn Fn(&std::ffi::OsStr, &std::ffi::OsStr) -> std::cmp::Ordering + Send + Sync>),
}

/// Builds a walker.
pub struct WalkBuilder {
    paths: Vec<PathBuf>,
    ig_builder: IgnoreBuilder,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    sorter: Option<Sorter>,
    threads: usize,
    skip: Option<Arc<StdoutHandle>>,
}

/// Identity of the stdout file (if it's a regular file).
#[derive(Debug)]
pub struct StdoutHandle {
    dev: u64,
    ino: u64,
}

impl StdoutHandle {
    pub fn stdout() -> Option<StdoutHandle> {
        use std::os::unix::fs::MetadataExt;
        let md = fs::metadata("/dev/stdout").ok()?;
        if !md.file_type().is_file() {
            return None;
        }
        Some(StdoutHandle { dev: md.dev(), ino: md.ino() })
    }
}

impl WalkBuilder {
    pub fn new<P: AsRef<Path>>(path: P) -> WalkBuilder {
        WalkBuilder {
            paths: vec![path.as_ref().to_path_buf()],
            ig_builder: IgnoreBuilder::new(),
            max_depth: None,
            max_filesize: None,
            follow_links: false,
            same_file_system: false,
            sorter: None,
            threads: 0,
            skip: None,
        }
    }

    pub fn add<P: AsRef<Path>>(&mut self, path: P) -> &mut WalkBuilder {
        self.paths.push(path.as_ref().to_path_buf());
        self
    }
    pub fn max_depth(&mut self, depth: Option<usize>) -> &mut WalkBuilder {
        self.max_depth = depth;
        self
    }
    pub fn follow_links(&mut self, yes: bool) -> &mut WalkBuilder {
        self.follow_links = yes;
        self
    }
    pub fn max_filesize(&mut self, filesize: Option<u64>) -> &mut WalkBuilder {
        self.max_filesize = filesize;
        self
    }
    pub fn threads(&mut self, n: usize) -> &mut WalkBuilder {
        self.threads = n;
        self
    }
    pub fn add_ignore<P: AsRef<Path>>(&mut self, path: P) -> Option<IgnoreError> {
        let mut builder = crate::gitignore::GitignoreBuilder::new("");
        let mut errs = crate::gitignore::PartialErrorBuilder::default();
        errs.maybe_push(builder.add(path));
        match builder.build() {
            Ok(gi) => {
                self.ig_builder.add_ignore(gi);
            }
            Err(err) => {
                errs.push(err);
            }
        }
        errs.into_error_option()
    }
    pub fn add_custom_ignore_filename<S: AsRef<std::ffi::OsStr>>(&mut self, name: S) -> &mut WalkBuilder {
        self.ig_builder.add_custom_ignore_filename(name);
        self
    }
    pub fn overrides(&mut self, overrides: Override) -> &mut WalkBuilder {
        self.ig_builder.overrides(overrides);
        self
    }
    pub fn types(&mut self, types: Types) -> &mut WalkBuilder {
        self.ig_builder.types(types);
        self
    }
    pub fn hidden(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.hidden(yes);
        self
    }
    pub fn parents(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.parents(yes);
        self
    }
    pub fn ignore(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.ignore(yes);
        self
    }
    pub fn git_global(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.git_global(yes);
        self
    }
    pub fn git_ignore(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.git_ignore(yes);
        self
    }
    pub fn git_exclude(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.git_exclude(yes);
        self
    }
    pub fn require_git(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.require_git(yes);
        self
    }
    pub fn ignore_case_insensitive(&mut self, yes: bool) -> &mut WalkBuilder {
        self.ig_builder.ignore_case_insensitive(yes);
        self
    }
    pub fn sort_by_file_name<F>(&mut self, cmp: F) -> &mut WalkBuilder
    where
        F: Fn(&std::ffi::OsStr, &std::ffi::OsStr) -> std::cmp::Ordering + Send + Sync + 'static,
    {
        self.sorter = Some(Sorter::ByName(Arc::new(cmp)));
        self
    }
    pub fn same_file_system(&mut self, yes: bool) -> &mut WalkBuilder {
        self.same_file_system = yes;
        self
    }
    pub fn skip_stdout(&mut self, yes: bool) -> &mut WalkBuilder {
        if yes {
            self.skip = StdoutHandle::stdout().map(Arc::new);
        } else {
            self.skip = None;
        }
        self
    }

    pub fn build(&mut self) -> Walk {
        let ig_root = self.ig_builder.build();
        Walk {
            paths: self.paths.clone().into_iter(),
            ig_root,
            max_depth: self.max_depth,
            max_filesize: self.max_filesize,
            follow_links: self.follow_links,
            same_file_system: self.same_file_system,
            sorter: self.sorter.clone(),
            skip: self.skip.clone(),
            stack: vec![],
            root_device: None,
            cur_ig: None,
            pending_root: None,
        }
    }

    pub fn build_parallel(&mut self) -> WalkParallel {
        let ig_root = self.ig_builder.build();
        WalkParallel {
            paths: self.paths.clone(),
            ig_root,
            max_depth: self.max_depth,
            max_filesize: self.max_filesize,
            follow_links: self.follow_links,
            same_file_system: self.same_file_system,
            skip: self.skip.clone(),
            threads: self.threads,
        }
    }
}

fn device_num<P: AsRef<Path>>(path: P) -> io::Result<u64> {
    use std::os::unix::fs::MetadataExt;
    path.as_ref().metadata().map(|md| md.dev())
}

fn is_hidden(dent: &DirEntry) -> bool {
    use std::os::unix::ffi::OsStrExt;
    if dent.depth() == 0 {
        return false;
    }
    dent.file_name().map(|name| name.as_bytes().starts_with(b".")).unwrap_or(false)
}

/// Shared per-entry skip logic.
fn skip_entry(
    ig: &Ignore,
    dent: &DirEntry,
    skip: &Option<Arc<StdoutHandle>>,
    max_filesize: Option<u64>,
) -> Result<bool, IgnoreError> {
    if dent.depth() == 0 {
        return Ok(false);
    }
    if should_skip_entry(ig, dent) {
        return Ok(true);
    }
    if let Some(ref stdout) = *skip {
        if path_equals(dent, stdout)? {
            return Ok(true);
        }
    }
    if max_filesize.is_some() && !dent.is_dir() {
        return Ok(skip_filesize(max_filesize.unwrap(), dent.path(), &dent.metadata().ok()));
    }
    Ok(false)
}

fn should_skip_entry(ig: &Ignore, dent: &DirEntry) -> bool {
    let m = ig.matched_dir_entry(dent.path(), dent.is_dir(), is_hidden(dent));
    if m.is_ignore() {
        crate::log_debug!(
            "ignore::walk",
            "crates/ignore/src/walk.rs:1780",
            "ignoring {}: {}",
            dent.path().display(),
            describe_match(&m)
        );
        true
    } else if m.is_whitelist() {
        crate::log_debug!(
            "ignore::walk",
            "crates/ignore/src/walk.rs:1783",
            "whitelisting {}: {}",
            dent.path().display(),
            describe_match(&m)
        );
        false
    } else {
        false
    }
}

fn describe_match(m: &crate::gitignore::Match<crate::ignore::IgnoreMatchKind>) -> String {
    use crate::gitignore::Match;
    use crate::ignore::IgnoreMatchKind;
    let inner = |k: &IgnoreMatchKind| -> String {
        match k {
            IgnoreMatchKind::Override => "Override(Glob(Matched(...)))".to_string(),
            IgnoreMatchKind::Gitignore(g) => format!("Gitignore({})", g),
            IgnoreMatchKind::Types(t) => format!("Types({})", t),
            IgnoreMatchKind::Hidden => "Hidden".to_string(),
        }
    };
    match m {
        Match::None => "None".to_string(),
        Match::Ignore(k) => format!("Ignore(IgnoreMatch({}))", inner(k)),
        Match::Whitelist(k) => format!("Whitelist(IgnoreMatch({}))", inner(k)),
    }
}

fn path_equals(dent: &DirEntry, handle: &StdoutHandle) -> Result<bool, IgnoreError> {
    use std::os::unix::fs::MetadataExt;
    if dent.ino() != handle.ino {
        return Ok(false);
    }
    match fs::metadata(dent.path()) {
        Ok(md) => Ok(md.ino() == handle.ino && md.dev() == handle.dev),
        Err(err) => Err(IgnoreError::Io(err.to_string()).with_path(dent.path())),
    }
}

fn skip_filesize(max_filesize: u64, path: &Path, ent: &Option<Metadata>) -> bool {
    let filesize = match *ent {
        Some(ref md) => Some(md.len()),
        None => None,
    };
    if let Some(fs) = filesize {
        if fs > max_filesize {
            crate::log_debug!(
                "ignore::walk",
                "crates/ignore/src/walk.rs:1805",
                "ignoring {}: {} bytes > {} max filesize",
                path.display(),
                fs,
                max_filesize
            );
            true
        } else {
            false
        }
    } else {
        false
    }
}

/// Read and (optionally) sort the entries of a directory.
fn read_dir_entries(
    path: &Path,
    depth: usize,
    follow_links: bool,
    sorter: &Option<Sorter>,
) -> Result<Vec<Result<DirEntry, WalkError>>, WalkError> {
    let rd = fs::read_dir(path).map_err(|err| WalkError::with_path(depth, path.to_path_buf(), err))?;
    let mut entries: Vec<Result<DirEntry, WalkError>> = vec![];
    for ent in rd {
        match ent {
            Err(err) => entries.push(Err(WalkError::with_path(depth, path.to_path_buf(), err))),
            Ok(ent) => {
                use std::os::unix::fs::DirEntryExt;
                let ft = match ent.file_type() {
                    Ok(ft) => ft,
                    Err(err) => {
                        entries.push(Err(WalkError::with_path(depth, ent.path(), err)));
                        continue;
                    }
                };
                let dent = DirEntry {
                    path: ent.path(),
                    file_type: Some(ft),
                    depth,
                    path_is_symlink: ft.is_symlink(),
                    follow_link: false,
                    ino: ent.ino(),
                    err: None,
                    is_stdin: false,
                };
                entries.push(Ok(dent));
            }
        }
    }
    let _ = follow_links;
    if let Some(Sorter::ByName(cmp)) = sorter {
        entries.sort_by(|a, b| match (a, b) {
            (Ok(a), Ok(b)) => cmp(a.file_name().unwrap_or_default(), b.file_name().unwrap_or_default()),
            (Ok(_), Err(_)) => std::cmp::Ordering::Less,
            (Err(_), Ok(_)) => std::cmp::Ordering::Greater,
            (Err(_), Err(_)) => std::cmp::Ordering::Equal,
        });
    }
    Ok(entries)
}

/// Follow a symlink entry, checking for loops against the ancestor stack.
fn follow_symlink(
    dent: DirEntry,
    ancestors: &[(PathBuf, u64, u64)],
) -> Result<DirEntry, WalkError> {
    use std::os::unix::fs::MetadataExt;
    let depth = dent.depth;
    let md = fs::metadata(&dent.path)
        .map_err(|err| WalkError::with_path(depth, dent.path.clone(), err))?;
    let new = DirEntry {
        path: dent.path,
        file_type: Some(md.file_type()),
        depth,
        path_is_symlink: true,
        follow_link: true,
        ino: md.ino(),
        err: None,
        is_stdin: false,
    };
    if md.file_type().is_dir() {
        // Loop check.
        let (dev, ino) = (md.dev(), md.ino());
        for (apath, adev, aino) in ancestors.iter().rev() {
            if *adev == dev && *aino == ino {
                return Err(WalkError {
                    depth,
                    inner: WalkErrorInner::Loop { ancestor: apath.clone(), child: new.path.clone() },
                });
            }
        }
    }
    Ok(new)
}

struct Frame {
    entries: std::vec::IntoIter<Result<DirEntry, WalkError>>,
    ig: Ignore,
    /// (path, dev, ino) of this directory for loop detection.
    ancestor: (PathBuf, u64, u64),
}

/// A sequential walker.
pub struct Walk {
    paths: std::vec::IntoIter<PathBuf>,
    ig_root: Ignore,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    sorter: Option<Sorter>,
    skip: Option<Arc<StdoutHandle>>,
    stack: Vec<Frame>,
    root_device: Option<u64>,
    cur_ig: Option<Ignore>,
    pending_root: Option<PathBuf>,
}

impl Walk {
    fn ancestors(&self) -> Vec<(PathBuf, u64, u64)> {
        self.stack.iter().map(|f| f.ancestor.clone()).collect()
    }

    /// Push a directory frame for `dent` (already determined to be a dir).
    fn push_dir(&mut self, dent: &DirEntry, ig: Ignore) -> Option<WalkError> {
        use std::os::unix::fs::MetadataExt;
        let depth = dent.depth + 1;
        if let Some(md) = self.max_depth {
            if depth > md {
                // Don't descend, but we still need a frame to pop ig? No:
                // we never pushed, so just return.
                return None;
            }
        }
        let (dev, ino) = match fs::metadata(dent.path()) {
            Ok(md) => (md.dev(), md.ino()),
            Err(_) => (0, 0),
        };
        match read_dir_entries(dent.path(), depth, self.follow_links, &self.sorter) {
            Ok(entries) => {
                self.stack.push(Frame {
                    entries: entries.into_iter(),
                    ig,
                    ancestor: (dent.path().to_path_buf(), dev, ino),
                });
                None
            }
            Err(err) => Some(err),
        }
    }
}

impl Iterator for Walk {
    type Item = Result<DirEntry, IgnoreError>;

    fn next(&mut self) -> Option<Result<DirEntry, IgnoreError>> {
        loop {
            // Process the top frame.
            if let Some(frame) = self.stack.last_mut() {
                let next = frame.entries.next();
                let ig = frame.ig.clone();
                match next {
                    None => {
                        self.stack.pop();
                        continue;
                    }
                    Some(Err(err)) => return Some(Err(err.into_ignore_error())),
                    Some(Ok(mut dent)) => {
                        // Follow symlinks if requested.
                        if self.follow_links && dent.file_type.map_or(false, |ft| ft.is_symlink()) {
                            let ancestors = self.ancestors();
                            dent = match follow_symlink(dent, &ancestors) {
                                Ok(d) => d,
                                Err(err) => return Some(Err(err.into_ignore_error())),
                            };
                        }
                        let is_dir = dent.is_dir();
                        if is_dir {
                            if let Ok(should_skip) = skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                if should_skip {
                                    continue;
                                }
                            } else if let Err(err) = skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                return Some(Err(err));
                            }
                            // same file system check
                            if self.same_file_system {
                                if let Some(root_dev) = self.root_device {
                                    match device_num(dent.path()) {
                                        Ok(dev) => {
                                            if dev != root_dev {
                                                // Don't descend, but still yield? walkdir yields the dir entry.
                                                let (igtmp, err) = ig.add_child(dent.path());
                                                let _ = igtmp;
                                                dent.err = err;
                                                return Some(Ok(dent));
                                            }
                                        }
                                        Err(err) => {
                                            return Some(Err(WalkError::with_path(dent.depth, dent.path.clone(), err).into_ignore_error()));
                                        }
                                    }
                                }
                            }
                            let (igtmp, err) = ig.add_child(dent.path());
                            dent.err = err;
                            if let Some(werr) = self.push_dir(&dent, igtmp) {
                                // Yield the dir entry first, then the error.
                                self.cur_ig = None;
                                let e = werr.into_ignore_error();
                                // We emulate walkdir: the directory entry is yielded,
                                // then the read_dir error on the next call.
                                self.pending_err = Some(e);
                                return Some(Ok(dent));
                            }
                            return Some(Ok(dent));
                        } else {
                            match skip_entry(&ig, &dent, &self.skip, self.max_filesize) {
                                Err(err) => return Some(Err(err)),
                                Ok(true) => continue,
                                Ok(false) => return Some(Ok(dent)),
                            }
                        }
                    }
                }
            }
            if let Some(err) = self.pending_err.take() {
                return Some(Err(err));
            }
            // Start the next root path.
            let path = match self.paths.next() {
                None => return None,
                Some(path) => path,
            };
            if path == Path::new("-") {
                return Some(Ok(DirEntry::new_stdin()));
            }
            self.root_device = None;
            if self.same_file_system {
                match device_num(&path) {
                    Ok(dev) => self.root_device = Some(dev),
                    Err(err) => {
                        return Some(Err(WalkError::with_path(0, path.clone(), err).into_ignore_error()));
                    }
                }
            }
            let follow_root = self.follow_links || path.is_file();
            let dent = match DirEntry::from_path(0, path.clone(), false) {
                Ok(d) => d,
                Err(err) => return Some(Err(err.into_ignore_error())),
            };
            // Determine the ignore matcher for this root.
            let ig = if path.is_dir() {
                let (ig, err) = self.ig_root.add_parents(&path);
                if let Some(err) = err {
                    // Yield the error, but we must still process the path.
                    self.pending_root = Some(path.clone());
                    self.cur_ig = Some(ig);
                    return Some(Err(err));
                }
                ig
            } else {
                self.ig_root.clone()
            };
            if let Some(r) = self.start_root(dent, ig, follow_root) {
                return Some(r);
            }
        }
    }
}

impl Walk {
    fn start_root(
        &mut self,
        mut dent: DirEntry,
        ig: Ignore,
        follow_root: bool,
    ) -> Option<Result<DirEntry, IgnoreError>> {
        // Root symlinks are always followed.
        let is_symlink = dent.file_type.map_or(false, |ft| ft.is_symlink());
        if is_symlink {
            match fs::metadata(dent.path()) {
                Ok(md) => {
                    use std::os::unix::fs::MetadataExt;
                    if follow_root {
                        dent.file_type = Some(md.file_type());
                        dent.follow_link = true;
                        dent.ino = md.ino();
                    }
                    if md.file_type().is_dir() {
                        let (igtmp, err) = ig.add_child(dent.path());
                        dent.err = err;
                        // Make the entry look like a directory for consumers.
                        dent.file_type = Some(md.file_type());
                        if let Some(werr) = self.push_dir(&dent, igtmp) {
                            self.pending_err = Some(werr.into_ignore_error());
                        }
                        return Some(Ok(dent));
                    }
                    return Some(Ok(dent));
                }
                Err(err) => {
                    return Some(Err(WalkError::with_path(0, dent.path.clone(), err).into_ignore_error()));
                }
            }
        }
        if dent.is_dir() {
            let (igtmp, err) = ig.add_child(dent.path());
            dent.err = err;
            if let Some(werr) = self.push_dir(&dent, igtmp) {
                self.pending_err = Some(werr.into_ignore_error());
            }
            return Some(Ok(dent));
        }
        Some(Ok(dent))
    }
}

/// Parallel walker.
pub struct WalkParallel {
    paths: Vec<PathBuf>,
    ig_root: Ignore,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    skip: Option<Arc<StdoutHandle>>,
    threads: usize,
}

/// A visitor for the parallel walker.
pub trait ParallelVisitor: Send {
    fn visit(&mut self, entry: Result<DirEntry, IgnoreError>) -> WalkState;
}

pub trait ParallelVisitorBuilder<'s> {
    fn build(&mut self) -> Box<dyn ParallelVisitor + 's>;
}

struct Work {
    dent: DirEntry,
    ig: Ignore,
    root_device: Option<u64>,
    ancestors: Arc<Vec<(PathBuf, u64, u64)>>,
}

struct Shared {
    stack: Mutex<Vec<Work>>,
    cond: Condvar,
    active: AtomicUsize,
    quit: AtomicBool,
}

impl WalkParallel {
    pub fn threads(&self) -> usize {
        if self.threads == 0 {
            2
        } else {
            self.threads
        }
    }

    pub fn visit(self, builder: &mut dyn ParallelVisitorBuilder<'_>) {
        let threads = self.threads();
        let shared = Arc::new(Shared {
            stack: Mutex::new(vec![]),
            cond: Condvar::new(),
            active: AtomicUsize::new(0),
            quit: AtomicBool::new(false),
        });
        // Seed the stack with roots, processing roots sequentially through a
        // single visitor first (errors and files).
        {
            let mut visitor = builder.build();
            let mut stack = vec![];
            for path in self.paths.iter() {
                if path == Path::new("-") {
                    if visitor.visit(Ok(DirEntry::new_stdin())) == WalkState::Quit {
                        shared.quit.store(true, Ordering::SeqCst);
                        break;
                    }
                    continue;
                }
                let mut root_device = None;
                if self.same_file_system {
                    match device_num(path) {
                        Ok(dev) => root_device = Some(dev),
                        Err(err) => {
                            if visitor.visit(Err(
                                WalkError::with_path(0, path.clone(), err).into_ignore_error(),
                            )) == WalkState::Quit
                            {
                                shared.quit.store(true, Ordering::SeqCst);
                                break;
                            }
                            continue;
                        }
                    }
                }
                let dent = match DirEntry::from_path(0, path.clone(), false) {
                    Ok(d) => d,
                    Err(err) => {
                        if visitor.visit(Err(err.into_ignore_error())) == WalkState::Quit {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                        continue;
                    }
                };
                let ig = if path.is_dir() {
                    let (ig, err) = self.ig_root.add_parents(path);
                    if let Some(err) = err {
                        if visitor.visit(Err(err)) == WalkState::Quit {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                    }
                    ig
                } else {
                    self.ig_root.clone()
                };
                // Resolve root symlinks.
                let mut dent = dent;
                let is_symlink = dent.file_type.map_or(false, |ft| ft.is_symlink());
                let follow_root = self.follow_links || path.is_file();
                if is_symlink {
                    match fs::metadata(dent.path()) {
                        Ok(md) => {
                            use std::os::unix::fs::MetadataExt;
                            if follow_root || md.file_type().is_dir() {
                                dent.file_type = Some(md.file_type());
                                dent.follow_link = follow_root;
                                dent.ino = md.ino();
                            }
                        }
                        Err(err) => {
                            if visitor.visit(Err(
                                WalkError::with_path(0, dent.path.clone(), err).into_ignore_error(),
                            )) == WalkState::Quit
                            {
                                shared.quit.store(true, Ordering::SeqCst);
                                break;
                            }
                            continue;
                        }
                    }
                }
                if dent.is_dir() {
                    let (igtmp, err) = ig.add_child(dent.path());
                    dent.err = err;
                    let state = visitor.visit(Ok(dent.clone()));
                    match state {
                        WalkState::Quit => {
                            shared.quit.store(true, Ordering::SeqCst);
                            break;
                        }
                        WalkState::Skip => continue,
                        WalkState::Continue => {}
                    }
                    if let Some(md) = self.max_depth {
                        if 1 > md {
                            continue;
                        }
                    }
                    stack.push(Work { dent, ig: igtmp, root_device, ancestors: Arc::new(vec![]) });
                } else {
                    if visitor.visit(Ok(dent)) == WalkState::Quit {
                        shared.quit.store(true, Ordering::SeqCst);
                        break;
                    }
                }
            }
            *shared.stack.lock().unwrap() = stack;
        }
        if shared.quit.load(Ordering::SeqCst) {
            return;
        }
        // Spawn workers.
        let mut handles = vec![];
        std::thread::scope(|scope| {
            for _ in 0..threads {
                let visitor = builder.build();
                let shared = shared.clone();
                let worker = Worker {
                    visitor,
                    shared,
                    max_depth: self.max_depth,
                    max_filesize: self.max_filesize,
                    follow_links: self.follow_links,
                    same_file_system: self.same_file_system,
                    skip: self.skip.clone(),
                    threads,
                };
                handles.push(scope.spawn(move || worker.run()));
            }
        });
    }
}

struct Worker<'s> {
    visitor: Box<dyn ParallelVisitor + 's>,
    shared: Arc<Shared>,
    max_depth: Option<usize>,
    max_filesize: Option<u64>,
    follow_links: bool,
    same_file_system: bool,
    skip: Option<Arc<StdoutHandle>>,
    threads: usize,
}

impl<'s> Worker<'s> {
    fn run(mut self) {
        loop {
            let work = match self.get_work() {
                None => return,
                Some(w) => w,
            };
            let state = self.run_one(work);
            self.shared.active.fetch_sub(1, Ordering::SeqCst);
            self.shared.cond.notify_all();
            if state == WalkState::Quit {
                self.shared.quit.store(true, Ordering::SeqCst);
                self.shared.cond.notify_all();
                return;
            }
        }
    }

    fn get_work(&self) -> Option<Work> {
        let mut stack = self.shared.stack.lock().unwrap();
        loop {
            if self.shared.quit.load(Ordering::SeqCst) {
                return None;
            }
            if let Some(w) = stack.pop() {
                self.shared.active.fetch_add(1, Ordering::SeqCst);
                return Some(w);
            }
            if self.shared.active.load(Ordering::SeqCst) == 0 {
                return None;
            }
            stack = self.shared.cond.wait(stack).unwrap();
        }
    }

    fn run_one(&mut self, work: Work) -> WalkState {
        use std::os::unix::fs::MetadataExt;
        let depth = work.dent.depth() + 1;
        let (dev, ino) = match fs::metadata(work.dent.path()) {
            Ok(md) => (md.dev(), md.ino()),
            Err(_) => (0, 0),
        };
        let mut ancestors: Vec<(PathBuf, u64, u64)> = (*work.ancestors).clone();
        ancestors.push((work.dent.path().to_path_buf(), dev, ino));
        let ancestors = Arc::new(ancestors);
        let entries = match read_dir_entries(work.dent.path(), depth, self.follow_links, &None) {
            Ok(entries) => entries,
            Err(err) => {
                return self.visitor.visit(Err(err.into_ignore_error()));
            }
        };
        let _ = self.threads;
        for ent in entries {
            if self.shared.quit.load(Ordering::SeqCst) {
                return WalkState::Quit;
            }
            let mut dent = match ent {
                Ok(d) => d,
                Err(err) => {
                    match self.visitor.visit(Err(err.into_ignore_error())) {
                        WalkState::Quit => return WalkState::Quit,
                        _ => continue,
                    }
                }
            };
            if self.follow_links && dent.file_type.map_or(false, |ft| ft.is_symlink()) {
                dent = match follow_symlink(dent, &ancestors) {
                    Ok(d) => d,
                    Err(err) => match self.visitor.visit(Err(err.into_ignore_error())) {
                        WalkState::Quit => return WalkState::Quit,
                        _ => continue,
                    },
                };
            }
            let is_dir = dent.is_dir();
            match skip_entry(&work.ig, &dent, &self.skip, self.max_filesize) {
                Err(err) => match self.visitor.visit(Err(err)) {
                    WalkState::Quit => return WalkState::Quit,
                    _ => continue,
                },
                Ok(true) => continue,
                Ok(false) => {}
            }
            if is_dir {
                let mut descend = true;
                if self.same_file_system {
                    if let Some(root_dev) = work.root_device {
                        match device_num(dent.path()) {
                            Ok(dev) => {
                                if dev != root_dev {
                                    descend = false;
                                }
                            }
                            Err(err) => {
                                match self.visitor.visit(Err(
                                    WalkError::with_path(depth, dent.path.clone(), err).into_ignore_error(),
                                )) {
                                    WalkState::Quit => return WalkState::Quit,
                                    _ => continue,
                                }
                            }
                        }
                    }
                }
                let (igtmp, err) = work.ig.add_child(dent.path());
                dent.err = err;
                let state = self.visitor.visit(Ok(dent.clone()));
                match state {
                    WalkState::Quit => return WalkState::Quit,
                    WalkState::Skip => continue,
                    WalkState::Continue => {}
                }
                if !descend {
                    continue;
                }
                if let Some(md) = self.max_depth {
                    if depth + 1 > md {
                        continue;
                    }
                }
                let w = Work {
                    dent,
                    ig: igtmp,
                    root_device: work.root_device,
                    ancestors: ancestors.clone(),
                };
                let mut stack = self.shared.stack.lock().unwrap();
                stack.push(w);
                self.shared.cond.notify_one();
