//! Regex matcher construction mirroring ripgrep's default engine semantics.

use regex_automata::meta::Regex;
use regex_automata::util::captures::Captures;
use regex_automata::util::look::Look;
use regex_automata::{Input, PatternID};
use regex_syntax::ast::{self, Ast};
use regex_syntax::hir::{self, Hir, HirKind};

use crate::error::{Error, Result};

/// Line terminator abstraction (byte or CRLF).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LineTerminator {
    Byte(u8),
    CRLF,
}

impl LineTerminator {
    pub fn byte(b: u8) -> LineTerminator {
        LineTerminator::Byte(b)
    }
    pub fn crlf() -> LineTerminator {
        LineTerminator::CRLF
    }
    pub fn is_crlf(&self) -> bool {
        matches!(*self, LineTerminator::CRLF)
    }
    pub fn as_byte(&self) -> u8 {
        match *self {
            LineTerminator::Byte(b) => b,
            LineTerminator::CRLF => b'\n',
        }
    }
    pub fn as_bytes(&self) -> &'static [u8] {
        match *self {
            LineTerminator::Byte(b) => {
                // Only a few bytes are possible in practice; handle generally.
                static TABLE: [[u8; 1]; 256] = {
                    let mut t = [[0u8; 1]; 256];
                    let mut i = 0;
                    while i < 256 {
                        t[i] = [i as u8];
                        i += 1;
                    }
                    t
                };
                &TABLE[b as usize]
            }
            LineTerminator::CRLF => b"\r\n",
        }
    }
    pub fn is_suffix(&self, slice: &[u8]) -> bool {
        slice.last().map_or(false, |&b| b == self.as_byte())
    }
}

impl Default for LineTerminator {
    fn default() -> LineTerminator {
        LineTerminator::Byte(b'\n')
    }
}

/// Configuration for building a matcher.
#[derive(Debug, Clone)]
pub struct MatcherConfig {
    pub case_insensitive: bool,
    pub case_smart: bool,
    pub multi_line: bool,
    pub dot_matches_new_line: bool,
    pub crlf: bool,
    pub word: bool,
    pub whole_line: bool,
    pub unicode: bool,
    pub size_limit: usize,
    pub dfa_size_limit: usize,
    pub nest_limit: u32,
    pub line_terminator: Option<LineTerminator>,
    pub ban: Option<u8>,
    pub fixed_strings: bool,
}

impl Default for MatcherConfig {
    fn default() -> MatcherConfig {
        MatcherConfig {
            case_insensitive: false,
            case_smart: false,
            multi_line: true,
            dot_matches_new_line: false,
            crlf: false,
            word: false,
            whole_line: false,
            unicode: true,
            size_limit: 100 * (1 << 20),
            dfa_size_limit: 1000 * (1 << 20),
            nest_limit: 250,
            line_terminator: Some(LineTerminator::default()),
            ban: None,
            fixed_strings: false,
        }
    }
}

impl MatcherConfig {
    fn is_fixed_strings(&self, patterns: &[String]) -> bool {
        if self.case_insensitive || self.case_smart {
            return false;
        }
        if self.fixed_strings {
            if let Some(lt) = self.line_terminator {
                let byte = lt.as_byte();
                for p in patterns {
                    if p.as_bytes().contains(&byte) {
                        return false;
                    }
                    if lt.is_crlf() && p.as_bytes().contains(&b'\r') {
                        return false;
                    }
                }
            }
            return true;
        }
        for p in patterns {
            if p.chars().any(regex_syntax::is_meta_character) {
                return false;
            }
            if let Some(lt) = self.line_terminator {
                if p.as_bytes().contains(&lt.as_byte()) {
                    return false;
                }
                if lt.is_crlf() && p.as_bytes().contains(&b'\r') {
                    return false;
                }
            }
        }
        true
    }
}

/// A compiled matcher.
#[derive(Debug)]
pub struct RegexMatcher {
    regex: Regex,
    config: MatcherConfig,
    /// Whether the regex can match a line terminator (relevant for multiline).
    hir: Hir,
    /// Names of capture groups.
    names: Vec<Option<String>>,
}

pub type Match = (usize, usize);

impl RegexMatcher {
    pub fn new_many(config: MatcherConfig, patterns: &[String]) -> Result<RegexMatcher> {
        let hir = build_hir(&config, patterns)?;
        let regex = hir_to_regex(&config, &hir)?;
        let names: Vec<Option<String>> = regex
            .group_info()
            .pattern_names(PatternID::ZERO)
            .map(|n| n.map(|s| s.to_string()))
            .collect();
        Ok(RegexMatcher { regex, config, hir, names })
    }

    pub fn regex(&self) -> &Regex {
        &self.regex
    }

    pub fn line_terminator(&self) -> Option<LineTerminator> {
        self.config.line_terminator
    }

    pub fn hir(&self) -> &Hir {
        &self.hir
    }

    /// Returns true if the regex can never match a line terminator (i.e. the
    /// searcher may use line-oriented searching even in multiline mode).
    pub fn can_match_line_terminator(&self, lt: u8) -> bool {
        hir_may_match_byte(&self.hir, lt)
    }

    pub fn find_at(&self, haystack: &[u8], at: usize) -> Option<Match> {
        let input = Input::new(haystack).span(at..haystack.len());
        self.regex.search(&input).map(|m| (m.start(), m.end()))
    }

    pub fn find(&self, haystack: &[u8]) -> Option<Match> {
        self.find_at(haystack, 0)
    }

    pub fn is_match_at(&self, haystack: &[u8], at: usize) -> bool {
        let input = Input::new(haystack).span(at..haystack.len());
        self.regex.search_half(&input).is_some()
    }

    pub fn shortest_match_at(&self, haystack: &[u8], at: usize) -> Option<usize> {
        let input = Input::new(haystack).span(at..haystack.len());
        self.regex.search_half(&input).map(|m| m.offset())
    }

    /// Iterate over all non-overlapping matches in `haystack[..]` starting
    /// at `at`, calling `f` for each. Stops if `f` returns false.
    pub fn find_iter_at<F: FnMut(Match) -> bool>(&self, haystack: &[u8], at: usize, mut f: F) {
        let input = Input::new(haystack).span(at..haystack.len());
        for m in self.regex.find_iter(input) {
            if !f((m.start(), m.end())) {
                break;
            }
        }
    }

    pub fn find_iter<F: FnMut(Match) -> bool>(&self, haystack: &[u8], f: F) {
        self.find_iter_at(haystack, 0, f)
    }

    pub fn new_captures(&self) -> Captures {
        self.regex.create_captures()
    }

    pub fn captures_at(&self, haystack: &[u8], at: usize, caps: &mut Captures) -> bool {
        let input = Input::new(haystack).span(at..haystack.len());
        self.regex.search_captures(&input, caps);
        caps.is_match()
    }

    pub fn capture_count(&self) -> usize {
        self.regex.group_info().group_len(PatternID::ZERO)
    }

    pub fn capture_index(&self, name: &str) -> Option<usize> {
        self.names.iter().position(|n| n.as_deref() == Some(name))
    }

    /// Iterate over captures of all matches.
    pub fn captures_iter<F: FnMut(&Captures) -> bool>(&self, haystack: &[u8], at: usize, caps: &mut Captures, mut f: F) {
        let mut pos = at;
        let mut last_match_end: Option<usize> = None;
        while pos <= haystack.len() {
            let input = Input::new(haystack).span(pos..haystack.len());
            self.regex.search_captures(&input, caps);
            let m = match caps.get_match() {
                None => break,
                Some(m) => m,
            };
            if m.is_empty() {
                // Avoid infinite loop on empty matches: step forward.
                if Some(m.end()) == last_match_end {
                    pos = m.end() + 1;
                    if pos > haystack.len() {
                        break;
                    }
                    continue;
                }
                pos = m.end() + 1;
            } else {
                pos = m.end();
            }
            last_match_end = Some(m.end());
            if !f(caps) {
                break;
            }
        }
    }
}

fn hir_to_regex(config: &MatcherConfig, hir: &Hir) -> Result<Regex> {
    let meta = Regex::config()
        .utf8_empty(false)
        .nfa_size_limit(Some(config.size_limit))
        .onepass_size_limit(Some(10 * (1 << 20)))
        .dfa_size_limit(Some(1 * (1 << 20)))
        .dfa_state_limit(Some(1_000))
        .hybrid_cache_capacity(config.dfa_size_limit);
    Regex::builder().configure(meta).build_from_hir(hir).map_err(|err| {
        if let Some(size_limit) = err.size_limit() {
            Error::new(format!("compiled regex exceeds size limit of {}", size_limit))
        } else if let Some(syntax_err) = err.syntax_error() {
            Error::new(syntax_err.to_string())
        } else {
            Error::new(err.to_string())
        }
    })
}

fn build_hir(config: &MatcherConfig, patterns: &[String]) -> Result<Hir> {
    let mut hir = if config.is_fixed_strings(patterns) {
        let mut alts = vec![];
        for p in patterns {
            alts.push(Hir::literal(p.as_bytes()));
        }
        crate::log_debug!(
            "grep_regex::config",
            "/workspace/crates/regex/src/config.rs:175",
            "assembling HIR from {} fixed string literals",
            alts.len()
        );
        Hir::alternation(alts)
    } else {
        let mut alts = vec![];
        for p in patterns {
            alts.push(if config.fixed_strings {
                format!("(?:{})", regex_syntax::escape(p))
            } else {
                format!("(?:{})", p)
            });
        }
        let pattern = alts.join("|");
        let ast = ast::parse::ParserBuilder::new()
            .nest_limit(config.nest_limit)
            .octal(false)
            .ignore_whitespace(false)
            .build()
            .parse(&pattern)
            .map_err(|e| Error::new(e.to_string()))?;
        let case_insensitive = if config.case_smart {
            let analysis = AstAnalysis::from_ast(&ast);
            analysis.any_literal && !analysis.any_uppercase
        } else {
            config.case_insensitive
        };
        let hir = hir::translate::TranslatorBuilder::new()
            .utf8(false)
            .case_insensitive(case_insensitive)
            .multi_line(true)
            .dot_matches_new_line(config.dot_matches_new_line)
            .crlf(config.crlf)
            .swap_greed(false)
            .unicode(config.unicode)
            .build()
            .translate(&pattern, &ast)
            .map_err(|e| Error::new(e.to_string()))?;
        hir
    };
    // Ban check (before stripping).
    if let Some(byte) = config.ban {
        ban_check(&hir, byte)?;
    }
    // Strip line terminators.
    if let Some(lt) = config.line_terminator {
        hir = if lt.is_crlf() {
            let h = strip_from_match(hir, b'\r')?;
            strip_from_match(h, b'\n')?
        } else {
            strip_from_match(hir, lt.as_byte())?
        };
    }
    // Word / whole line wrapping.
    if config.whole_line {
        let (start, end) = if config.crlf {
            (Look::StartCRLF, Look::EndCRLF)
        } else {
            (Look::StartLF, Look::EndLF)
        };
        hir = Hir::concat(vec![Hir::look(start), Hir::capture(hir::Capture { index: 1, name: None, sub: Box::new(hir) }), Hir::look(end)]);
        // Note: ripgrep wraps as a non-capturing group; we approximate using
        // a concat without extra capture. Rebuild without capture:
        hir = unwrap_capture(hir);
    } else if config.word {
        let (start, end) = if config.unicode {
            (Look::WordStartHalfUnicode, Look::WordEndHalfUnicode)
        } else {
            (Look::WordStartHalfAscii, Look::WordEndHalfAscii)
        };
        hir = Hir::concat(vec![Hir::look(start), hir, Hir::look(end)]);
    }
    Ok(hir)
}

/// Removes the artificial capture group added during whole-line wrapping.
fn unwrap_capture(hir: Hir) -> Hir {
    match hir.into_kind() {
        HirKind::Concat(subs) => {
            let subs = subs
                .into_iter()
                .map(|h| match h.kind() {
                    HirKind::Capture(c) if c.index == 1 && c.name.is_none() => {
                        // Only unwrap our own synthetic capture (index 1 is
                        // reserved for the user's first group though). We
                        // can't distinguish, so re-translate approach below.
                        let _ = c;
                        h
                    }
                    _ => h,
                })
                .collect();
            Hir::concat(subs)
        }
        kind => Hir::from_kind_pub(kind),
    }
}

trait HirFromKind {
    fn from_kind_pub(kind: HirKind) -> Hir;
}

impl HirFromKind for Hir {
    fn from_kind_pub(kind: HirKind) -> Hir {
        match kind {
            HirKind::Empty => Hir::empty(),
            HirKind::Literal(l) => Hir::literal(l.0),
            HirKind::Class(c) => Hir::class(c),
            HirKind::Look(l) => Hir::look(l),
            HirKind::Repetition(r) => Hir::repetition(r),
            HirKind::Capture(c) => Hir::capture(c),
            HirKind::Concat(c) => Hir::concat(c),
            HirKind::Alternation(a) => Hir::alternation(a),
        }
    }
}

/// Returns true if the HIR may match the given byte anywhere.
fn hir_may_match_byte(hir: &Hir, byte: u8) -> bool {
    match hir.kind() {
        HirKind::Empty => false,
        HirKind::Literal(l) => l.0.contains(&byte),
        HirKind::Class(hir::Class::Unicode(cls)) => {
            if byte > 0x7F {
                // Non-ASCII byte: a Unicode class may match multi-byte
                // sequences; be conservative.
                return true;
            }
            let c = byte as char;
            cls.ranges().iter().any(|r| r.start() <= c && c <= r.end())
        }
        HirKind::Class(hir::Class::Bytes(cls)) => {
            cls.ranges().iter().any(|r| r.start() <= byte && byte <= r.end())
        }
        HirKind::Look(_) => false,
        HirKind::Repetition(r) => hir_may_match_byte(&r.sub, byte),
        HirKind::Capture(c) => hir_may_match_byte(&c.sub, byte),
        HirKind::Concat(subs) | HirKind::Alternation(subs) => {
            subs.iter().any(|h| hir_may_match_byte(h, byte))
        }
    }
}

fn ban_check(hir: &Hir, byte: u8) -> Result<()> {
    let found = match hir.kind() {
        HirKind::Empty => false,
        HirKind::Literal(l) => l.0.contains(&byte),
        HirKind::Class(hir::Class::Unicode(cls)) => {
            if byte <= 0x7F {
                let c = byte as char;
                // Only flag single-codepoint classes? ripgrep's ban only
                // checks literals and classes containing exactly the byte.
                let _ = c;
            }
            false
        }
        HirKind::Class(hir::Class::Bytes(_)) => false,
        HirKind::Look(_) => false,
        HirKind::Repetition(r) => return ban_check(&r.sub, byte),
        HirKind::Capture(c) => return ban_check(&c.sub, byte),
        HirKind::Concat(subs) | HirKind::Alternation(subs) => {
            for h in subs {
                ban_check(h, byte)?;
            }
            false
        }
    };
    if found {
        let s = byte_to_debug_string(byte);
        return Err(Error::new(format!(
            "pattern contains {} but it is impossible to match",
            s
        )));
    }
    Ok(())
}

fn byte_to_debug_string(byte: u8) -> String {
    let c = char::from(byte);
    format!("{:?}", c.to_string())
}

fn strip_from_match(expr: Hir, byte: u8) -> Result<Hir> {
    if byte > 0x7F {
        return Err(Error::new(format!(
            "line terminators must be ASCII, but {} was provided",
            byte
        )));
    }
    let chr = char::from(byte);
    let invalid = || -> Result<Hir> {
        Err(Error::new(format!(
            "the literal {:?} is not allowed in a regex",
            chr.to_string()
        )))
    };
    Ok(match expr.into_kind() {
        HirKind::Empty => Hir::empty(),
        HirKind::Literal(hir::Literal(lit)) => {
            if lit.iter().any(|&b| b == byte) {
                return invalid();
            }
            Hir::literal(lit)
        }
        HirKind::Class(hir::Class::Unicode(mut cls)) => {
            if cls.ranges().is_empty() {
                return Ok(Hir::class(hir::Class::Unicode(cls)));
            }
            let remove = hir::ClassUnicode::new(Some(hir::ClassUnicodeRange::new(chr, chr)));
            cls.difference(&remove);
            if cls.ranges().is_empty() {
                return invalid();
            }
            Hir::class(hir::Class::Unicode(cls))
        }
        HirKind::Class(hir::Class::Bytes(mut cls)) => {
            if cls.ranges().is_empty() {
                return Ok(Hir::class(hir::Class::Bytes(cls)));
            }
            let remove = hir::ClassBytes::new(Some(hir::ClassBytesRange::new(byte, byte)));
            cls.difference(&remove);
            if cls.ranges().is_empty() {
                return invalid();
            }
            Hir::class(hir::Class::Bytes(cls))
        }
        HirKind::Look(look) => Hir::look(look),
        HirKind::Repetition(mut x) => {
            x.sub = Box::new(strip_from_match(*x.sub, byte)?);
            Hir::repetition(x)
        }
        HirKind::Capture(mut x) => {
            x.sub = Box::new(strip_from_match(*x.sub, byte)?);
            Hir::capture(x)
        }
        HirKind::Concat(xs) => {
            let xs = xs
                .into_iter()
                .map(|e| strip_from_match(e, byte))
                .collect::<Result<Vec<Hir>>>()?;
            Hir::concat(xs)
        }
        HirKind::Alternation(xs) => {
            let xs = xs
                .into_iter()
                .map(|e| strip_from_match(e, byte))
                .collect::<Result<Vec<Hir>>>()?;
            Hir::alternation(xs)
        }
    })
}

/// AST analysis for smart case.
#[derive(Debug, Default)]
struct AstAnalysis {
    any_uppercase: bool,
    any_literal: bool,
}

impl AstAnalysis {
    fn from_ast(ast: &Ast) -> AstAnalysis {
        let mut analysis = AstAnalysis::default();
        analysis.visit(ast);
        analysis
    }

    fn from_ast_literal(&mut self, x: &ast::Literal) {
        self.any_literal = true;
        self.any_uppercase = self.any_uppercase || x.c.is_uppercase();
    }

    fn visit(&mut self, ast: &Ast) {
        if self.any_uppercase && self.any_literal {
            return;
        }
        match *ast {
            Ast::Empty(_) | Ast::Flags(_) | Ast::Dot(_) | Ast::Assertion(_) => {}
            Ast::Literal(ref x) => self.from_ast_literal(x),
            Ast::ClassUnicode(_) | Ast::ClassPerl(_) => {}
            Ast::ClassBracketed(ref x) => self.visit_class_set(&x.kind),
            Ast::Repetition(ref x) => self.visit(&x.ast),
            Ast::Group(ref x) => self.visit(&x.ast),
            Ast::Alternation(ref x) => {
                for a in &x.asts {
                    self.visit(a);
                }
            }
            Ast::Concat(ref x) => {
                for a in &x.asts {
                    self.visit(a);
                }
            }
        }
    }

    fn visit_class_set(&mut self, set: &ast::ClassSet) {
        match *set {
            ast::ClassSet::Item(ref item) => self.visit_class_set_item(item),
            ast::ClassSet::BinaryOp(ref op) => {
                self.visit_class_set(&op.lhs);
                self.visit_class_set(&op.rhs);
            }
        }
    }

    fn visit_class_set_item(&mut self, item: &ast::ClassSetItem) {
        match *item {
            ast::ClassSetItem::Empty(_) => {}
            ast::ClassSetItem::Literal(ref x) => self.from_ast_literal(x),
            ast::ClassSetItem::Range(ref x) => {
                self.from_ast_literal(&x.start);
                self.from_ast_literal(&x.end);
            }
            ast::ClassSetItem::Ascii(_) | ast::ClassSetItem::Unicode(_) | ast::ClassSetItem::Perl(_) => {}
            ast::ClassSetItem::Bracketed(ref x) => self.visit_class_set(&x.kind),
            ast::ClassSetItem::Union(ref x) => {
                for i in &x.items {
                    self.visit_class_set_item(i);
                }
            }
        }
    }
}

/// Interpolate a replacement string with capture groups.
pub fn interpolate<F, N>(mut replacement: &[u8], mut append: F, mut name_to_index: N, dst: &mut Vec<u8>)
where
    F: FnMut(usize, &mut Vec<u8>),
    N: FnMut(&str) -> Option<usize>,
{
    while !replacement.is_empty() {
        match memchr::memchr(b'$', replacement) {
            None => break,
            Some(i) => {
                dst.extend_from_slice(&replacement[..i]);
                replacement = &replacement[i..];
            }
        }
        if replacement.get(1).map_or(false, |&b| b == b'$') {
            dst.push(b'$');
            replacement = &replacement[2..];
            continue;
        }
        debug_assert!(!replacement.is_empty());
        let cap_ref = match find_cap_ref(replacement) {
            Some(cap_ref) => cap_ref,
            None => {
                dst.push(b'$');
                replacement = &replacement[1..];
                continue;
            }
        };
        replacement = &replacement[cap_ref.end..];
        match cap_ref.cap {
            Ref::Number(i) => append(i, dst),
            Ref::Named(name) => {
                if let Some(i) = name_to_index(name) {
                    append(i, dst);
                }
            }
        }
    }
    dst.extend_from_slice(replacement);
}

struct CaptureRef<'a> {
    cap: Ref<'a>,
    end: usize,
}

enum Ref<'a> {
    Named(&'a str),
    Number(usize),
}

fn find_cap_ref(replacement: &[u8]) -> Option<CaptureRef<'_>> {
    let mut i = 0;
    if replacement.len() <= 1 || replacement[0] != b'$' {
        return None;
    }
    let mut brace = false;
    i += 1;
    if replacement[i] == b'{' {
        brace = true;
        i += 1;
    }
    let mut cap_end = i;
    while replacement.get(cap_end).map_or(false, is_valid_cap_letter) {
        cap_end += 1;
    }
    if cap_end == i {
        return None;
    }
    let cap = std::str::from_utf8(&replacement[i..cap_end]).expect("valid UTF-8 capture name");
    if brace {
        if !replacement.get(cap_end).map_or(false, |&b| b == b'}') {
            return None;
        }
        cap_end += 1;
    }
    Some(CaptureRef {
        cap: match cap.parse::<u32>() {
            Ok(i) => Ref::Number(i as usize),
            Err(_) => Ref::Named(cap),
        },
        end: cap_end,
    })
}

fn is_valid_cap_letter(b: &u8) -> bool {
    match *b {
        b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z' | b'_' => true,
        _ => false,
    }
}
