//! A buffer for incrementally reading lines from a reader.

use std::io;

pub const DEFAULT_BUFFER_CAPACITY: usize = 64 * (1 << 10);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinaryDetection {
    None,
    Quit(u8),
    Convert(u8),
}

impl BinaryDetection {
    pub fn is_quit(&self) -> bool {
        matches!(*self, BinaryDetection::Quit(_))
    }
    pub fn quit_byte(&self) -> Option<u8> {
        match *self {
            BinaryDetection::Quit(b) => Some(b),
            _ => None,
        }
    }
    pub fn convert_byte(&self) -> Option<u8> {
        match *self {
            BinaryDetection::Convert(b) => Some(b),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct LineBufferConfig {
    pub capacity: usize,
    pub lineterm: u8,
    pub binary: BinaryDetection,
}

pub struct LineBufferReader<'b, R> {
    rdr: R,
    line_buffer: &'b mut LineBuffer,
}

impl<'b, R: io::Read> LineBufferReader<'b, R> {
    pub fn new(rdr: R, line_buffer: &'b mut LineBuffer) -> LineBufferReader<'b, R> {
        line_buffer.clear();
        LineBufferReader { rdr, line_buffer }
    }
    pub fn absolute_byte_offset(&self) -> u64 {
        self.line_buffer.absolute_byte_offset()
    }
    pub fn binary_byte_offset(&self) -> Option<u64> {
        self.line_buffer.binary_byte_offset()
    }
    pub fn fill(&mut self) -> Result<bool, io::Error> {
        self.line_buffer.fill(&mut self.rdr)
    }
    pub fn buffer(&self) -> &[u8] {
        self.line_buffer.buffer()
    }
    pub fn consume(&mut self, amt: usize) {
        self.line_buffer.consume(amt);
    }
}

#[derive(Debug)]
pub struct LineBuffer {
    config: LineBufferConfig,
    buf: Vec<u8>,
    pos: usize,
    last_lineterm: usize,
    end: usize,
    absolute_byte_offset: u64,
    binary_byte_offset: Option<u64>,
}

impl LineBuffer {
    pub fn new(config: LineBufferConfig) -> LineBuffer {
        let buf = vec![0; config.capacity];
        LineBuffer {
            config,
            buf,
            pos: 0,
            last_lineterm: 0,
            end: 0,
            absolute_byte_offset: 0,
            binary_byte_offset: None,
        }
    }

    pub fn set_binary_detection(&mut self, binary: BinaryDetection) {
        self.config.binary = binary;
    }

    pub fn set_line_terminator(&mut self, lineterm: u8) {
        self.config.lineterm = lineterm;
    }

    fn clear(&mut self) {
        self.pos = 0;
        self.last_lineterm = 0;
        self.end = 0;
        self.absolute_byte_offset = 0;
        self.binary_byte_offset = None;
    }

    fn absolute_byte_offset(&self) -> u64 {
        self.absolute_byte_offset
    }

    fn binary_byte_offset(&self) -> Option<u64> {
        self.binary_byte_offset
    }

    fn buffer(&self) -> &[u8] {
        &self.buf[self.pos..self.last_lineterm]
    }

    fn free_buffer(&mut self) -> &mut [u8] {
        &mut self.buf[self.end..]
    }

    fn consume(&mut self, amt: usize) {
        assert!(amt <= self.buffer().len());
        self.pos += amt;
        self.absolute_byte_offset += amt as u64;
    }

    fn fill<R: io::Read>(&mut self, mut rdr: R) -> Result<bool, io::Error> {
        if self.binary_byte_offset.is_some() && self.config.binary.is_quit() {
            return Ok(!self.buffer().is_empty());
        }
        self.roll();
        assert_eq!(self.pos, 0);
        loop {
            self.ensure_capacity()?;
            let readlen = rdr.read(self.free_buffer())?;
            if readlen == 0 {
                self.last_lineterm = self.end;
                return Ok(!self.buffer().is_empty());
            }
            let oldend = self.end;
            self.end += readlen;
            let newbytes = &mut self.buf[oldend..self.end];

            match self.config.binary {
                BinaryDetection::None => {}
                BinaryDetection::Quit(byte) => {
                    if let Some(i) = memchr::memchr(byte, newbytes) {
                        self.end = oldend + i;
                        self.last_lineterm = self.end;
                        self.binary_byte_offset = Some(self.absolute_byte_offset + self.end as u64);
                        return Ok(self.pos < self.end);
                    }
                }
                BinaryDetection::Convert(byte) => {
                    if let Some(i) = replace_bytes(newbytes, byte, self.config.lineterm) {
                        if self.binary_byte_offset.is_none() {
                            self.binary_byte_offset =
                                Some(self.absolute_byte_offset + (oldend + i) as u64);
                        }
                    }
                }
            }

            if let Some(i) = memchr::memrchr(self.config.lineterm, newbytes) {
                self.last_lineterm = oldend + i + 1;
                return Ok(true);
            }
        }
    }

    fn roll(&mut self) {
        if self.pos == self.end {
            self.pos = 0;
            self.last_lineterm = 0;
            self.end = 0;
            return;
        }
        let roll_len = self.end - self.pos;
        self.buf.copy_within(self.pos..self.end, 0);
        self.pos = 0;
        self.last_lineterm = roll_len;
        self.end = roll_len;
    }

    fn ensure_capacity(&mut self) -> Result<(), io::Error> {
        if !self.free_buffer().is_empty() {
            return Ok(());
        }
        let len = std::cmp::max(1, self.buf.len());
        let additional = len * 2;
        let newlen = self.buf.len() + additional;
        self.buf.resize(newlen, 0);
        assert!(!self.free_buffer().is_empty());
        Ok(())
    }
}

/// Replaces `src` with `replacement` in bytes, and return the offset of the
/// first replacement, if one exists.
fn replace_bytes(mut bytes: &mut [u8], src: u8, replacement: u8) -> Option<usize> {
    if src == replacement {
        return None;
    }
    let first_pos = memchr::memchr(src, bytes)?;
    bytes[first_pos] = replacement;
    bytes = &mut bytes[first_pos + 1..];
    while let Some(i) = memchr::memchr(src, bytes) {
        bytes[i] = replacement;
        bytes = &mut bytes[i + 1..];
    }
    Some(first_pos)
}
