//! The searcher: drives a matcher over input and reports to a sink.

pub mod line_buffer;
pub mod lines;

use std::cell::RefCell;
use std::fs::File;
use std::io::{self, Read};
use std::path::Path;

use crate::encoding::{DecodeReader, Encoding};
use crate::matcher::{LineTerminator, RegexMatcher};

pub use self::line_buffer::BinaryDetection;
use self::line_buffer::{LineBuffer, LineBufferConfig, LineBufferReader, DEFAULT_BUFFER_CAPACITY};
use self::lines::LineStep;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SinkContextKind {
    Before,
    After,
    Other,
}

pub struct SinkMatch<'b> {
    pub line_term: LineTerminator,
    pub bytes: &'b [u8],
    pub absolute_byte_offset: u64,
    pub line_number: Option<u64>,
    pub buffer: &'b [u8],
    pub bytes_range_in_buffer: std::ops::Range<usize>,
}

impl<'b> SinkMatch<'b> {
    /// Returns the number of lines in this match (counting a trailing line
    /// without a terminator as a line).
    pub fn line_count(&self) -> u64 {
        let mut n = lines::count(self.bytes, self.line_term.as_byte());
        if self.bytes.last().map_or(false, |&b| b != self.line_term.as_byte()) {
            n += 1;
        }
        if self.bytes.is_empty() {
            n = 0;
        }
        n
    }
}

pub struct SinkContext<'b> {
    pub line_term: LineTerminator,
    pub bytes: &'b [u8],
    pub kind: SinkContextKind,
    pub absolute_byte_offset: u64,
    pub line_number: Option<u64>,
}

pub struct SinkFinish {
    pub byte_count: u64,
    pub binary_byte_offset: Option<u64>,
}

/// A sink receives search results.
pub trait Sink {
    fn matched(&mut self, searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool>;
    fn context(&mut self, _searcher: &Searcher, _ctx: &SinkContext<'_>) -> io::Result<bool> {
        Ok(true)
    }
    fn context_break(&mut self, _searcher: &Searcher) -> io::Result<bool> {
        Ok(true)
    }
    fn binary_data(&mut self, _searcher: &Searcher, _offset: u64) -> io::Result<bool> {
        Ok(true)
    }
    fn begin(&mut self, _searcher: &Searcher) -> io::Result<bool> {
        Ok(true)
    }
    fn finish(&mut self, _searcher: &Searcher, _finish: &SinkFinish) -> io::Result<()> {
        Ok(())
    }
}

#[derive(Debug, Clone)]
pub struct SearcherConfig {
    pub line_term: LineTerminator,
    pub invert_match: bool,
    pub after_context: usize,
    pub before_context: usize,
    pub passthru: bool,
    pub line_number: bool,
    pub binary: BinaryDetection,
    pub multi_line: bool,
    /// None = auto (BOM sniffing); Some(None) = disabled; Some(Some(e)) = explicit.
    pub encoding: Option<Encoding>,
    pub bom_sniffing: bool,
    pub stop_on_nonmatch: bool,
}

impl Default for SearcherConfig {
    fn default() -> SearcherConfig {
        SearcherConfig {
            line_term: LineTerminator::default(),
            invert_match: false,
            after_context: 0,
            before_context: 0,
            passthru: false,
            line_number: true,
            binary: BinaryDetection::None,
            multi_line: false,
            encoding: None,
            bom_sniffing: true,
            stop_on_nonmatch: false,
        }
    }
}

impl SearcherConfig {
    fn max_context(&self) -> usize {
        std::cmp::max(self.before_context, self.after_context)
    }
}

/// A searcher.
#[derive(Debug)]
pub struct Searcher {
    config: SearcherConfig,
    line_buffer: RefCell<LineBuffer>,
    multi_line_buffer: RefCell<Vec<u8>>,
}

impl Searcher {
    pub fn new(config: SearcherConfig) -> Searcher {
        let lb = LineBuffer::new(LineBufferConfig {
            capacity: DEFAULT_BUFFER_CAPACITY,
            lineterm: config.line_term.as_byte(),
            binary: config.binary,
        });
        Searcher {
            config,
            line_buffer: RefCell::new(lb),
            multi_line_buffer: RefCell::new(vec![]),
        }
    }

    pub fn config(&self) -> &SearcherConfig {
        &self.config
    }
    pub fn line_terminator(&self) -> LineTerminator {
        self.config.line_term
    }
    pub fn invert_match(&self) -> bool {
        self.config.invert_match
    }
    pub fn line_number(&self) -> bool {
        self.config.line_number
    }
    pub fn multi_line(&self) -> bool {
        self.config.multi_line
    }
    pub fn after_context(&self) -> usize {
        self.config.after_context
    }
    pub fn before_context(&self) -> usize {
        self.config.before_context
    }
    pub fn passthru(&self) -> bool {
        self.config.passthru
    }
    pub fn binary_detection(&self) -> BinaryDetection {
        self.config.binary
    }
    pub fn set_binary_detection(&mut self, detection: BinaryDetection) {
        self.config.binary = detection;
        self.line_buffer.borrow_mut().set_binary_detection(detection);
    }

    /// Returns true if multi-line search should be used for the matcher.
    pub fn multi_line_with_matcher(&self, matcher: &RegexMatcher) -> bool {
        if !self.config.multi_line {
            return false;
        }
        if let Some(line_term) = matcher.line_terminator() {
            if line_term == self.config.line_term {
                return false;
            }
        }
        if !matcher.can_match_line_terminator(self.config.line_term.as_byte()) {
            return false;
        }
        true
    }

    /// Search a file path (opening the file). If `use_slice` is true, the
    /// file is read into memory and searched as a slice (mmap emulation).
    pub fn search_path<S: Sink>(
        &mut self,
        matcher: &RegexMatcher,
        path: &Path,
        use_slice: bool,
        sink: S,
    ) -> io::Result<()> {
        let file = File::open(path)?;
        self.search_file_maybe_path(matcher, Some(path), &file, use_slice, sink)
    }

    pub fn search_file<S: Sink>(
        &mut self,
        matcher: &RegexMatcher,
        file: &File,
        use_slice: bool,
        sink: S,
    ) -> io::Result<()> {
        self.search_file_maybe_path(matcher, None, file, use_slice, sink)
    }

    fn search_file_maybe_path<S: Sink>(
        &mut self,
        matcher: &RegexMatcher,
        path: Option<&Path>,
        file: &File,
        use_slice: bool,
        sink: S,
    ) -> io::Result<()> {
        if use_slice {
            // Emulate a memory map: read the whole file into memory.
            let mut file = file;
            let len = file.metadata().map(|m| m.len()).unwrap_or(0);
            if len == 0 {
                // mmap of an empty file isn't used; fall through to reader.
            } else {
                let mut data = Vec::with_capacity(len as usize);
                file.read_to_end(&mut data)?;
                crate::log_trace!(
                    "grep_searcher::searcher",
                    "crates/searcher/src/searcher/mod.rs:720",
                    "{:?}: searching via memory map",
                    path
                );
                return self.search_slice(matcher, &data, sink);
            }
        }
        if self.multi_line_with_matcher(matcher) {
            crate::log_trace!(
                "grep_searcher::searcher",
                "crates/searcher/src/searcher/mod.rs:730",
                "{:?}: reading entire file on to heap for mulitline",
                path
            );
            self.fill_multi_line_buffer_from_reader(file)?;
            crate::log_trace!(
                "grep_searcher::searcher",
                "crates/searcher/src/searcher/mod.rs:735",
                "{:?}: searching via multiline strategy",
                path
            );
            let buf = self.multi_line_buffer.borrow();
            MultiLine::new(self, matcher, &buf, sink).run()
        } else {
            crate::log_trace!(
                "grep_searcher::searcher",
                "crates/searcher/src/searcher/mod.rs:742",
                "{:?}: searching using generic reader",
                path
            );
            self.search_reader(matcher, file, sink)
        }
    }

    fn needs_decoder(&self) -> bool {
        self.config.encoding.is_some() || self.config.bom_sniffing
    }

    fn wrap_decoder<'r, R: Read + 'r>(&self, rdr: R) -> Box<dyn Read + 'r> {
        if !self.needs_decoder() {
            Box::new(rdr)
        } else {
            Box::new(DecodeReader::new(rdr, self.config.encoding))
        }
    }

    pub fn search_reader<S: Sink, R: Read>(
        &mut self,
        matcher: &RegexMatcher,
        read_from: R,
        sink: S,
    ) -> io::Result<()> {
        let decoder = self.wrap_decoder(read_from);
        if self.multi_line_with_matcher(matcher) {
            self.fill_multi_line_buffer_from_reader(decoder)?;
            let buf = self.multi_line_buffer.borrow();
            MultiLine::new(self, matcher, &buf, sink).run()
        } else {
            let mut line_buffer = self.line_buffer.borrow_mut();
            line_buffer.set_binary_detection(self.config.binary);
            line_buffer.set_line_terminator(self.config.line_term.as_byte());
            let rdr = LineBufferReader::new(decoder, &mut line_buffer);
            ReadByLine::new(self, matcher, rdr, sink).run()
        }
    }

    pub fn search_slice<S: Sink>(
        &mut self,
        matcher: &RegexMatcher,
        slice: &[u8],
        sink: S,
    ) -> io::Result<()> {
        if self.slice_needs_transcoding(slice) {
            return self.search_reader(matcher, slice, sink);
        }
        if self.multi_line_with_matcher(matcher) {
            MultiLine::new(self, matcher, slice, sink).run()
        } else {
            SliceByLine::new(self, matcher, slice, sink).run()
        }
    }

    fn slice_needs_transcoding(&self, slice: &[u8]) -> bool {
        self.config.encoding.is_some() || (self.config.bom_sniffing && slice_has_bom(slice))
    }

    fn fill_multi_line_buffer_from_reader<R: Read>(&self, mut read_from: R) -> io::Result<()> {
        let mut buf = self.multi_line_buffer.borrow_mut();
        buf.clear();
        read_from.read_to_end(&mut buf)?;
        if let BinaryDetection::Convert(byte) = self.config.binary {
            // Convert is applied during search via detect_binary in the core;
            // but the data itself is immutable in the slice path. Mirror
            // grep-searcher: for multi-line via reader, the buffer is filled
            // directly (no conversion).
            let _ = byte;
        }
        Ok(())
    }
}

fn slice_has_bom(slice: &[u8]) -> bool {
    (slice.len() >= 3 && slice[0] == 0xEF && slice[1] == 0xBB && slice[2] == 0xBF)
        || (slice.len() >= 2
            && ((slice[0] == 0xFF && slice[1] == 0xFE) || (slice[0] == 0xFE && slice[1] == 0xFF)))
}

type Range = (usize, usize);

fn range_is_empty(r: &Range) -> bool {
    r.0 >= r.1
}

/// Core search logic shared by all strategies.
struct Core<'s, S: Sink> {
    config: &'s SearcherConfig,
    matcher: &'s RegexMatcher,
    searcher: &'s Searcher,
    sink: S,
    binary: bool,
    pos: usize,
    absolute_byte_offset: u64,
    binary_byte_offset: Option<usize>,
    line_number: Option<u64>,
    last_line_counted: usize,
    last_line_visited: usize,
    after_context_left: usize,
    has_sunk: bool,
    has_matched: bool,
}

impl<'s, S: Sink> Core<'s, S> {
    fn new(searcher: &'s Searcher, matcher: &'s RegexMatcher, sink: S, binary: bool) -> Core<'s, S> {
        let line_number = if searcher.config.line_number { Some(1) } else { None };
        Core {
            config: &searcher.config,
            matcher,
            searcher,
            sink,
            binary,
            pos: 0,
            absolute_byte_offset: 0,
            binary_byte_offset: None,
            line_number,
            last_line_counted: 0,
            last_line_visited: 0,
            after_context_left: 0,
            has_sunk: false,
            has_matched: false,
        }
    }

    fn pos(&self) -> usize {
        self.pos
    }
    fn set_pos(&mut self, pos: usize) {
        self.pos = pos;
    }
    fn binary_byte_offset(&self) -> Option<u64> {
        self.binary_byte_offset.map(|o| o as u64)
    }
    fn matched(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        self.sink_matched(buf, range)
    }
    fn binary_data(&mut self, binary_byte_offset: u64) -> io::Result<bool> {
        self.sink.binary_data(self.searcher, binary_byte_offset)
    }
    fn begin(&mut self) -> io::Result<bool> {
        self.sink.begin(self.searcher)
    }
    fn finish(&mut self, byte_count: u64, binary_byte_offset: Option<u64>) -> io::Result<()> {
        self.sink.finish(self.searcher, &SinkFinish { byte_count, binary_byte_offset })
    }

    fn match_by_line(&mut self, buf: &[u8]) -> io::Result<bool> {
        if self.is_line_by_line_fast() {
            self.match_by_line_fast(buf)
        } else {
            self.match_by_line_slow(buf)
        }
    }

    fn roll(&mut self, buf: &[u8]) -> usize {
        let consumed = if self.config.max_context() == 0 {
            buf.len()
        } else {
            let context_start =
                lines::preceding(buf, self.config.line_term.as_byte(), self.config.max_context());
            std::cmp::max(context_start, self.last_line_visited)
        };
        self.count_lines(buf, consumed);
        self.absolute_byte_offset += consumed as u64;
        self.last_line_counted = 0;
        self.last_line_visited = 0;
        self.set_pos(buf.len() - consumed);
        consumed
    }

    fn detect_binary(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        if self.binary_byte_offset.is_some() {
            return Ok(self.config.binary.quit_byte().is_some());
        }
        let binary_byte = match self.config.binary {
            BinaryDetection::Quit(b) => b,
            BinaryDetection::Convert(b) => b,
            _ => return Ok(false),
        };
        if let Some(i) = memchr::memchr(binary_byte, &buf[range.0..range.1]) {
            let offset = range.0 + i;
            self.binary_byte_offset = Some(offset);
            if !self.binary_data(offset as u64)? {
                return Ok(true);
            }
            Ok(self.config.binary.quit_byte().is_some())
        } else {
            Ok(false)
        }
    }

    fn before_context_by_line(&mut self, buf: &[u8], upto: usize) -> io::Result<bool> {
        if self.config.before_context == 0 {
            return Ok(true);
        }
        let range = (self.last_line_visited, upto);
        if range_is_empty(&range) {
            return Ok(true);
        }
        let before_context_start = range.0
            + lines::preceding(
                &buf[range.0..range.1],
                self.config.line_term.as_byte(),
                self.config.before_context - 1,
            );
        let range = (before_context_start, range.1);
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), range.0, range.1);
        while let Some(line) = stepper.next(buf) {
            if !self.sink_break_context(line.0)? {
                return Ok(false);
            }
            if !self.sink_before_context(buf, &line)? {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn after_context_by_line(&mut self, buf: &[u8], upto: usize) -> io::Result<bool> {
        if self.after_context_left == 0 {
            return Ok(true);
        }
        let range = (self.last_line_visited, upto);
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), range.0, range.1);
        while let Some(line) = stepper.next(buf) {
            if !self.sink_after_context(buf, &line)? {
                return Ok(false);
            }
            if self.after_context_left == 0 {
                break;
            }
        }
        Ok(true)
    }

    fn other_context_by_line(&mut self, buf: &[u8], upto: usize) -> io::Result<bool> {
        let range = (self.last_line_visited, upto);
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), range.0, range.1);
        while let Some(line) = stepper.next(buf) {
            if !self.sink_other_context(buf, &line)? {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn match_by_line_slow(&mut self, buf: &[u8]) -> io::Result<bool> {
        let range = (self.pos(), buf.len());
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), range.0, range.1);
        while let Some(line) = stepper.next(buf) {
            let matched = {
                let slice = lines::without_terminator(&buf[line.0..line.1], self.config.line_term);
                self.matcher.shortest_match_at(slice, 0).is_some()
            };
            self.set_pos(line.1);
            let success = matched != self.config.invert_match;
            if success {
                self.has_matched = true;
                if !self.before_context_by_line(buf, line.0)? {
                    return Ok(false);
                }
                if !self.sink_matched(buf, &line)? {
                    return Ok(false);
                }
            } else if self.after_context_left >= 1 {
                if !self.sink_after_context(buf, &line)? {
                    return Ok(false);
                }
            } else if self.config.passthru {
                if !self.sink_other_context(buf, &line)? {
                    return Ok(false);
                }
            }
            if self.config.stop_on_nonmatch && !matched && self.has_matched {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn match_by_line_fast(&mut self, buf: &[u8]) -> io::Result<bool> {
        while !buf[self.pos()..].is_empty() {
            if self.config.stop_on_nonmatch && self.has_matched {
                return Ok(false);
            }
            if self.config.invert_match {
                if !self.match_by_line_fast_invert(buf)? {
                    return Ok(false);
                }
            } else if let Some(line) = self.find_by_line_fast(buf) {
                self.has_matched = true;
                if self.config.max_context() > 0 {
                    if !self.after_context_by_line(buf, line.0)? {
                        return Ok(false);
                    }
                    if !self.before_context_by_line(buf, line.0)? {
                        return Ok(false);
                    }
                }
                self.set_pos(line.1);
                if !self.sink_matched(buf, &line)? {
                    return Ok(false);
                }
            } else {
                break;
            }
        }
        if !self.after_context_by_line(buf, buf.len())? {
            return Ok(false);
        }
        self.set_pos(buf.len());
        Ok(true)
    }

    fn match_by_line_fast_invert(&mut self, buf: &[u8]) -> io::Result<bool> {
        let invert_match = match self.find_by_line_fast(buf) {
            None => {
                let range = (self.pos(), buf.len());
                self.set_pos(range.1);
                range
            }
            Some(line) => {
                let range = (self.pos(), line.0);
                self.set_pos(line.1);
                range
            }
        };
        if range_is_empty(&invert_match) {
            return Ok(true);
        }
        self.has_matched = true;
        if !self.after_context_by_line(buf, invert_match.0)? {
            return Ok(false);
        }
        if !self.before_context_by_line(buf, invert_match.0)? {
            return Ok(false);
        }
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), invert_match.0, invert_match.1);
        while let Some(line) = stepper.next(buf) {
            if !self.sink_matched(buf, &line)? {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn find_by_line_fast(&self, buf: &[u8]) -> Option<Range> {
        let mut pos = self.pos();
        while !buf[pos..].is_empty() {
            match self.matcher.shortest_match_at(&buf[pos..], 0) {
                None => return None,
                Some(i) => {
                    let line = lines::locate(buf, self.config.line_term.as_byte(), (pos + i, pos + i));
                    if line.0 == buf.len() {
                        pos = buf.len();
                        continue;
                    }
                    // Confirm the match on the line itself (without the
                    // terminator), to match line-by-line semantics.
                    let slice = lines::without_terminator(&buf[line.0..line.1], self.config.line_term);
                    if self.matcher.shortest_match_at(slice, 0).is_some() {
                        return Some(line);
                    }
                    pos = line.1;
                    continue;
                }
            }
        }
        None
    }

    fn sink_matched(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        if self.binary && self.detect_binary(buf, range)? {
            return Ok(false);
        }
        if !self.sink_break_context(range.0)? {
            return Ok(false);
        }
        self.count_lines(buf, range.0);
        let offset = self.absolute_byte_offset + range.0 as u64;
        let linebuf = &buf[range.0..range.1];
        let keepgoing = self.sink.matched(
            self.searcher,
            &SinkMatch {
                line_term: self.config.line_term,
                bytes: linebuf,
                absolute_byte_offset: offset,
                line_number: self.line_number,
                buffer: buf,
                bytes_range_in_buffer: range.0..range.1,
            },
        )?;
        if !keepgoing {
            return Ok(false);
        }
        self.last_line_visited = range.1;
        self.after_context_left = self.config.after_context;
        self.has_sunk = true;
        Ok(true)
    }

    fn sink_context_kind(&mut self, buf: &[u8], range: &Range, kind: SinkContextKind) -> io::Result<bool> {
        if self.binary && self.detect_binary(buf, range)? {
            return Ok(false);
        }
        self.count_lines(buf, range.0);
        let offset = self.absolute_byte_offset + range.0 as u64;
        let keepgoing = self.sink.context(
            self.searcher,
            &SinkContext {
                line_term: self.config.line_term,
                bytes: &buf[range.0..range.1],
                kind,
                absolute_byte_offset: offset,
                line_number: self.line_number,
            },
        )?;
        if !keepgoing {
            return Ok(false);
        }
        self.last_line_visited = range.1;
        if kind == SinkContextKind::After {
            self.after_context_left -= 1;
        }
        self.has_sunk = true;
        Ok(true)
    }

    fn sink_before_context(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        self.sink_context_kind(buf, range, SinkContextKind::Before)
    }

    fn sink_after_context(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        assert!(self.after_context_left >= 1);
        self.sink_context_kind(buf, range, SinkContextKind::After)
    }

    fn sink_other_context(&mut self, buf: &[u8], range: &Range) -> io::Result<bool> {
        self.sink_context_kind(buf, range, SinkContextKind::Other)
    }

    fn sink_break_context(&mut self, start_of_line: usize) -> io::Result<bool> {
        let is_gap = self.last_line_visited < start_of_line;
        let any_context = self.config.before_context > 0 || self.config.after_context > 0;
        if !any_context || !self.has_sunk || !is_gap {
            Ok(true)
        } else {
            self.sink.context_break(self.searcher)
        }
    }

    fn count_lines(&mut self, buf: &[u8], upto: usize) {
        if let Some(ref mut line_number) = self.line_number {
            if self.last_line_counted <= upto {
                let slice = &buf[self.last_line_counted..upto];
                let count = lines::count(slice, self.config.line_term.as_byte());
                *line_number += count;
                self.last_line_counted = upto;
            }
        }
    }

    fn is_line_by_line_fast(&self) -> bool {
        if self.config.passthru {
            return false;
        }
        if self.config.stop_on_nonmatch {
            return false;
        }
        if let Some(line_term) = self.matcher.line_terminator() {
            if line_term.is_crlf() {
                return false;
            }
            if line_term == self.config.line_term {
                return true;
            }
        }
        if !self.matcher.can_match_line_terminator(self.config.line_term.as_byte()) {
            return true;
        }
        false
    }
}

struct ReadByLine<'s, R, S: Sink> {
    config: &'s SearcherConfig,
    core: Core<'s, S>,
    rdr: LineBufferReader<'s, R>,
}

impl<'s, R: Read, S: Sink> ReadByLine<'s, R, S> {
    fn new(searcher: &'s Searcher, matcher: &'s RegexMatcher, rdr: LineBufferReader<'s, R>, sink: S) -> ReadByLine<'s, R, S> {
        ReadByLine { config: &searcher.config, core: Core::new(searcher, matcher, sink, false), rdr }
    }

    fn run(mut self) -> io::Result<()> {
        if self.core.begin()? {
            while self.fill()? && self.core.match_by_line(self.rdr.buffer())? {}
        }
        self.core.finish(self.rdr.absolute_byte_offset(), self.rdr.binary_byte_offset())
    }

    fn fill(&mut self) -> io::Result<bool> {
        assert!(self.rdr.buffer()[self.core.pos()..].is_empty());
        let already_binary = self.rdr.binary_byte_offset().is_some();
        let old_buf_len = self.rdr.buffer().len();
        let consumed = self.core.roll(self.rdr.buffer());
        self.rdr.consume(consumed);
        let didread = self.rdr.fill()?;
        if !already_binary {
            if let Some(offset) = self.rdr.binary_byte_offset() {
                if !self.core.binary_data(offset)? {
                    return Ok(false);
                }
            }
        }
        if !didread || self.should_binary_quit() {
            return Ok(false);
        }
        if consumed == 0 && old_buf_len == self.rdr.buffer().len() {
            return Err(io::Error::new(io::ErrorKind::Other, "buffer did not grow"));
        }
        Ok(true)
    }

    fn should_binary_quit(&self) -> bool {
        self.rdr.binary_byte_offset().is_some() && self.config.binary.quit_byte().is_some()
    }
}

struct SliceByLine<'s, S: Sink> {
    core: Core<'s, S>,
    slice: &'s [u8],
}

impl<'s, S: Sink> SliceByLine<'s, S> {
    fn new(searcher: &'s Searcher, matcher: &'s RegexMatcher, slice: &'s [u8], sink: S) -> SliceByLine<'s, S> {
        SliceByLine { core: Core::new(searcher, matcher, sink, true), slice }
    }

    fn run(mut self) -> io::Result<()> {
        if self.core.begin()? {
            let binary_upto = std::cmp::min(self.slice.len(), DEFAULT_BUFFER_CAPACITY);
            let binary_range = (0, binary_upto);
            if !self.core.detect_binary(self.slice, &binary_range)? {
                while !self.slice[self.core.pos()..].is_empty() && self.core.match_by_line(self.slice)? {}
            }
            let byte_count = self.byte_count();
            let binary_byte_offset = self.core.binary_byte_offset();
            self.core.finish(byte_count, binary_byte_offset)?;
        }
        Ok(())
    }

    fn byte_count(&mut self) -> u64 {
        match self.core.binary_byte_offset() {
            Some(offset) if offset < self.core.pos() as u64 => offset,
            _ => self.core.pos() as u64,
        }
    }
}

struct MultiLine<'s, S: Sink> {
    config: &'s SearcherConfig,
    core: Core<'s, S>,
    slice: &'s [u8],
    last_match: Option<Range>,
}

impl<'s, S: Sink> MultiLine<'s, S> {
    fn new(searcher: &'s Searcher, matcher: &'s RegexMatcher, slice: &'s [u8], sink: S) -> MultiLine<'s, S> {
        MultiLine {
            config: &searcher.config,
            core: Core::new(searcher, matcher, sink, true),
            slice,
            last_match: None,
        }
    }

    fn run(mut self) -> io::Result<()> {
        if self.core.begin()? {
            let binary_upto = std::cmp::min(self.slice.len(), DEFAULT_BUFFER_CAPACITY);
            let binary_range = (0, binary_upto);
            if !self.core.detect_binary(self.slice, &binary_range)? {
                let mut keepgoing = true;
                while !self.slice[self.core.pos()..].is_empty() && keepgoing {
                    keepgoing = self.sink()?;
                }
                if keepgoing {
                    keepgoing = match self.last_match.take() {
                        None => true,
                        Some(last_match) => {
                            if self.sink_context(&last_match)? {
                                self.sink_matched(&last_match)?;
                            }
                            true
                        }
                    };
                }
                if keepgoing {
                    if self.config.passthru {
                        self.core.other_context_by_line(self.slice, self.slice.len())?;
                    } else {
                        self.core.after_context_by_line(self.slice, self.slice.len())?;
                    }
                }
            }
            let byte_count = self.byte_count();
            let binary_byte_offset = self.core.binary_byte_offset();
            self.core.finish(byte_count, binary_byte_offset)?;
        }
        Ok(())
    }

    fn sink(&mut self) -> io::Result<bool> {
        if self.config.invert_match {
            return self.sink_matched_inverted();
        }
        let mat = match self.find() {
            Some(range) => range,
            None => {
                self.core.set_pos(self.slice.len());
                return Ok(true);
            }
        };
        self.advance(&mat);
        let line = lines::locate(self.slice, self.config.line_term.as_byte(), mat);
        match self.last_match.take() {
            None => {
                self.last_match = Some(line);
                Ok(true)
            }
            Some(last_match) => {
                if last_match.1 >= line.0 {
                    self.last_match = Some((last_match.0, line.1));
                    Ok(true)
                } else {
                    self.last_match = Some(line);
                    if !self.sink_context(&last_match)? {
                        return Ok(false);
                    }
                    self.sink_matched(&last_match)
                }
            }
        }
    }

    fn sink_matched_inverted(&mut self) -> io::Result<bool> {
        let invert_match = match self.find() {
            None => {
                let range = (self.core.pos(), self.slice.len());
                self.core.set_pos(range.1);
                range
            }
            Some(mat) => {
                let line = lines::locate(self.slice, self.config.line_term.as_byte(), mat);
                let range = (self.core.pos(), line.0);
                self.advance(&line);
                range
            }
        };
        if range_is_empty(&invert_match) {
            return Ok(true);
        }
        if !self.sink_context(&invert_match)? {
            return Ok(false);
        }
        let mut stepper = LineStep::new(self.config.line_term.as_byte(), invert_match.0, invert_match.1);
        while let Some(line) = stepper.next(self.slice) {
            if !self.sink_matched(&line)? {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn sink_matched(&mut self, range: &Range) -> io::Result<bool> {
        if range_is_empty(range) {
            return Ok(false);
        }
        self.core.matched(self.slice, range)
    }

    fn sink_context(&mut self, range: &Range) -> io::Result<bool> {
        if self.config.passthru {
            if !self.core.other_context_by_line(self.slice, range.0)? {
                return Ok(false);
            }
        } else {
            if !self.core.after_context_by_line(self.slice, range.0)? {
                return Ok(false);
            }
            if !self.core.before_context_by_line(self.slice, range.0)? {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn find(&mut self) -> Option<Range> {
        let pos = self.core.pos();
        self.core.matcher.find(&self.slice[pos..]).map(|(s, e)| (s + pos, e + pos))
    }

    fn advance(&mut self, range: &Range) {
        self.core.set_pos(range.1);
        if range_is_empty(range) && self.core.pos() < self.slice.len() {
            let newpos = self.core.pos() + 1;
            self.core.set_pos(newpos);
        }
    }

    fn byte_count(&mut self) -> u64 {
        match self.core.binary_byte_offset() {
            Some(offset) if offset < self.core.pos() as u64 => offset,
            _ => self.core.pos() as u64,
        }
    }
}
