//! Shared printer utilities.

use std::borrow::Cow;
use std::io;
use std::path::Path;

use crate::matcher::{LineTerminator, RegexMatcher};
use crate::searcher::{Searcher, SinkContext, SinkContextKind, SinkMatch};

pub type Match = (usize, usize);

pub fn match_len(m: &Match) -> usize {
    m.1 - m.0
}
pub fn match_is_empty(m: &Match) -> bool {
    m.0 >= m.1
}

const MAX_LOOK_AHEAD: usize = 128;

/// A simple layer of abstraction over either a match or a contextual line
/// reported by the searcher.
pub struct Sunk<'a> {
    bytes: &'a [u8],
    absolute_byte_offset: u64,
    line_number: Option<u64>,
    context_kind: Option<SinkContextKind>,
    matches: &'a [Match],
    original_matches: &'a [Match],
}

impl<'a> Sunk<'a> {
    pub fn empty() -> Sunk<'static> {
        Sunk {
            bytes: &[],
            absolute_byte_offset: 0,
            line_number: None,
            context_kind: None,
            matches: &[],
            original_matches: &[],
        }
    }

    pub fn from_sink_match(
        sunk: &'a SinkMatch<'a>,
        original_matches: &'a [Match],
        replacement: Option<(&'a [u8], &'a [Match])>,
    ) -> Sunk<'a> {
        let (bytes, matches) = replacement.unwrap_or_else(|| (sunk.bytes, original_matches));
        Sunk {
            bytes,
            absolute_byte_offset: sunk.absolute_byte_offset,
            line_number: sunk.line_number,
            context_kind: None,
            matches,
            original_matches,
        }
    }

    pub fn from_sink_context(
        sunk: &'a SinkContext<'a>,
        original_matches: &'a [Match],
        replacement: Option<(&'a [u8], &'a [Match])>,
    ) -> Sunk<'a> {
        let (bytes, matches) = replacement.unwrap_or_else(|| (sunk.bytes, original_matches));
        Sunk {
            bytes,
            absolute_byte_offset: sunk.absolute_byte_offset,
            line_number: sunk.line_number,
            context_kind: Some(sunk.kind),
            matches,
            original_matches,
        }
    }

    pub fn context_kind(&self) -> Option<SinkContextKind> {
        self.context_kind
    }
    pub fn bytes(&self) -> &'a [u8] {
        self.bytes
    }
    pub fn matches(&self) -> &'a [Match] {
        self.matches
    }
    pub fn original_matches(&self) -> &'a [Match] {
        self.original_matches
    }
    pub fn lines(&self, line_term: u8) -> LineIter<'a> {
        LineIter::new(line_term, self.bytes())
    }
    pub fn absolute_byte_offset(&self) -> u64 {
        self.absolute_byte_offset
    }
    pub fn line_number(&self) -> Option<u64> {
        self.line_number
    }
}

/// Iterate over lines (with terminators) in a byte slice.
pub struct LineIter<'b> {
    bytes: &'b [u8],
    stepper: crate::searcher::lines::LineStep,
}

impl<'b> LineIter<'b> {
    pub fn new(line_term: u8, bytes: &'b [u8]) -> LineIter<'b> {
        LineIter { bytes, stepper: crate::searcher::lines::LineStep::new(line_term, 0, bytes.len()) }
    }
}

impl<'b> Iterator for LineIter<'b> {
    type Item = &'b [u8];
    fn next(&mut self) -> Option<&'b [u8]> {
        self.stepper.next(self.bytes).map(|(s, e)| &self.bytes[s..e])
    }
}

/// A path for printing, with an optional separator replacement.
#[derive(Clone, Debug)]
pub struct PrinterPath<'a> {
    path: &'a Path,
    bytes: Cow<'a, [u8]>,
    hyperlink: std::cell::OnceCell<Option<crate::printer::hyperlink::HyperlinkPath>>,
}

impl<'a> PrinterPath<'a> {
    pub fn new(path: &'a Path) -> PrinterPath<'a> {
        use std::os::unix::ffi::OsStrExt;
        PrinterPath {
            path,
            bytes: Cow::Borrowed(path.as_os_str().as_bytes()),
            hyperlink: std::cell::OnceCell::new(),
        }
    }

    pub fn with_separator(path: &'a Path, sep: Option<u8>) -> PrinterPath<'a> {
        let mut ppath = PrinterPath::new(path);
        if let Some(sep) = sep {
            ppath.replace_separator(sep);
        }
        ppath
    }

    fn replace_separator(&mut self, new_sep: u8) {
        let transformed_path: Vec<u8> = self
            .bytes
            .iter()
            .map(|&b| if b == b'/' { new_sep } else { b })
            .collect();
        self.bytes = Cow::Owned(transformed_path);
    }

    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    pub fn as_path(&self) -> &Path {
        self.path
    }

    pub fn hyperlink_path(&self) -> Option<&crate::printer::hyperlink::HyperlinkPath> {
        self.hyperlink
            .get_or_init(|| crate::printer::hyperlink::HyperlinkPath::from_path(self.path))
            .as_ref()
    }
}

/// Decimal formatting without allocation.
pub struct DecimalFormatter {
    buf: [u8; 20],
    start: usize,
}

impl DecimalFormatter {
    pub fn new(mut n: u64) -> DecimalFormatter {
        let mut buf = [0; 20];
        let mut i = buf.len();
        loop {
            i -= 1;
            buf[i] = b'0' + (n % 10) as u8;
            n /= 10;
            if n == 0 {
                break;
            }
        }
        DecimalFormatter { buf, start: i }
    }
    pub fn as_bytes(&self) -> &[u8] {
        &self.buf[self.start..]
    }
}

/// Trim prefix ASCII whitespace (not including the line terminator).
pub fn trim_ascii_prefix(line_term: LineTerminator, slice: &[u8], range: Match) -> Match {
    fn is_space(b: u8) -> bool {
        matches!(b, b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r' | b' ')
    }
    let count = slice[range.0..range.1]
        .iter()
        .take_while(|&&b| is_space(b) && !line_term.as_bytes().contains(&b))
        .count();
    (range.0 + count, range.1)
}

/// Trim the line terminator from the end of the given range.
pub fn trim_line_terminator(searcher: &Searcher, buf: &[u8], line: &mut Match) {
    let lineterm = searcher.line_terminator();
    if lineterm.is_suffix(&buf[line.0..line.1]) {
        let mut end = line.1 - 1;
        if lineterm.is_crlf() && end > 0 && buf.get(end - 1) == Some(&b'\r') {
            end -= 1;
        }
        line.1 = end;
    }
}

/// Find all matches in the given range (with surrounding context visible
/// to the regex for look-around).
pub fn find_iter_at_in_context<F>(
    searcher: &Searcher,
    matcher: &RegexMatcher,
    mut bytes: &[u8],
    range: std::ops::Range<usize>,
    mut matched: F,
) -> io::Result<()>
where
    F: FnMut(Match) -> bool,
{
    let is_multi_line = searcher.multi_line_with_matcher(matcher);
    if is_multi_line {
        if bytes[range.end..].len() >= MAX_LOOK_AHEAD {
            bytes = &bytes[..range.end + MAX_LOOK_AHEAD];
        }
    } else {
        let mut m = (0, range.end);
        trim_line_terminator(searcher, bytes, &mut m);
        bytes = &bytes[..m.1];
    }
    matcher.find_iter_at(bytes, range.start, |m| {
        if m.0 >= range.end {
            return false;
        }
        matched(m)
    });
    Ok(())
}

/// Replacement state.
pub struct Replacer {
    space: Option<Space>,
}

struct Space {
    caps: regex_automata::util::captures::Captures,
    dst: Vec<u8>,
    matches: Vec<Match>,
}

impl Replacer {
    pub fn new() -> Replacer {
        Replacer { space: None }
    }

    pub fn replace_all<'a>(
        &'a mut self,
        searcher: &Searcher,
        matcher: &RegexMatcher,
        mut subject: &[u8],
        range: std::ops::Range<usize>,
        replacement: &[u8],
    ) -> io::Result<()> {
        let is_multi_line = searcher.multi_line_with_matcher(matcher);
        if is_multi_line {
            if subject[range.end..].len() >= MAX_LOOK_AHEAD {
                subject = &subject[..range.end + MAX_LOOK_AHEAD];
            }
        } else {
            let mut m = (0, range.end);
            trim_line_terminator(searcher, subject, &mut m);
            subject = &subject[..m.1];
        }
        {
            let space = self.allocate(matcher);
            space.dst.clear();
            space.matches.clear();
            let Space { ref mut caps, ref mut dst, ref mut matches } = *space;
            let mut last_match = range.start;
            matcher.captures_iter(subject, range.start, caps, |caps| {
                let m = caps.get_match().unwrap();
                if m.start() >= range.end {
                    return false;
                }
                dst.extend_from_slice(&subject[last_match..m.start()]);
                last_match = m.end();
                let start = dst.len();
                crate::matcher::interpolate(
                    replacement,
                    |i, dst| {
                        if let Some(sp) = caps.get_group(i) {
                            dst.extend_from_slice(&subject[sp.start..sp.end]);
                        }
                    },
                    |name| matcher.capture_index(name),
                    dst,
                );
                let end = dst.len();
                matches.push((start, end));
                true
            });
            let end = std::cmp::min(subject.len(), range.end);
            dst.extend_from_slice(&subject[last_match..end]);
        }
        Ok(())
    }

    pub fn replacement<'a>(&'a self) -> Option<(&'a [u8], &'a [Match])> {
        match self.space {
            None => None,
            Some(ref space) => Some((&space.dst, &space.matches)),
        }
    }

    pub fn clear(&mut self) {
        if let Some(ref mut space) = self.space {
            space.dst.clear();
            space.matches.clear();
        }
    }

    fn allocate(&mut self, matcher: &RegexMatcher) -> &mut Space {
        if self.space.is_none() {
            let caps = matcher.new_captures();
            self.space = Some(Space { caps, dst: vec![], matches: vec![] });
        }
        self.space.as_mut().unwrap()
    }
}
