//! The standard printer.

use std::cell::{Cell, RefCell};
use std::io::{self, Write};
use std::path::Path;
use std::sync::Arc;
use std::time::Instant;

use bstr::ByteSlice;

use crate::matcher::RegexMatcher;
use crate::printer::color::ColorSpecs;
use crate::printer::hyperlink::{HyperlinkConfig, Interpolator};
use crate::printer::stats::Stats;
use crate::printer::util::{
    find_iter_at_in_context, trim_ascii_prefix, trim_line_terminator, DecimalFormatter, Match,
    PrinterPath, Replacer, Sunk,
};
use crate::printer::{ColorWriter, CounterWriter};
use crate::searcher::lines::LineStep;
use crate::searcher::{Searcher, Sink, SinkContext, SinkContextKind, SinkFinish, SinkMatch};

#[derive(Debug, Clone)]
pub struct StandardConfig {
    pub colors: ColorSpecs,
    pub hyperlink: HyperlinkConfig,
    pub stats: bool,
    pub heading: bool,
    pub path: bool,
    pub only_matching: bool,
    pub per_match: bool,
    pub per_match_one_line: bool,
    pub replacement: Arc<Option<Vec<u8>>>,
    pub max_columns: Option<u64>,
    pub max_columns_preview: bool,
    pub max_matches: Option<u64>,
    pub column: bool,
    pub byte_offset: bool,
    pub trim_ascii: bool,
    pub separator_search: Arc<Option<Vec<u8>>>,
    pub separator_context: Arc<Option<Vec<u8>>>,
    pub separator_field_match: Arc<Vec<u8>>,
    pub separator_field_context: Arc<Vec<u8>>,
    pub separator_path: Option<u8>,
    pub path_terminator: Option<u8>,
}

impl Default for StandardConfig {
    fn default() -> StandardConfig {
        StandardConfig {
            colors: ColorSpecs::default(),
            hyperlink: HyperlinkConfig::default(),
            stats: false,
            heading: false,
            path: true,
            only_matching: false,
            per_match: false,
            per_match_one_line: false,
            replacement: Arc::new(None),
            max_columns: None,
            max_columns_preview: false,
            max_matches: None,
            column: false,
            byte_offset: false,
            trim_ascii: false,
            separator_search: Arc::new(None),
            separator_context: Arc::new(Some(b"--".to_vec())),
            separator_field_match: Arc::new(b":".to_vec()),
            separator_field_context: Arc::new(b"-".to_vec()),
            separator_path: None,
            path_terminator: None,
        }
    }
}

/// The standard printer.
pub struct Standard<W: Write> {
    config: StandardConfig,
    wtr: RefCell<CounterWriter<W>>,
    matches: Vec<Match>,
}

impl<W: Write> Standard<W> {
    pub fn new(config: StandardConfig, wtr: ColorWriter<W>) -> Standard<W> {
        Standard { config, wtr: RefCell::new(CounterWriter::new(wtr)), matches: vec![] }
    }

    pub fn config(&self) -> &StandardConfig {
        &self.config
    }

    pub fn sink<'s, 'm>(&'s mut self, matcher: &'m RegexMatcher) -> StandardSink<'static, 's, 'm, W> {
        let interpolator = Interpolator::new(&self.config.hyperlink);
        let stats = if self.config.stats { Some(Stats::new()) } else { None };
        let needs_match_granularity = self.needs_match_granularity(&stats);
        StandardSink {
            matcher,
            standard: self,
            replacer: Replacer::new(),
            interpolator,
            path: None,
            start_time: Instant::now(),
            match_count: 0,
            after_context_remaining: 0,
            binary_byte_offset: None,
            stats,
            needs_match_granularity,
        }
    }

    pub fn sink_with_path<'p, 's, 'm>(
        &'s mut self,
        matcher: &'m RegexMatcher,
        path: &'p Path,
    ) -> StandardSink<'p, 's, 'm, W> {
        if !self.config.path {
            return self.sink(matcher);
        }
        let interpolator = Interpolator::new(&self.config.hyperlink);
        let stats = if self.config.stats { Some(Stats::new()) } else { None };
        let ppath = PrinterPath::with_separator(path, self.config.separator_path);
        let needs_match_granularity = self.needs_match_granularity(&stats);
        StandardSink {
            matcher,
            standard: self,
            replacer: Replacer::new(),
            interpolator,
            path: Some(ppath),
            start_time: Instant::now(),
            match_count: 0,
            after_context_remaining: 0,
            binary_byte_offset: None,
            stats,
            needs_match_granularity,
        }
    }

    fn needs_match_granularity(&self, stats: &Option<Stats>) -> bool {
        let supports_color = self.wtr.borrow().supports_color();
        let match_colored = !self.config.colors.matched.is_none();
        (supports_color && match_colored)
            || self.config.column
            || self.config.replacement.is_some()
            || self.config.per_match
            || self.config.only_matching
            || stats.is_some()
    }

    pub fn has_written(&self) -> bool {
        self.wtr.borrow().total_count() > 0
    }

    pub fn get_mut(&mut self) -> &mut W {
        self.wtr.get_mut().get_mut()
    }

    pub fn into_inner(self) -> ColorWriter<W> {
        self.wtr.into_inner().into_inner()
    }
}

/// A sink for the standard printer.
pub struct StandardSink<'p, 's, 'm, W: Write> {
    matcher: &'m RegexMatcher,
    standard: &'s mut Standard<W>,
    replacer: Replacer,
    interpolator: Interpolator<'s>,
    path: Option<PrinterPath<'p>>,
    start_time: Instant,
    match_count: u64,
    after_context_remaining: u64,
    binary_byte_offset: Option<u64>,
    stats: Option<Stats>,
    needs_match_granularity: bool,
}

impl<'p, 's, 'm, W: Write> StandardSink<'p, 's, 'm, W> {
    pub fn has_match(&self) -> bool {
        self.match_count > 0
    }
    pub fn match_count(&self) -> u64 {
        self.match_count
    }
    pub fn binary_byte_offset(&self) -> Option<u64> {
        self.binary_byte_offset
    }
    pub fn stats(&self) -> Option<&Stats> {
        self.stats.as_ref()
    }

    fn record_matches(&mut self, searcher: &Searcher, bytes: &[u8], range: std::ops::Range<usize>) -> io::Result<()> {
        self.standard.matches.clear();
        if !self.needs_match_granularity {
            return Ok(());
        }
        let matches = &mut self.standard.matches;
        find_iter_at_in_context(searcher, self.matcher, bytes, range.clone(), |m| {
            let (s, e) = (m.0 - range.start, m.1 - range.start);
            matches.push((s, e));
            true
        })?;
        if !matches.is_empty() {
            let last = *matches.last().unwrap();
            if last.0 >= last.1 && last.0 >= range.end {
                matches.pop().unwrap();
            }
        }
        Ok(())
    }

    fn replace(&mut self, searcher: &Searcher, bytes: &[u8], range: std::ops::Range<usize>) -> io::Result<()> {
        self.replacer.clear();
        if let Some(ref replacement) = *self.standard.config.replacement {
            self.replacer.replace_all(searcher, self.matcher, bytes, range, replacement)?;
        }
        Ok(())
    }

    fn should_quit(&self) -> bool {
        let limit = match self.standard.config.max_matches {
            None => return false,
            Some(limit) => limit,
        };
        if self.match_count < limit {
            return false;
        }
        self.after_context_remaining == 0
    }

    fn match_more_than_limit(&self) -> bool {
        let limit = match self.standard.config.max_matches {
            None => return false,
            Some(limit) => limit,
        };
        self.match_count > limit
    }
}

impl<'p, 's, 'm, W: Write> Sink for StandardSink<'p, 's, 'm, W> {
    fn matched(&mut self, searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
        self.match_count += 1;
        if self.match_more_than_limit() {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        } else {
            self.after_context_remaining = searcher.after_context() as u64;
        }
        self.record_matches(searcher, mat.buffer, mat.bytes_range_in_buffer.clone())?;
        self.replace(searcher, mat.buffer, mat.bytes_range_in_buffer.clone())?;
        if let Some(ref mut stats) = self.stats {
            stats.add_matches(self.standard.matches.len() as u64);
            stats.add_matched_lines(count_lines(mat.bytes, mat.line_term.as_byte()));
        }
        if searcher.binary_detection().convert_byte().is_some() {
            if self.binary_byte_offset.is_some() {
                return Ok(false);
            }
        }
        StandardImpl::from_match(searcher, self, mat).sink()?;
        Ok(!self.should_quit())
    }

    fn context(&mut self, searcher: &Searcher, ctx: &SinkContext<'_>) -> io::Result<bool> {
        self.standard.matches.clear();
        self.replacer.clear();
        if ctx.kind == SinkContextKind::After {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        }
        if searcher.invert_match() {
            self.record_matches(searcher, ctx.bytes, 0..ctx.bytes.len())?;
            self.replace(searcher, ctx.bytes, 0..ctx.bytes.len())?;
        }
        if searcher.binary_detection().convert_byte().is_some() {
            if self.binary_byte_offset.is_some() {
                return Ok(false);
            }
        }
        StandardImpl::from_context(searcher, self, ctx).sink()?;
        Ok(!self.should_quit())
    }

    fn context_break(&mut self, searcher: &Searcher) -> io::Result<bool> {
        StandardImpl::new(searcher, self).write_context_separator()?;
        Ok(true)
    }

    fn binary_data(&mut self, searcher: &Searcher, binary_byte_offset: u64) -> io::Result<bool> {
        if searcher.binary_detection().quit_byte().is_some() {
            if let Some(ref path) = self.path {
                crate::log_debug!(
                    "grep_printer::standard",
                    "crates/printer/src/standard.rs:723",
                    "ignoring {}: found binary data at offset {}",
                    path.as_path().display(),
                    binary_byte_offset
                );
            }
        }
        self.binary_byte_offset = Some(binary_byte_offset);
        Ok(true)
    }

    fn begin(&mut self, _searcher: &Searcher) -> io::Result<bool> {
        self.standard.wtr.borrow_mut().reset_count();
        self.start_time = Instant::now();
        self.match_count = 0;
        self.after_context_remaining = 0;
        self.binary_byte_offset = None;
        if self.standard.config.max_matches == Some(0) {
            return Ok(false);
        }
        Ok(true)
    }

    fn finish(&mut self, searcher: &Searcher, finish: &SinkFinish) -> io::Result<()> {
        if let Some(offset) = finish.binary_byte_offset {
            self.binary_byte_offset = Some(offset);
        }
        if let Some(stats) = self.stats.as_mut() {
            stats.add_elapsed(self.start_time.elapsed());
            stats.add_searches(1);
            if self.match_count > 0 {
                stats.add_searches_with_match(1);
            }
            stats.add_bytes_searched(finish.byte_count);
            stats.add_bytes_printed(self.standard.wtr.borrow().count());
        }
        if let Some(offset) = self.binary_byte_offset {
            StandardImpl::new(searcher, self).write_binary_message(offset)?;
        }
        Ok(())
    }
}

fn count_lines(bytes: &[u8], line_term: u8) -> u64 {
    let mut n = memchr::memchr_iter(line_term, bytes).count() as u64;
    if !bytes.is_empty() && bytes.last() != Some(&line_term) {
        n += 1;
    }
    n
}

/// Implementation of the standard printer's output.
struct StandardImpl<'a, W: Write> {
    searcher: &'a Searcher,
    sink: &'a StandardSink<'a, 'a, 'a, W>,
    sunk: Sunk<'a>,
    in_color_match: Cell<bool>,
}

impl<'a, W: Write> StandardImpl<'a, W> {
    fn new(searcher: &'a Searcher, sink: &'a StandardSink<'_, '_, '_, W>) -> StandardImpl<'a, W> {
        // SAFETY of lifetimes: we only read from the sink.
        let sink: &'a StandardSink<'a, 'a, 'a, W> = unsafe { std::mem::transmute(sink) };
        StandardImpl { searcher, sink, sunk: Sunk::empty(), in_color_match: Cell::new(false) }
    }

    fn from_match(searcher: &'a Searcher, sink: &'a StandardSink<'_, '_, '_, W>, mat: &'a SinkMatch<'a>) -> StandardImpl<'a, W> {
        let sink: &'a StandardSink<'a, 'a, 'a, W> = unsafe { std::mem::transmute(sink) };
        let sunk = Sunk::from_sink_match(mat, &sink.standard.matches, sink.replacer.replacement());
        StandardImpl { searcher, sink, sunk, in_color_match: Cell::new(false) }
    }

    fn from_context(searcher: &'a Searcher, sink: &'a StandardSink<'_, '_, '_, W>, ctx: &'a SinkContext<'a>) -> StandardImpl<'a, W> {
        let sink: &'a StandardSink<'a, 'a, 'a, W> = unsafe { std::mem::transmute(sink) };
        let sunk = Sunk::from_sink_context(ctx, &sink.standard.matches, sink.replacer.replacement());
        StandardImpl { searcher, sink, sunk, in_color_match: Cell::new(false) }
    }

    fn sink(&self) -> io::Result<()> {
        self.write_search_prelude()?;
        if self.sunk.matches().is_empty() {
            if self.multi_line() && !self.is_context() {
                self.sink_fast_multi_line()
            } else {
                self.sink_fast()
            }
        } else {
            if self.multi_line() && !self.is_context() {
                self.sink_slow_multi_line()
            } else {
                self.sink_slow()
            }
        }
    }

    fn sink_fast(&self) -> io::Result<()> {
        self.write_prelude(self.sunk.absolute_byte_offset(), self.sunk.line_number(), None)?;
        self.write_line(self.sunk.bytes())
    }

    fn sink_fast_multi_line(&self) -> io::Result<()> {
        let line_term = self.searcher.line_terminator().as_byte();
        let mut absolute_byte_offset = self.sunk.absolute_byte_offset();
        for (i, line) in self.sunk.lines(line_term).enumerate() {
            self.write_prelude(
                absolute_byte_offset,
                self.sunk.line_number().map(|n| n + i as u64),
                None,
            )?;
            absolute_byte_offset += line.len() as u64;
            self.write_line(line)?;
        }
        Ok(())
    }

    fn sink_slow(&self) -> io::Result<()> {
        if self.config().only_matching {
            for &m in self.sunk.matches() {
                self.write_prelude(
                    self.sunk.absolute_byte_offset() + m.0 as u64,
                    self.sunk.line_number(),
                    Some(m.0 as u64 + 1),
                )?;
                let buf = &self.sunk.bytes()[m.0..m.1];
                self.write_colored_line(&[(0, buf.len())], buf)?;
            }
        } else if self.config().per_match {
            for &m in self.sunk.matches() {
                self.write_prelude(
                    self.sunk.absolute_byte_offset() + m.0 as u64,
                    self.sunk.line_number(),
                    Some(m.0 as u64 + 1),
                )?;
                self.write_colored_line(&[m], self.sunk.bytes())?;
            }
        } else {
            self.write_prelude(
                self.sunk.absolute_byte_offset(),
                self.sunk.line_number(),
                Some(self.sunk.matches()[0].0 as u64 + 1),
            )?;
            self.write_colored_line(self.sunk.matches(), self.sunk.bytes())?;
        }
        Ok(())
    }

    fn sink_slow_multi_line(&self) -> io::Result<()> {
        if self.config().only_matching {
            return self.sink_slow_multi_line_only_matching();
        } else if self.config().per_match {
            return self.sink_slow_multi_per_match();
        }
        let line_term = self.searcher.line_terminator().as_byte();
        let bytes = self.sunk.bytes();
        let matches = self.sunk.matches();
        let mut midx = 0;
        let mut count = 0;
        let mut stepper = LineStep::new(line_term, 0, bytes.len());
        while let Some((start, end)) = stepper.next(bytes) {
            let mut line = (start, end);
            self.write_prelude(
                self.sunk.absolute_byte_offset() + line.0 as u64,
                self.sunk.line_number().map(|n| n + count),
                Some(matches[0].0 as u64 + 1),
            )?;
            count += 1;
            self.trim_line_terminator(bytes, &mut line);
            self.trim_ascii_prefix(bytes, &mut line);
            if self.exceeds_max_columns(&bytes[line.0..line.1]) {
                self.write_exceeded_line(bytes, line, matches, &mut midx)?;
            } else {
                self.write_colored_matches(bytes, line, matches, &mut midx)?;
                self.write_line_term()?;
            }
        }
        Ok(())
    }

    fn sink_slow_multi_line_only_matching(&self) -> io::Result<()> {
        let line_term = self.searcher.line_terminator().as_byte();
        let spec = &self.config().colors.matched;
        let bytes = self.sunk.bytes();
        let matches = self.sunk.matches();
        let mut midx = 0;
        let mut count = 0;
        let mut stepper = LineStep::new(line_term, 0, bytes.len());
        while let Some((start, end)) = stepper.next(bytes) {
            let mut line = (start, end);
            self.trim_line_terminator(bytes, &mut line);
            self.trim_ascii_prefix(bytes, &mut line);
            while line.0 < line.1 {
                if matches[midx].1 <= line.0 {
                    if midx + 1 < matches.len() {
                        midx += 1;
                        continue;
                    } else {
                        break;
                    }
                }
                let m = matches[midx];
                if line.0 < m.0 {
                    let upto = std::cmp::min(line.1, m.0);
                    line.0 = upto;
                } else {
                    let upto = std::cmp::min(line.1, m.1);
                    self.write_prelude(
                        self.sunk.absolute_byte_offset() + m.0 as u64,
                        self.sunk.line_number().map(|n| n + count),
                        Some(m.0 as u64 + 1),
                    )?;
                    let this_line = (line.0, upto);
                    line.0 = upto;
                    if self.exceeds_max_columns(&bytes[this_line.0..this_line.1]) {
                        self.write_exceeded_line(bytes, this_line, matches, &mut midx)?;
                    } else {
                        self.write_spec(spec, &bytes[this_line.0..this_line.1])?;
                        self.write_line_term()?;
                    }
                }
            }
            count += 1;
        }
        Ok(())
    }

    fn sink_slow_multi_per_match(&self) -> io::Result<()> {
        let line_term = self.searcher.line_terminator().as_byte();
        let spec = &self.config().colors.matched;
        let bytes = self.sunk.bytes();
        for &m in self.sunk.matches() {
            let mut count = 0;
            let mut stepper = LineStep::new(line_term, 0, bytes.len());
            while let Some((start, end)) = stepper.next(bytes) {
                let mut line = (start, end);
                if line.0 >= m.1 {
                    break;
                } else if line.1 <= m.0 {
                    count += 1;
                    continue;
                }
                self.write_prelude(
                    self.sunk.absolute_byte_offset() + line.0 as u64,
                    self.sunk.line_number().map(|n| n + count),
                    Some(m.0.saturating_sub(line.0) as u64 + 1),
                )?;
                count += 1;
                self.trim_line_terminator(bytes, &mut line);
                self.trim_ascii_prefix(bytes, &mut line);
                if self.exceeds_max_columns(&bytes[line.0..line.1]) {
                    self.write_exceeded_line(bytes, line, &[m], &mut 0)?;
                    continue;
                }
                while line.0 < line.1 {
                    if m.1 <= line.0 {
                        self.write(&bytes[line.0..line.1])?;
                        line.0 = line.1;
                    } else if line.0 < m.0 {
                        let upto = std::cmp::min(line.1, m.0);
                        self.write(&bytes[line.0..upto])?;
                        line.0 = upto;
                    } else {
                        let upto = std::cmp::min(line.1, m.1);
                        self.write_spec(spec, &bytes[line.0..upto])?;
                        line.0 = upto;
                    }
                }
                self.write_line_term()?;
                if self.config().per_match_one_line {
                    break;
                }
            }
        }
        Ok(())
    }

    fn write_prelude(&self, absolute_byte_offset: u64, line_number: Option<u64>, column: Option<u64>) -> io::Result<()> {
        let mut prelude = PreludeWriter::new(self);
        prelude.start(line_number, column)?;
        prelude.write_path()?;
        prelude.write_line_number(line_number)?;
        prelude.write_column_number(column)?;
        prelude.write_byte_offset(absolute_byte_offset)?;
        prelude.end()
    }

    fn write_line(&self, line: &[u8]) -> io::Result<()> {
        let line = if !self.config().trim_ascii {
            line
        } else {
            let lineterm = self.searcher.line_terminator();
            let full_range = (0, line.len());
            let range = trim_ascii_prefix(lineterm, line, full_range);
            &line[range.0..range.1]
        };
        if self.exceeds_max_columns(line) {
            let range = (0, line.len());
            self.write_exceeded_line(line, range, self.sunk.matches(), &mut 0)?;
        } else {
            self.write(line)?;
            if !self.has_line_terminator(line) {
                self.write_line_term()?;
            }
        }
        Ok(())
    }

    fn write_colored_line(&self, matches: &[Match], bytes: &[u8]) -> io::Result<()> {
        let spec = &self.config().colors.matched;
        if !self.wtr().borrow().supports_color() || spec.is_none() {
            return self.write_line(bytes);
        }
        let mut line = (0, bytes.len());
        self.trim_ascii_prefix(bytes, &mut line);
        if self.exceeds_max_columns(bytes) {
            self.write_exceeded_line(bytes, line, matches, &mut 0)
        } else {
            self.trim_line_terminator(bytes, &mut line);
            self.write_colored_matches(bytes, line, matches, &mut 0)?;
            self.write_line_term()
        }
    }

    fn write_colored_matches(&self, bytes: &[u8], mut line: Match, matches: &[Match], match_index: &mut usize) -> io::Result<()> {
        self.trim_line_terminator(bytes, &mut line);
        if matches.is_empty() {
            self.write(&bytes[line.0..line.1])?;
            return Ok(());
        }
        while line.0 < line.1 {
            if matches[*match_index].1 <= line.0 {
                if *match_index + 1 < matches.len() {
                    *match_index += 1;
                    continue;
                } else {
                    self.end_color_match()?;
                    self.write(&bytes[line.0..line.1])?;
                    break;
                }
            }
            let m = matches[*match_index];
            if line.0 < m.0 {
                let upto = std::cmp::min(line.1, m.0);
                self.end_color_match()?;
                self.write(&bytes[line.0..upto])?;
                line.0 = upto;
            } else {
                let upto = std::cmp::min(line.1, m.1);
                self.start_color_match()?;
                self.write(&bytes[line.0..upto])?;
                line.0 = upto;
            }
        }
        self.end_color_match()?;
        Ok(())
    }

    fn write_exceeded_line(&self, bytes: &[u8], mut line: Match, matches: &[Match], match_index: &mut usize) -> io::Result<()> {
        if self.config().max_columns_preview {
            let original = line;
            let end = bytes[line.0..line.1]
                .grapheme_indices()
                .map(|(_, end, _)| end)
                .take(self.config().max_columns.unwrap_or(0) as usize)
                .last()
                .unwrap_or(0)
                + line.0;
            line.1 = end;
            self.write_colored_matches(bytes, line, matches, match_index)?;
            if matches.is_empty() {
                self.write(b" [... omitted end of long line]")?;
            } else {
                let remaining = matches
                    .iter()
                    .filter(|m| m.0 >= line.1 && m.0 < original.1)
                    .count();
                let tense = if remaining == 1 { "match" } else { "matches" };
                write!(self.wtr().borrow_mut(), " [... {} more {}]", remaining, tense)?;
            }
            self.write_line_term()?;
            return Ok(());
        }
        if self.sunk.original_matches().is_empty() {
            if self.is_context() {
                self.write(b"[Omitted long context line]")?;
            } else {
                self.write(b"[Omitted long matching line]")?;
            }
        } else {
            if self.config().only_matching {
                if self.is_context() {
                    self.write(b"[Omitted long context line]")?;
                } else {
                    self.write(b"[Omitted long matching line]")?;
                }
            } else {
                write!(
                    self.wtr().borrow_mut(),
                    "[Omitted long line with {} matches]",
                    self.sunk.original_matches().len(),
                )?;
            }
        }
        self.write_line_term()?;
        Ok(())
    }

    fn write_path_line(&self) -> io::Result<()> {
        if let Some(path) = self.path() {
            self.write_path_hyperlink(path)?;
            if let Some(term) = self.config().path_terminator {
                self.write(&[term])?;
            } else {
                self.write_line_term()?;
            }
        }
        Ok(())
    }

    fn write_search_prelude(&self) -> io::Result<()> {
        let this_search_printed = self.wtr().borrow().count() > 0;
        if this_search_printed {
            return Ok(());
        }
        let ever_printed = self.wtr().borrow().total_count() > 0;
        if ever_printed {
            if let Some(ref sep) = *self.config().separator_search {
                self.write(sep)?;
                self.write_line_term()?;
            }
        }
        if self.config().heading {
            self.write_path_line()?;
        }
        Ok(())
    }

    fn write_binary_message(&self, offset: u64) -> io::Result<()> {
        if self.sink.match_count == 0 {
            return Ok(());
        }
        let bin = self.searcher.binary_detection();
        if let Some(byte) = bin.quit_byte() {
            if let Some(path) = self.path() {
                self.write_path_hyperlink(path)?;
                self.write(b": ")?;
            }
            let remainder = format!(
                "WARNING: stopped searching binary file after match \
                 (found {:?} byte around offset {})\n",
                [byte].as_bstr(),
                offset,
            );
            self.write(remainder.as_bytes())?;
        } else if let Some(byte) = bin.convert_byte() {
            if let Some(path) = self.path() {
                self.write_path_hyperlink(path)?;
                self.write(b": ")?;
            }
            let remainder = format!(
                "binary file matches (found {:?} byte around offset {})\n",
                [byte].as_bstr(),
                offset,
            );
            self.write(remainder.as_bytes())?;
        }
        Ok(())
    }

    fn write_context_separator(&self) -> io::Result<()> {
        if let Some(ref sep) = *self.config().separator_context {
            self.write(sep)?;
            self.write_line_term()?;
        }
        Ok(())
    }

    fn write_line_term(&self) -> io::Result<()> {
        self.write(self.searcher.line_terminator().as_bytes())
    }

    fn write_spec(&self, spec: &crate::printer::color::ColorSpec, buf: &[u8]) -> io::Result<()> {
        let mut wtr = self.wtr().borrow_mut();
        wtr.set_color(spec)?;
        wtr.write_all(buf)?;
        wtr.reset()?;
        Ok(())
    }

    fn write_path(&self, path: &PrinterPath) -> io::Result<()> {
        let mut wtr = self.wtr().borrow_mut();
        wtr.set_color(&self.config().colors.path)?;
        wtr.write_all(path.as_bytes())?;
        wtr.reset()?;
        Ok(())
    }

    fn write_path_hyperlink(&self, path: &PrinterPath) -> io::Result<()> {
        let status = self.start_hyperlink(path, None, None)?;
        self.write_path(path)?;
        self.end_hyperlink(status)
    }

    fn start_hyperlink(&self, path: &PrinterPath, line_number: Option<u64>, column: Option<u64>) -> io::Result<bool> {
        if self.config().hyperlink.is_empty() {
            return Ok(false);
        }
        let mut wtr = self.wtr().borrow_mut();
        if !wtr.supports_hyperlinks() {
            return Ok(false);
        }
        let hpath = match path.hyperlink_path() {
            None => return Ok(false),
            Some(p) => p,
        };
        let mut uri = vec![];
        self.sink.interpolator.interpolate(hpath, line_number, column, &mut uri);
        wtr.set_hyperlink(Some(&uri))?;
        Ok(true)
    }

    fn end_hyperlink(&self, active: bool) -> io::Result<()> {
        if !active {
            return Ok(());
        }
        self.wtr().borrow_mut().set_hyperlink(None)
    }

    fn start_color_match(&self) -> io::Result<()> {
        if self.in_color_match.get() {
            return Ok(());
        }
        self.wtr().borrow_mut().set_color(&self.config().colors.matched)?;
        self.in_color_match.set(true);
        Ok(())
    }

    fn end_color_match(&self) -> io::Result<()> {
        if !self.in_color_match.get() {
            return Ok(());
        }
        self.wtr().borrow_mut().reset()?;
        self.in_color_match.set(false);
        Ok(())
    }

    fn write(&self, buf: &[u8]) -> io::Result<()> {
        self.wtr().borrow_mut().write_all(buf)
    }

    fn trim_line_terminator(&self, buf: &[u8], line: &mut Match) {
        trim_line_terminator(self.searcher, buf, line);
    }

    fn has_line_terminator(&self, buf: &[u8]) -> bool {
        self.searcher.line_terminator().is_suffix(buf)
    }

    fn is_context(&self) -> bool {
        self.sunk.context_kind().is_some()
    }

    fn config(&self) -> &'a StandardConfig {
        &self.sink.standard.config
    }

    fn wtr(&self) -> &'a RefCell<CounterWriter<W>> {
        &self.sink.standard.wtr
    }

    fn path(&self) -> Option<&'a PrinterPath<'a>> {
        if !self.config().path {
            None
        } else {
            self.sink.path.as_ref()
        }
    }

    fn separator_field(&self) -> &[u8] {
        if self.is_context() {
            &self.config().separator_field_context
        } else {
            &self.config().separator_field_match
        }
    }

    fn multi_line(&self) -> bool {
        self.searcher.multi_line_with_matcher(self.sink.matcher)
    }

    fn exceeds_max_columns(&self, line: &[u8]) -> bool {
        self.config().max_columns.map_or(false, |m| line.len() as u64 > m)
    }

    fn trim_ascii_prefix(&self, slice: &[u8], range: &mut Match) {
        if !self.config().trim_ascii {
            return;
        }
        let lineterm = self.searcher.line_terminator();
        *range = trim_ascii_prefix(lineterm, slice, *range)
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum PreludeSeparator {
    None,
    FieldSeparator,
    PathTerminator,
}

struct PreludeWriter<'a, W: Write> {
    std: &'a StandardImpl<'a, W>,
    next_separator: PreludeSeparator,
    field_separator: &'a [u8],
    hyperlink_active: bool,
}

impl<'a, W: Write> PreludeWriter<'a, W> {
    fn new(std: &'a StandardImpl<'a, W>) -> PreludeWriter<'a, W> {
        PreludeWriter {
            std,
            next_separator: PreludeSeparator::None,
            field_separator: std.separator_field(),
            hyperlink_active: false,
        }
    }

    fn start(&mut self, line_number: Option<u64>, column: Option<u64>) -> io::Result<()> {
        let path = match self.std.path() {
            None => return Ok(()),
            Some(p) => p,
        };
        if self.config().hyperlink.is_empty() {
            return Ok(());
        }
        self.hyperlink_active = self.std.start_hyperlink(path, line_number, column)?;
        Ok(())
    }

    fn end(&mut self) -> io::Result<()> {
        self.std.end_hyperlink(self.hyperlink_active)?;
        self.write_separator()
    }

    fn write_path(&mut self) -> io::Result<()> {
        if self.config().heading {
            return Ok(());
        }
        let path = match self.std.path() {
            None => return Ok(()),
            Some(p) => p,
        };
        self.write_separator()?;
        self.std.write_path(path)?;
        self.next_separator = if self.config().path_terminator.is_some() {
            PreludeSeparator::PathTerminator
        } else {
            PreludeSeparator::FieldSeparator
        };
        Ok(())
    }

    fn write_line_number(&mut self, line: Option<u64>) -> io::Result<()> {
        let line_number = match line {
            None => return Ok(()),
            Some(n) => n,
        };
        self.write_separator()?;
        let n = DecimalFormatter::new(line_number);
        self.std.write_spec(&self.config().colors.line, n.as_bytes())?;
        self.next_separator = PreludeSeparator::FieldSeparator;
        Ok(())
    }

    fn write_column_number(&mut self, column: Option<u64>) -> io::Result<()> {
        if !self.config().column {
            return Ok(());
        }
        let column_number = match column {
            None => return Ok(()),
            Some(n) => n,
        };
        self.write_separator()?;
        let n = DecimalFormatter::new(column_number);
        self.std.write_spec(&self.config().colors.column, n.as_bytes())?;
        self.next_separator = PreludeSeparator::FieldSeparator;
        Ok(())
    }

    fn write_byte_offset(&mut self, offset: u64) -> io::Result<()> {
        if !self.config().byte_offset {
            return Ok(());
        }
        self.write_separator()?;
        let n = DecimalFormatter::new(offset);
        self.std.write_spec(&self.config().colors.column, n.as_bytes())?;
        self.next_separator = PreludeSeparator::FieldSeparator;
        Ok(())
    }

    fn write_separator(&mut self) -> io::Result<()> {
        match self.next_separator {
            PreludeSeparator::None => {}
            PreludeSeparator::FieldSeparator => {
                self.std.write(self.field_separator)?;
            }
            PreludeSeparator::PathTerminator => {
                self.std.write(&[self.config().path_terminator.unwrap()])?;
            }
        }
        self.next_separator = PreludeSeparator::None;
        Ok(())
    }

    fn config(&self) -> &StandardConfig {
        self.std.config()
    }
}
