//! The JSON Lines printer.

use std::io::{self, Write};
use std::path::Path;
use std::time::Instant;

use crate::matcher::RegexMatcher;
use crate::printer::stats::Stats;
use crate::printer::util::{find_iter_at_in_context, Match};
use crate::printer::{ColorWriter, CounterWriter};
use crate::searcher::{Searcher, Sink, SinkContext, SinkContextKind, SinkFinish, SinkMatch};

#[derive(Debug, Clone)]
pub struct JSONConfig {
    pub pretty: bool,
    pub max_matches: Option<u64>,
    pub always_begin_end: bool,
}

impl Default for JSONConfig {
    fn default() -> JSONConfig {
        JSONConfig { pretty: false, max_matches: None, always_begin_end: false }
    }
}

pub struct JSON<W: Write> {
    config: JSONConfig,
    wtr: CounterWriter<W>,
    matches: Vec<Match>,
}

impl<W: Write> JSON<W> {
    pub fn new(config: JSONConfig, wtr: ColorWriter<W>) -> JSON<W> {
        JSON { config, wtr: CounterWriter::new(wtr), matches: vec![] }
    }

    pub fn sink<'s, 'm>(&'s mut self, matcher: &'m RegexMatcher) -> JSONSink<'static, 's, 'm, W> {
        JSONSink {
            matcher,
            json: self,
            path: None,
            start_time: Instant::now(),
            match_count: 0,
            after_context_remaining: 0,
            binary_byte_offset: None,
            begin_printed: false,
            stats: Stats::new(),
        }
    }

    pub fn sink_with_path<'p, 's, 'm>(&'s mut self, matcher: &'m RegexMatcher, path: &'p Path) -> JSONSink<'p, 's, 'm, W> {
        JSONSink {
            matcher,
            json: self,
            path: Some(path),
            start_time: Instant::now(),
            match_count: 0,
            after_context_remaining: 0,
            binary_byte_offset: None,
            begin_printed: false,
            stats: Stats::new(),
        }
    }

    pub fn get_mut(&mut self) -> &mut W {
        self.wtr.get_mut()
    }

    pub fn into_inner(self) -> ColorWriter<W> {
        self.wtr.into_inner()
    }

    fn write_message(&mut self, msg: &[u8]) -> io::Result<()> {
        self.wtr.write_all(msg)?;
        self.wtr.write_all(b"\n")
    }
}

pub struct JSONSink<'p, 's, 'm, W: Write> {
    matcher: &'m RegexMatcher,
    json: &'s mut JSON<W>,
    path: Option<&'p Path>,
    start_time: Instant,
    match_count: u64,
    after_context_remaining: u64,
    binary_byte_offset: Option<u64>,
    begin_printed: bool,
    stats: Stats,
}

impl<'p, 's, 'm, W: Write> JSONSink<'p, 's, 'm, W> {
    pub fn has_match(&self) -> bool {
        self.match_count > 0
    }
    pub fn binary_byte_offset(&self) -> Option<u64> {
        self.binary_byte_offset
    }
    pub fn stats(&self) -> &Stats {
        &self.stats
    }

    fn record_matches(&mut self, searcher: &Searcher, bytes: &[u8], range: std::ops::Range<usize>) -> io::Result<()> {
        self.json.matches.clear();
        let matches = &mut self.json.matches;
        find_iter_at_in_context(searcher, self.matcher, bytes, range.clone(), |m| {
            let (s, e) = (m.0 - range.start, m.1 - range.start);
            matches.push((s, e));
            true
        })?;
        if !matches.is_empty() {
            let last = *matches.last().unwrap();
            if last.0 >= last.1 && last.0 >= range.end {
                matches.pop().unwrap();
            }
        }
        Ok(())
    }

    fn should_quit(&self) -> bool {
        let limit = match self.json.config.max_matches {
            None => return false,
            Some(limit) => limit,
        };
        if self.match_count < limit {
            return false;
        }
        self.after_context_remaining == 0
    }

    fn match_more_than_limit(&self) -> bool {
        let limit = match self.json.config.max_matches {
            None => return false,
            Some(limit) => limit,
        };
        self.match_count > limit
    }

    fn write_begin_message(&mut self) -> io::Result<()> {
        if self.begin_printed {
            return Ok(());
        }
        let mut msg = Vec::new();
        msg.extend_from_slice(b"{\"type\":\"begin\",\"data\":{\"path\":");
        write_path(&mut msg, self.path);
        msg.extend_from_slice(b"}}");
        self.json.write_message(&msg)?;
        self.begin_printed = true;
        Ok(())
    }

    fn write_match_or_context(&mut self, kind: &str, lines: &[u8], line_number: Option<u64>, absolute_offset: u64, submatches: &[Match]) -> io::Result<()> {
        let mut msg = Vec::new();
        msg.extend_from_slice(b"{\"type\":\"");
        msg.extend_from_slice(kind.as_bytes());
        msg.extend_from_slice(b"\",\"data\":{\"path\":");
        write_path(&mut msg, self.path);
        msg.extend_from_slice(b",\"lines\":");
        write_data(&mut msg, lines);
        msg.extend_from_slice(b",\"line_number\":");
        match line_number {
            None => msg.extend_from_slice(b"null"),
            Some(n) => msg.extend_from_slice(n.to_string().as_bytes()),
        }
        msg.extend_from_slice(b",\"absolute_offset\":");
        msg.extend_from_slice(absolute_offset.to_string().as_bytes());
        msg.extend_from_slice(b",\"submatches\":[");
        for (i, m) in submatches.iter().enumerate() {
            if i > 0 {
                msg.push(b',');
            }
            msg.extend_from_slice(b"{\"match\":");
            write_data(&mut msg, &lines[m.0..m.1]);
            msg.extend_from_slice(b",\"start\":");
            msg.extend_from_slice(m.0.to_string().as_bytes());
            msg.extend_from_slice(b",\"end\":");
            msg.extend_from_slice(m.1.to_string().as_bytes());
            msg.push(b'}');
        }
        msg.extend_from_slice(b"]}}");
        self.json.write_message(&msg)
    }
}

impl<'p, 's, 'm, W: Write> Sink for JSONSink<'p, 's, 'm, W> {
    fn matched(&mut self, searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
        self.write_begin_message()?;
        self.match_count += 1;
        if self.match_more_than_limit() {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        } else {
            self.after_context_remaining = searcher.after_context() as u64;
        }
        self.record_matches(searcher, mat.buffer, mat.bytes_range_in_buffer.clone())?;
        self.stats.add_matches(self.json.matches.len() as u64);
        self.stats.add_matched_lines(count_lines(mat.bytes, mat.line_term.as_byte()));
        let submatches = std::mem::take(&mut self.json.matches);
        self.write_match_or_context("match", mat.bytes, mat.line_number, mat.absolute_byte_offset, &submatches)?;
        self.json.matches = submatches;
        Ok(!self.should_quit())
    }

    fn context(&mut self, searcher: &Searcher, ctx: &SinkContext<'_>) -> io::Result<bool> {
        self.write_begin_message()?;
        self.json.matches.clear();
        if ctx.kind == SinkContextKind::After {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        }
        let submatches = if searcher.invert_match() {
            self.record_matches(searcher, ctx.bytes, 0..ctx.bytes.len())?;
            std::mem::take(&mut self.json.matches)
        } else {
            vec![]
        };
        self.write_match_or_context("context", ctx.bytes, ctx.line_number, ctx.absolute_byte_offset, &submatches)?;
        Ok(!self.should_quit())
    }

    fn begin(&mut self, _searcher: &Searcher) -> io::Result<bool> {
        self.json.wtr.reset_count();
        self.start_time = Instant::now();
        self.match_count = 0;
        self.after_context_remaining = 0;
        self.binary_byte_offset = None;
        if self.json.config.max_matches == Some(0) {
            return Ok(false);
        }
        if !self.json.config.always_begin_end {
            return Ok(true);
        }
        self.write_begin_message()?;
        Ok(true)
    }

    fn finish(&mut self, _searcher: &Searcher, finish: &SinkFinish) -> io::Result<()> {
        if !self.begin_printed {
            return Ok(());
        }
        self.binary_byte_offset = finish.binary_byte_offset;
        self.stats.add_elapsed(self.start_time.elapsed());
        self.stats.add_searches(1);
        if self.match_count > 0 {
            self.stats.add_searches_with_match(1);
        }
        self.stats.add_bytes_searched(finish.byte_count);
        self.stats.add_bytes_printed(self.json.wtr.count());
        let mut msg = Vec::new();
        msg.extend_from_slice(b"{\"type\":\"end\",\"data\":{\"path\":");
        write_path(&mut msg, self.path);
        msg.extend_from_slice(b",\"binary_offset\":");
        match finish.binary_byte_offset {
            None => msg.extend_from_slice(b"null"),
            Some(n) => msg.extend_from_slice(n.to_string().as_bytes()),
        }
        msg.extend_from_slice(b",\"stats\":");
        write_stats(&mut msg, &self.stats);
        msg.extend_from_slice(b"}}");
        self.json.write_message(&msg)?;
        Ok(())
    }
}

fn count_lines(bytes: &[u8], line_term: u8) -> u64 {
    let mut n = memchr::memchr_iter(line_term, bytes).count() as u64;
    if !bytes.is_empty() && bytes.last() != Some(&line_term) {
        n += 1;
    }
    n
}

/// Write `{"text":...}` or `{"bytes":...}`.
pub fn write_data(dst: &mut Vec<u8>, data: &[u8]) {
    match std::str::from_utf8(data) {
        Ok(s) => {
            dst.extend_from_slice(b"{\"text\":");
            write_json_string(dst, s);
            dst.push(b'}');
        }
        Err(_) => {
            dst.extend_from_slice(b"{\"bytes\":\"");
            dst.extend_from_slice(base64(data).as_bytes());
            dst.extend_from_slice(b"\"}");
        }
    }
}

fn write_path(dst: &mut Vec<u8>, path: Option<&Path>) {
    use std::os::unix::ffi::OsStrExt;
    match path {
        None => dst.extend_from_slice(b"null"),
        Some(p) => write_data(dst, p.as_os_str().as_bytes()),
    }
}

/// Write a JSON string literal with serde_json compatible escaping.
pub fn write_json_string(dst: &mut Vec<u8>, s: &str) {
    dst.push(b'"');
    for &b in s.as_bytes() {
        match b {
            b'"' => dst.extend_from_slice(b"\\\""),
            b'\\' => dst.extend_from_slice(b"\\\\"),
            b'\n' => dst.extend_from_slice(b"\\n"),
            b'\r' => dst.extend_from_slice(b"\\r"),
            b'\t' => dst.extend_from_slice(b"\\t"),
            0x08 => dst.extend_from_slice(b"\\b"),
            0x0c => dst.extend_from_slice(b"\\f"),
            0x00..=0x1f => {
                dst.extend_from_slice(format!("\\u{:04x}", b).as_bytes());
            }
            _ => dst.push(b),
        }
    }
    dst.push(b'"');
}

pub fn write_duration(dst: &mut Vec<u8>, d: std::time::Duration, sorted: bool) {
    let human = format!("{:0.6}s", d.as_secs_f64());
    if sorted {
        dst.extend_from_slice(b"{\"human\":");
        write_json_string(dst, &human);
        dst.extend_from_slice(format!(",\"nanos\":{},\"secs\":{}}}", d.subsec_nanos(), d.as_secs()).as_bytes());
    } else {
        dst.extend_from_slice(
            format!("{{\"secs\":{},\"nanos\":{},\"human\":", d.as_secs(), d.subsec_nanos()).as_bytes(),
        );
        write_json_string(dst, &human);
        dst.push(b'}');
    }
}

pub fn write_stats(dst: &mut Vec<u8>, stats: &Stats) {
    dst.extend_from_slice(b"{\"elapsed\":");
    write_duration(dst, stats.elapsed, false);
    dst.extend_from_slice(
        format!(
            ",\"searches\":{},\"searches_with_match\":{},\"bytes_searched\":{},\"bytes_printed\":{},\"matched_lines\":{},\"matches\":{}}}",
            stats.searches,
            stats.searches_with_match,
            stats.bytes_searched,
            stats.bytes_printed,
            stats.matched_lines,
            stats.matches
        )
        .as_bytes(),
    );
}

/// Write the final summary message (keys sorted, as serde_json::json! does).
pub fn write_summary(dst: &mut Vec<u8>, stats: &Stats, elapsed_total: std::time::Duration) {
    dst.extend_from_slice(b"{\"data\":{\"elapsed_total\":");
    write_duration(dst, elapsed_total, true);
    dst.extend_from_slice(b",\"stats\":{\"bytes_printed\":");
    dst.extend_from_slice(stats.bytes_printed.to_string().as_bytes());
    dst.extend_from_slice(b",\"bytes_searched\":");
    dst.extend_from_slice(stats.bytes_searched.to_string().as_bytes());
    dst.extend_from_slice(b",\"elapsed\":");
    write_duration(dst, stats.elapsed, true);
    dst.extend_from_slice(b",\"matched_lines\":");
    dst.extend_from_slice(stats.matched_lines.to_string().as_bytes());
    dst.extend_from_slice(b",\"matches\":");
    dst.extend_from_slice(stats.matches.to_string().as_bytes());
    dst.extend_from_slice(b",\"searches\":");
    dst.extend_from_slice(stats.searches.to_string().as_bytes());
    dst.extend_from_slice(b",\"searches_with_match\":");
    dst.extend_from_slice(stats.searches_with_match.to_string().as_bytes());
    dst.extend_from_slice(b"}},\"type\":\"summary\"}");
}

fn base64(data: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = chunk.get(1).map(|&b| b as u32);
        let b2 = chunk.get(2).map(|&b| b as u32);
        let n = (b0 << 16) | (b1.unwrap_or(0) << 8) | b2.unwrap_or(0);
        out.push(TABLE[((n >> 18) & 63) as usize] as char);
        out.push(TABLE[((n >> 12) & 63) as usize] as char);
        if b1.is_some() {
            out.push(TABLE[((n >> 6) & 63) as usize] as char);
        } else {
            out.push('=');
        }
        if b2.is_some() {
            out.push(TABLE[(n & 63) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}
