//! The summary printer (count, files with/without matches, quiet).

use std::cell::RefCell;
use std::io::{self, Write};
use std::path::Path;
use std::sync::Arc;
use std::time::Instant;

use crate::matcher::RegexMatcher;
use crate::printer::color::ColorSpecs;
use crate::printer::hyperlink::{HyperlinkConfig, Interpolator};
use crate::printer::stats::Stats;
use crate::printer::util::{find_iter_at_in_context, PrinterPath};
use crate::printer::{ColorWriter, CounterWriter};
use crate::searcher::{Searcher, Sink, SinkFinish, SinkMatch};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SummaryKind {
    Count,
    CountMatches,
    PathWithMatch,
    PathWithoutMatch,
    Quiet,
}

impl SummaryKind {
    fn requires_path(&self) -> bool {
        matches!(*self, SummaryKind::PathWithMatch | SummaryKind::PathWithoutMatch)
    }
    fn requires_stats(&self) -> bool {
        matches!(*self, SummaryKind::CountMatches)
    }
    fn quit_early(&self) -> bool {
        matches!(*self, SummaryKind::PathWithMatch | SummaryKind::Quiet)
    }
}

#[derive(Debug, Clone)]
pub struct SummaryConfig {
    pub kind: SummaryKind,
    pub colors: ColorSpecs,
    pub hyperlink: HyperlinkConfig,
    pub stats: bool,
    pub path: bool,
    pub max_matches: Option<u64>,
    pub exclude_zero: bool,
    pub separator_field: Arc<Vec<u8>>,
    pub separator_path: Option<u8>,
    pub path_terminator: Option<u8>,
}

impl Default for SummaryConfig {
    fn default() -> SummaryConfig {
        SummaryConfig {
            kind: SummaryKind::Count,
            colors: ColorSpecs::default(),
            hyperlink: HyperlinkConfig::default(),
            stats: false,
            path: true,
            max_matches: None,
            exclude_zero: true,
            separator_field: Arc::new(b":".to_vec()),
            separator_path: None,
            path_terminator: None,
        }
    }
}

pub struct Summary<W: Write> {
    config: SummaryConfig,
    wtr: RefCell<CounterWriter<W>>,
}

impl<W: Write> Summary<W> {
    pub fn new(config: SummaryConfig, wtr: ColorWriter<W>) -> Summary<W> {
        Summary { config, wtr: RefCell::new(CounterWriter::new(wtr)) }
    }

    pub fn config(&self) -> &SummaryConfig {
        &self.config
    }

    pub fn sink<'s, 'm>(&'s mut self, matcher: &'m RegexMatcher) -> SummarySink<'static, 's, 'm, W> {
        let stats = if self.config.stats || self.config.kind.requires_stats() {
            Some(Stats::new())
        } else {
            None
        };
        let interpolator = Interpolator::new(&self.config.hyperlink);
        SummarySink {
            matcher,
            summary: self,
            interpolator,
            path: None,
            start_time: Instant::now(),
            match_count: 0,
            binary_byte_offset: None,
            stats,
        }
    }

    pub fn sink_with_path<'p, 's, 'm>(&'s mut self, matcher: &'m RegexMatcher, path: &'p Path) -> SummarySink<'p, 's, 'm, W> {
        if !self.config.path && !self.config.kind.requires_path() {
            return self.sink(matcher);
        }
        let stats = if self.config.stats || self.config.kind.requires_stats() {
            Some(Stats::new())
        } else {
            None
        };
        let interpolator = Interpolator::new(&self.config.hyperlink);
        let ppath = PrinterPath::with_separator(path, self.config.separator_path);
        SummarySink {
            matcher,
            summary: self,
            interpolator,
            path: Some(ppath),
            start_time: Instant::now(),
            match_count: 0,
            binary_byte_offset: None,
            stats,
        }
    }

    pub fn get_mut(&mut self) -> &mut W {
        self.wtr.get_mut().get_mut()
    }

    pub fn into_inner(self) -> ColorWriter<W> {
        self.wtr.into_inner().into_inner()
    }
}

pub struct SummarySink<'p, 's, 'm, W: Write> {
    matcher: &'m RegexMatcher,
    summary: &'s mut Summary<W>,
    interpolator: Interpolator<'s>,
    path: Option<PrinterPath<'p>>,
    start_time: Instant,
    match_count: u64,
    binary_byte_offset: Option<u64>,
    stats: Option<Stats>,
}

impl<'p, 's, 'm, W: Write> SummarySink<'p, 's, 'm, W> {
    pub fn has_match(&self) -> bool {
        if self.summary.config.kind == SummaryKind::PathWithoutMatch {
            self.match_count == 0
        } else {
            self.match_count > 0
        }
    }

    pub fn binary_byte_offset(&self) -> Option<u64> {
        self.binary_byte_offset
    }

    pub fn stats(&self) -> Option<&Stats> {
        self.stats.as_ref()
    }

    fn is_multi_line(&self, searcher: &Searcher) -> bool {
        searcher.multi_line_with_matcher(self.matcher)
    }

    fn should_quit(&self) -> bool {
        if self.summary.config.kind.quit_early() {
            return true;
        }
        let limit = match self.summary.config.max_matches {
            None => return false,
            Some(limit) => limit,
        };
        self.match_count >= limit
    }

    fn write_path_line(&self, searcher: &Searcher) -> io::Result<()> {
        if let Some(ref path) = self.path {
            self.write_path_hyperlink(path)?;
            if let Some(term) = self.summary.config.path_terminator {
                self.write(&[term])?;
            } else {
                self.write_line_term(searcher)?;
            }
        }
        Ok(())
    }

    fn write_path_field(&self) -> io::Result<()> {
        if let Some(ref path) = self.path {
            self.write_path_hyperlink(path)?;
            if let Some(term) = self.summary.config.path_terminator {
                self.write(&[term])?;
            } else {
                self.write(&self.summary.config.separator_field)?;
            }
        }
        Ok(())
    }

    fn write_path_hyperlink(&self, path: &PrinterPath) -> io::Result<()> {
        let mut wtr = self.summary.wtr.borrow_mut();
        let mut active = false;
        if !self.summary.config.hyperlink.is_empty() && wtr.supports_hyperlinks() {
            if let Some(hpath) = path.hyperlink_path() {
                let mut uri = vec![];
                self.interpolator.interpolate(hpath, None, None, &mut uri);
                wtr.set_hyperlink(Some(&uri))?;
                active = true;
            }
        }
        wtr.set_color(&self.summary.config.colors.path)?;
        wtr.write_all(path.as_bytes())?;
        wtr.reset()?;
        if active {
            wtr.set_hyperlink(None)?;
        }
        Ok(())
    }

    fn write_line_term(&self, searcher: &Searcher) -> io::Result<()> {
        self.write(searcher.line_terminator().as_bytes())
    }

    fn write(&self, buf: &[u8]) -> io::Result<()> {
        self.summary.wtr.borrow_mut().write_all(buf)
    }
}

impl<'p, 's, 'm, W: Write> Sink for SummarySink<'p, 's, 'm, W> {
    fn matched(&mut self, searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
        let is_multi_line = self.is_multi_line(searcher);
        let sink_match_count = if self.stats.is_none() && !is_multi_line {
            1
        } else {
            let buf = mat.buffer;
            let range = mat.bytes_range_in_buffer.clone();
            let mut count = 0;
            find_iter_at_in_context(searcher, self.matcher, buf, range, |_| {
                count += 1;
                true
            })?;
            count
        };
        if is_multi_line {
            self.match_count += sink_match_count;
        } else {
            self.match_count += 1;
        }
        if let Some(ref mut stats) = self.stats {
            stats.add_matches(sink_match_count);
            stats.add_matched_lines(count_lines(mat.bytes, mat.line_term.as_byte()));
        } else if self.summary.config.kind.quit_early() {
            return Ok(false);
        }
        Ok(!self.should_quit())
    }

    fn binary_data(&mut self, searcher: &Searcher, binary_byte_offset: u64) -> io::Result<bool> {
        if searcher.binary_detection().quit_byte().is_some() {
            if let Some(ref path) = self.path {
                crate::log_debug!(
                    "grep_printer::summary",
                    "crates/printer/src/summary.rs:566",
                    "ignoring {}: found binary data at offset {}",
                    path.as_path().display(),
                    binary_byte_offset
                );
            }
        }
        Ok(true)
    }

    fn begin(&mut self, _searcher: &Searcher) -> io::Result<bool> {
        if self.path.is_none() && self.summary.config.kind.requires_path() {
            return Err(io::Error::new(
                io::ErrorKind::Other,
                format!("output kind {:?} requires a file path", self.summary.config.kind),
            ));
        }
        self.summary.wtr.borrow_mut().reset_count();
        self.start_time = Instant::now();
        self.match_count = 0;
        self.binary_byte_offset = None;
        if self.summary.config.max_matches == Some(0) {
            return Ok(false);
        }
        Ok(true)
    }

    fn finish(&mut self, searcher: &Searcher, finish: &SinkFinish) -> io::Result<()> {
        self.binary_byte_offset = finish.binary_byte_offset;
        if let Some(ref mut stats) = self.stats {
            stats.add_elapsed(self.start_time.elapsed());
            stats.add_searches(1);
            if self.match_count > 0 {
                stats.add_searches_with_match(1);
            }
            stats.add_bytes_searched(finish.byte_count);
            stats.add_bytes_printed(self.summary.wtr.borrow().count());
        }
        if self.binary_byte_offset.is_some() && searcher.binary_detection().quit_byte().is_some() {
            self.match_count = 0;
            return Ok(());
        }
        let show_count = !self.summary.config.exclude_zero || self.match_count > 0;
        match self.summary.config.kind {
            SummaryKind::Count => {
                if show_count {
                    self.write_path_field()?;
                    self.write(self.match_count.to_string().as_bytes())?;
                    self.write_line_term(searcher)?;
                }
            }
            SummaryKind::CountMatches => {
                if show_count {
                    self.write_path_field()?;
                    let stats = self.stats.as_ref().expect("CountMatches should enable stats tracking");
                    self.write(stats.matches.to_string().as_bytes())?;
                    self.write_line_term(searcher)?;
                }
            }
            SummaryKind::PathWithMatch => {
                if self.match_count > 0 {
                    self.write_path_line(searcher)?;
                }
            }
            SummaryKind::PathWithoutMatch => {
                if self.match_count == 0 {
                    self.write_path_line(searcher)?;
                }
            }
            SummaryKind::Quiet => {}
        }
        Ok(())
    }
}

fn count_lines(bytes: &[u8], line_term: u8) -> u64 {
    let mut n = memchr::memchr_iter(line_term, bytes).count() as u64;
    if !bytes.is_empty() && bytes.last() != Some(&line_term) {
        n += 1;
    }
    n
}
