actions.command:
cd /workspace && cat > src/flags/defs.rs <<'EOF'
//! Flag definitions.

use std::ffi::OsString;
use std::path::PathBuf;

use bstr::BString;

use crate::error::{Error, Result};
use crate::flags::lowargs::*;
use crate::util;

pub enum FlagValue {
    Switch(bool),
    Value(OsString),
}

impl FlagValue {
    pub fn unwrap_switch(self) -> bool {
        match self {
            FlagValue::Switch(yes) => yes,
            FlagValue::Value(_) => unreachable!("got switch but expected value"),
        }
    }
    pub fn unwrap_value(self) -> OsString {
        match self {
            FlagValue::Switch(_) => unreachable!("got value but expected switch"),
            FlagValue::Value(v) => v,
        }
    }
}

pub struct Flag {
    pub long: &'static str,
    pub short: Option<u8>,
    pub negated: Option<&'static str>,
    pub aliases: &'static [&'static str],
    pub switch: bool,
    pub update: fn(FlagValue, &mut LowArgs) -> Result<()>,
}

fn s(v: FlagValue) -> bool {
    v.unwrap_switch()
}
fn val(v: FlagValue) -> OsString {
    v.unwrap_value()
}
fn string(v: FlagValue) -> Result<String> {
    util::os_to_string(val(v))
}

fn choice_err(choice: &str) -> Error {
    Error::new(format!("choice '{}' is unrecognized", choice))
}

macro_rules! flag {
    ($long:expr, $short:expr, $negated:expr, $aliases:expr, $switch:expr, $update:expr) => {
        Flag { long: $long, short: $short, negated: $negated, aliases: $aliases, switch: $switch, update: $update }
    };
}

pub static FLAGS: &[Flag] = &[
    flag!("after-context", Some(b'A'), None, &[], false, |v, a| {
        a.context.set_after(util::parse_usize(&val(v))?);
        Ok(())
    }),
    flag!("before-context", Some(b'B'), None, &[], false, |v, a| {
        a.context.set_before(util::parse_usize(&val(v))?);
        Ok(())
    }),
    flag!("binary", None, Some("no-binary"), &[], true, |v, a| {
        a.binary = if s(v) { BinaryMode::SearchAndSuppress } else { BinaryMode::Auto };
        Ok(())
    }),
    flag!("block-buffered", None, Some("no-block-buffered"), &[], true, |v, a| {
        a.buffer = if s(v) { BufferMode::Block } else { BufferMode::Auto };
        Ok(())
    }),
    flag!("byte-offset", Some(b'b'), Some("no-byte-offset"), &[], true, |v, a| {
        a.byte_offset = s(v);
        Ok(())
    }),
    flag!("case-sensitive", Some(b's'), None, &[], true, |v, a| {
        assert!(s(v));
        a.case = CaseMode::Sensitive;
        Ok(())
    }),
    flag!("color", None, None, &[], false, |v, a| {
        let v = string(v)?;
        a.color = match v.as_str() {
            "never" => ColorChoice::Never,
            "auto" => ColorChoice::Auto,
            "always" => ColorChoice::Always,
            "ansi" => ColorChoice::Ansi,
            other => return Err(choice_err(other)),
        };
        Ok(())
    }),
    flag!("colors", None, None, &[], false, |v, a| {
        let v = string(v)?;
        let spec = v.parse::<crate::printer::color::UserColorSpec>()?;
        a.colors.push_user(spec);
        Ok(())
    }),
    flag!("column", None, Some("no-column"), &[], true, |v, a| {
        a.column = Some(s(v));
        Ok(())
    }),
    flag!("context", Some(b'C'), None, &[], false, |v, a| {
        a.context.set_both(util::parse_usize(&val(v))?);
        Ok(())
    }),
    flag!("context-separator", None, Some("no-context-separator"), &[], false, |v, a| {
        match v {
            FlagValue::Switch(yes) => {
                assert!(!yes, "flag can only be disabled");
                a.context_separator = ContextSeparator::disabled();
            }
            FlagValue::Value(v) => {
                a.context_separator = ContextSeparator::new(&v);
            }
        }
        Ok(())
    }),
    flag!("count", Some(b'c'), None, &[], true, |v, a| {
        assert!(s(v));
        a.mode.update(Mode::Search(SearchMode::Count));
        Ok(())
    }),
    flag!("count-matches", None, None, &[], true, |v, a| {
        assert!(s(v));
        a.mode.update(Mode::Search(SearchMode::CountMatches));
