//! Command line parsing.

use std::ffi::OsString;

use crate::error::{Error, Result};
use crate::flags::defs::{Flag, FlagValue, FLAGS};
use crate::flags::lowargs::{LowArgs, SpecialMode};

enum Lookup<'a> {
    Match { flag: &'a Flag, negated: bool, name: String },
    UnrecognizedShort(char),
    UnrecognizedLong(String),
}

fn find_short(ch: char) -> Lookup<'static> {
    if !ch.is_ascii() {
        return Lookup::UnrecognizedShort(ch);
    }
    let b = ch as u8;
    for flag in FLAGS {
        if flag.short == Some(b) {
            return Lookup::Match { flag, negated: false, name: format!("-{}", ch) };
        }
    }
    Lookup::UnrecognizedShort(ch)
}

fn find_long(name: &str) -> Lookup<'static> {
    for flag in FLAGS {
        if flag.long == name {
            return Lookup::Match { flag, negated: false, name: format!("--{}", name) };
        }
        if flag.negated == Some(name) {
            return Lookup::Match { flag, negated: true, name: format!("--{}", name) };
        }
        if flag.aliases.contains(&name) {
            return Lookup::Match { flag, negated: false, name: format!("--{}", name) };
        }
    }
    Lookup::UnrecognizedLong(name.to_string())
}

fn trigrams(s: &str) -> std::collections::HashSet<&[u8]> {
    let b = s.as_bytes();
    let mut set = std::collections::HashSet::new();
    if b.len() >= 3 {
        for i in 0..=b.len() - 3 {
            set.insert(&b[i..i + 3]);
        }
    }
    set
}

fn jaccard(a: &str, b: &str) -> f64 {
    let ta = trigrams(a);
    let tb = trigrams(b);
    let inter = ta.intersection(&tb).count();
    let union = ta.union(&tb).count();
    if union == 0 {
        0.0
    } else {
        inter as f64 / union as f64
    }
}

/// Returns a suggestion message for an unrecognized long flag name.
fn suggest(unrecognized: &str) -> Option<String> {
    let mut similar = vec![];
    for flag in FLAGS {
        let mut names = vec![flag.long];
        if let Some(neg) = flag.negated {
            names.push(neg);
        }
        for alias in flag.aliases {
            names.push(alias);
        }
        for name in names {
            if jaccard(unrecognized, name) >= 0.4 {
                similar.push(format!("--{}", name));
            }
        }
    }
    if similar.is_empty() {
        None
    } else {
        Some(format!("similar flags that are available: {}", similar.join(", ")))
    }
}

enum RawArg {
    Positional(OsString),
    Short(char),
    Long(String),
}

struct Lexer {
    args: std::vec::IntoIter<OsString>,
    /// Remaining bytes of a short cluster.
    cluster: Option<Vec<u8>>,
    /// Pending `=value` for a long option.
    pending_long_value: Option<(String, OsString)>,
    only_positional: bool,
    last_option: Option<String>,
}

impl Lexer {
    fn new(args: Vec<OsString>) -> Lexer {
        Lexer { args: args.into_iter(), cluster: None, pending_long_value: None, only_positional: false, last_option: None }
    }

    fn next(&mut self) -> Result<Option<RawArg>> {
        use std::os::unix::ffi::{OsStrExt, OsStringExt};
        if let Some((name, value)) = self.pending_long_value.take() {
            return Err(Error::new(format!(
                "invalid CLI arguments: unexpected argument for option '--{}': {:?}",
                name, value
            )));
        }
        if let Some(cluster) = self.cluster.take() {
            if !cluster.is_empty() {
                if cluster[0] == b'=' {
                    let value = OsString::from_vec(cluster[1..].to_vec());
                    return Err(Error::new(format!(
                        "invalid CLI arguments: unexpected argument for option '{}': {:?}",
                        self.last_option.clone().unwrap_or_default(),
                        value
                    )));
                }
                // Decode the next char.
                let s = String::from_utf8_lossy(&cluster);
                let ch = s.chars().next().unwrap();
                let len = ch.len_utf8();
                let rest = cluster[std::cmp::min(len, cluster.len())..].to_vec();
                self.cluster = Some(rest);
                self.last_option = Some(format!("-{}", ch));
                return Ok(Some(RawArg::Short(ch)));
            }
        }
        let arg = match self.args.next() {
            None => return Ok(None),
            Some(arg) => arg,
        };
        if self.only_positional {
            return Ok(Some(RawArg::Positional(arg)));
        }
        let bytes = arg.as_bytes();
        if bytes == b"--" {
            self.only_positional = true;
            return self.next();
        }
        if bytes.starts_with(b"--") {
            let rest = &bytes[2..];
            let (name, value) = match memchr::memchr(b'=', rest) {
                Some(i) => (&rest[..i], Some(OsString::from_vec(rest[i + 1..].to_vec()))),
                None => (rest, None),
            };
            let name = match std::str::from_utf8(name) {
                Ok(n) => n.to_string(),
                Err(_) => {
                    return Err(Error::new(format!(
                        "invalid CLI arguments: argument is invalid unicode: {:?}",
                        arg
                    )))
                }
            };
            if let Some(v) = value {
                self.pending_long_value = Some((name.clone(), v));
            }
            self.last_option = Some(format!("--{}", name));
            return Ok(Some(RawArg::Long(name)));
        }
        if bytes.len() > 1 && bytes[0] == b'-' {
            self.cluster = Some(bytes[1..].to_vec());
            return self.next();
        }
        Ok(Some(RawArg::Positional(arg)))
    }

    /// Take the value for the option most recently returned.
    fn value(&mut self) -> Result<OsString> {
        use std::os::unix::ffi::OsStringExt;
        if let Some((_, value)) = self.pending_long_value.take() {
            return Ok(value);
        }
        if let Some(cluster) = self.cluster.take() {
            if !cluster.is_empty() {
                let v = if cluster[0] == b'=' { cluster[1..].to_vec() } else { cluster };
                return Ok(OsString::from_vec(v));
            }
        }
        match self.args.next() {
            Some(v) => Ok(v),
            None => Err(Error::new(format!(
                "missing argument for option '{}'",
                self.last_option.clone().unwrap_or_default()
            ))),
        }
    }
}

/// Parse the given raw arguments into `args`.
pub fn parse_args(rawargs: Vec<OsString>, args: &mut LowArgs) -> Result<()> {
    let mut lexer = Lexer::new(rawargs);
    loop {
        let arg = match lexer.next()? {
            None => break,
            Some(arg) => arg,
        };
        let lookup = match arg {
            RawArg::Positional(value) => {
                args.positional.push(value);
                continue;
            }
            RawArg::Short('h') => {
                args.special = Some(SpecialMode::HelpShort);
                continue;
            }
            RawArg::Short('V') => {
                args.special = Some(SpecialMode::VersionShort);
                continue;
            }
            RawArg::Long(ref name) if name == "help" => {
                args.special = Some(SpecialMode::HelpLong);
                continue;
            }
            RawArg::Long(ref name) if name == "version" => {
                args.special = Some(SpecialMode::VersionLong);
                continue;
            }
            RawArg::Short(ch) => find_short(ch),
            RawArg::Long(name) => find_long(&name),
        };
        let (flag, negated, name) = match lookup {
            Lookup::Match { flag, negated, name } => (flag, negated, name),
            Lookup::UnrecognizedShort(ch) => {
                return Err(Error::new(format!("unrecognized flag -{}", ch)));
            }
            Lookup::UnrecognizedLong(name) => {
                let mut msg = format!("unrecognized flag --{}", name);
                if let Some(suggest_msg) = suggest(&name) {
                    msg = format!("{}\n\n{}", msg, suggest_msg);
                }
                return Err(Error::new(msg));
            }
        };
        let value = if flag.switch || negated {
            if negated {
                FlagValue::Switch(false)
            } else {
                FlagValue::Switch(true)
            }
        } else {
            let value = lexer
                .value()
                .map_err(|e| e.context(format!("missing value for flag {}", name)))?;
            FlagValue::Value(value)
        };
        (flag.update)(value, args).map_err(|e| e.context(format!("error parsing flag {}", name)))?;
    }
    Ok(())
}

/// The result of parsing CLI arguments.
pub enum ParseResult<T> {
    Special(SpecialMode),
    Ok(T),
    Err(Error),
}

/// Parse CLI arguments (and config file) into low-level args.
pub fn parse_low() -> ParseResult<LowArgs> {
    let mut low = LowArgs::default();
    let cli_args: Vec<OsString> = std::env::args_os().skip(1).collect();
    if let Err(err) = parse_args(cli_args.clone(), &mut low) {
        return ParseResult::Err(err);
    }
    set_log_levels(&low);
    // Config file.
    if !low.no_config {
        let config_args = crate::flags::config::args();
        if !config_args.is_empty() {
            let mut low_config = LowArgs::default();
            let mut all = config_args;
            all.extend(cli_args);
            if let Err(err) = parse_args(all, &mut low_config) {
                return ParseResult::Err(err);
            }
            low = low_config;
            set_log_levels(&low);
        }
    } else {
        crate::log_debug!(
            "rg::flags::parse",
            "crates/core/flags/parse.rs:88",
            "not reading config files because --no-config is present"
        );
    }
    if let Some(special) = low.special {
        return ParseResult::Special(special);
    }
    ParseResult::Ok(low)
}

fn set_log_levels(low: &LowArgs) {
    use crate::flags::lowargs::LoggingMode;
    match low.logging {
        Some(LoggingMode::Trace) => crate::messages::set_log_level(2),
        Some(LoggingMode::Debug) => crate::messages::set_log_level(1),
        None => crate::messages::set_log_level(0),
    }
}
