            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1094",
                "is_one_file? {:?}",
                is_one_file
            );
            return Ok(Paths { paths, has_implicit_path: false, is_one_file });
        }
        let is_readable_stdin = crate::util::is_readable_stdin();
        let use_cwd = !is_readable_stdin || state.stdin_consumed || !matches!(low.mode, Mode::Search(_));
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1108",
            "using heuristics to determine whether to read from stdin or search ./ \
             (is_readable_stdin={}, stdin_consumed={}, mode={})",
            is_readable_stdin,
            state.stdin_consumed,
            mode_debug(low.mode)
        );
        let (path, is_one_file) = if use_cwd {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1118",
                "heuristic chose to search ./"
            );
            (PathBuf::from("./"), false)
        } else {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1121",
                "heuristic chose to search stdin"
            );
            (PathBuf::from("-"), true)
        };
        Ok(Paths { paths: vec![path], has_implicit_path: true, is_one_file })
    }
}

fn mode_debug(mode: Mode) -> String {
    match mode {
        Mode::Search(SearchMode::Standard) => "Search(Standard)".to_string(),
        Mode::Search(SearchMode::FilesWithMatches) => "Search(FilesWithMatches)".to_string(),
        Mode::Search(SearchMode::FilesWithoutMatch) => "Search(FilesWithoutMatch)".to_string(),
        Mode::Search(SearchMode::Count) => "Search(Count)".to_string(),
        Mode::Search(SearchMode::CountMatches) => "Search(CountMatches)".to_string(),
        Mode::Search(SearchMode::JSON) => "Search(JSON)".to_string(),
        Mode::Files => "Files".to_string(),
        Mode::Types => "Types".to_string(),
        Mode::Generate(_) => "Generate(..)".to_string(),
    }
}

fn types(low: &LowArgs) -> Result<Types> {
    let mut builder = TypesBuilder::new();
    builder.add_defaults();
    for tychange in low.type_changes.iter() {
        match tychange {
            TypeChange::Clear { ref name } => {
                builder.clear(name);
            }
            TypeChange::Add { ref def } => {
                builder.add_def(def).map_err(|e| Error::new(e.to_string()))?;
            }
            TypeChange::Select { ref name } => {
                builder.select(name);
            }
            TypeChange::Negate { ref name } => {
                builder.negate(name);
            }
        }
    }
    builder.build().map_err(|e| Error::new(e.to_string()))
}

fn globs(state: &State, low: &LowArgs) -> Result<Override> {
    if low.globs.is_empty() && low.iglobs.is_empty() {
        return Ok(Override::empty());
    }
    let mut builder = OverrideBuilder::new(&state.cwd);
    if low.glob_case_insensitive {
        builder.case_insensitive(true);
    }
    for glob in low.globs.iter() {
        builder.add(glob).map_err(|e| Error::new(e.to_string()))?;
    }
    builder.case_insensitive(true);
    for glob in low.iglobs.iter() {
        builder.add(glob).map_err(|e| Error::new(e.to_string()))?;
    }
    builder.build().map_err(|e| Error::new(e.to_string()))
}

fn preprocessor_globs(state: &State, low: &LowArgs) -> Result<Override> {
    if low.pre_glob.is_empty() {
        return Ok(Override::empty());
    }
    let mut builder = OverrideBuilder::new(&state.cwd);
    for glob in low.pre_glob.iter() {
        builder.add(glob).map_err(|e| Error::new(e.to_string()))?;
    }
    builder.build().map_err(|e| Error::new(e.to_string()))
}

fn take_hyperlink_config(low: &mut LowArgs) -> Result<HyperlinkConfig> {
    let mut env = HyperlinkEnvironment::default();
    let hostname = hostname(low.hostname_bin.as_deref());
    if let Some(hostname) = hostname {
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1269",
            "found hostname for hyperlink configuration: {}",
            hostname
        );
        env.host = Some(hostname.into_bytes());
    }
    if let Some(wsl_prefix) = wsl_prefix() {
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1273",
            "found wsl_prefix for hyperlink configuration: {}",
            wsl_prefix
        );
        env.wsl_prefix = Some(wsl_prefix.into_bytes());
    }
    let fmt = std::mem::take(&mut low.hyperlink_format);
    crate::log_debug!(
        "rg::flags::hiargs",
        "crates/core/flags/hiargs.rs:1279",
        "hyperlink format: {:?}",
        fmt.to_format_string()
    );
    Ok(HyperlinkConfig { env, format: fmt })
}

fn hostname(bin: Option<&Path>) -> Option<String> {
    let bin = match bin {
        None => return platform_hostname(),
        Some(bin) => bin,
    };
    let mut cmd = std::process::Command::new(bin);
    cmd.stdin(std::process::Stdio::null());
    cmd.stderr(std::process::Stdio::null());
    let out = match cmd.output() {
        Ok(out) => out,
        Err(err) => {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1333",
                "failed to spawn command '{:?}' to get hostname \
                 (falling back to platform hostname): {}",
                bin,
                err
            );
            return platform_hostname();
        }
    };
    if !out.status.success() {
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1342",
            "command '{:?}' failed to get hostname \
             (falling back to platform hostname): {:?}",
            bin,
            out.status
        );
        return platform_hostname();
    }
    let hostname = match std::str::from_utf8(&out.stdout) {
        Ok(h) => h.trim(),
        Err(_) => {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1351",
                "output from command '{:?}' is not valid UTF-8 \
                 (falling back to platform hostname)",
                bin
            );
            return platform_hostname();
        }
    };
    if hostname.is_empty() {
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1360",
            "output from command '{:?}' is empty (falling back to platform hostname)",
            bin
        );
        return platform_hostname();
    }
    Some(hostname.to_string())
}

fn platform_hostname() -> Option<String> {
    let hostname_os = match crate::util::hostname() {
        Ok(x) => x,
        Err(err) => {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1380",
                "could not get hostname: {}",
                err
            );
            return None;
        }
    };
    match hostname_os.to_str() {
        Some(h) => Some(h.to_string()),
        None => {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1385",
                "got hostname {:?}, but it's not valid UTF-8",
                hostname_os
            );
            None
        }
    }
}

fn wsl_prefix() -> Option<String> {
    let distro_os = std::env::var_os("WSL_DISTRO_NAME")?;
    let distro = distro_os.to_str()?;
    Some(format!("wsl$/{}", distro))
}

/// Stdout writer selection.
pub fn stdout_writer(args: &HiArgs) -> Box<dyn Write + Send> {
    let line_buffered = if args.is_terminal_stdout {
        args.buffer != BufferMode::Block
    } else {
        args.buffer == BufferMode::Line
    };
    if line_buffered {
        Box::new(io::LineWriter::new(io::stdout()))
    } else {
        Box::new(io::BufWriter::with_capacity(64 * 1024, io::stdout()))
    }
}

pub fn hyperlink_format_default() -> HyperlinkFormat {
    HyperlinkFormat::empty()
}

pub type SharedStats = Arc<std::sync::Mutex<Stats>>;
