#[derive(Debug, Clone)]
pub struct BinaryDetection {
    pub explicit: SBD,
    pub implicit: SBD,
}

impl BinaryDetection {
    fn from_low_args(low: &LowArgs) -> BinaryDetection {
        let none = matches!(low.binary, BinaryMode::AsText) || low.null_data;
        let convert = matches!(low.binary, BinaryMode::SearchAndSuppress) || low.unrestricted >= 3;
        let explicit = if none { SBD::None } else { SBD::Convert(b'\x00') };
        let implicit = if none {
            SBD::None
        } else if convert {
            SBD::Convert(b'\x00')
        } else {
            SBD::Quit(b'\x00')
        };
        BinaryDetection { explicit, implicit }
    }
    fn is_none(&self) -> bool {
        self.explicit == SBD::None && self.implicit == SBD::None
    }
}

