impl HiArgs {
    pub fn from_low_args(mut low: LowArgs) -> Result<HiArgs> {
        let mut state = State {
            is_terminal_stdout: crate::util::stdout_is_tty(),
            stdin_consumed: false,
            cwd: std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
        };
        let patterns = Patterns::from_low_args(&mut state, &mut low)?;
        let paths = Paths::from_low_args(&mut state, &patterns, &mut low)?;
        let binary = BinaryDetection::from_low_args(&low);
        let colors = low.colors.resolve();
        let hyperlink_config = take_hyperlink_config(&mut low)?;
        let stats = if low.stats || matches!(low.mode, Mode::Search(SearchMode::JSON)) {
            Some(Stats::new())
        } else {
            None
        };
        let types = types(&low)?;
        let globs = globs(&state, &low)?;
        let pre_globs = preprocessor_globs(&state, &low)?;

        let color = match low.color {
