            "crates/core/flags/hiargs.rs:174",
            "using {} thread(s)",
            threads
        );
        let with_filename = low.with_filename.unwrap_or_else(|| low.vimgrep || !paths.is_one_file);
        let file_separator = match low.mode {
            Mode::Search(SearchMode::Standard) => {
                if heading {
                    Some(b"".to_vec())
                } else if let ContextMode::Limited(ref limited) = low.context {
                    let (before, after) = limited.get();
                    if before > 0 || after > 0 {
                        low.context_separator.clone().into_bytes()
                    } else {
                        None
                    }
                } else {
                    None
                }
            }
            _ => None,
        };
        let line_number = low.line_number.unwrap_or_else(|| {
            if low.vimgrep {
                return true;
            }
            if column {
                return true;
            }
            match low.mode {
                Mode::Search(SearchMode::JSON) => true,
                Mode::Search(SearchMode::Standard) => state.is_terminal_stdout,
                _ => false,
            }
        });
        let mode = match low.mode {
            Mode::Search(SearchMode::Count) if low.only_matching => {
                Mode::Search(SearchMode::CountMatches)
            }
            m => m,
        };
        let mmap = match low.mmap {
            MmapMode::Auto => {
                paths.paths.len() <= 10 && paths.paths.iter().all(|p| p.is_file())
            }
            MmapMode::AlwaysTryMmap => true,
            MmapMode::Never => false,
        };
        let no_ignore = low.unrestricted >= 1;
        let hidden = low.hidden || low.unrestricted >= 2;
        Ok(HiArgs {
            binary,
            boundary: low.boundary,
            buffer: low.buffer,
            byte_offset: low.byte_offset,
            case: low.case,
            color,
            colors,
