            threads,
            trim: low.trim,
            types,
            vimgrep: low.vimgrep,
            with_filename,
        })
    }

    pub fn mode(&self) -> Mode {
        self.mode
    }
    pub fn has_implicit_path(&self) -> bool {
        self.paths.has_implicit_path
    }
    pub fn quit_after_match(&self) -> bool {
        self.quit_after_match
    }
    pub fn stats(&self) -> Option<Stats> {
        self.stats.clone()
    }
    pub fn threads(&self) -> usize {
        self.threads
    }

    pub fn color_enabled(&self) -> bool {
        match self.color {
            ColorChoice::Never => false,
            ColorChoice::Always | ColorChoice::Ansi => true,
            ColorChoice::Auto => {
                if !self.is_terminal_stdout {
                    return false;
                }
                if std::env::var_os("NO_COLOR").is_some() {
                    return false;
                }
                match std::env::var("TERM") {
                    Ok(t) => t != "dumb",
                    Err(_) => false,
                }
            }
        }
    }

    /// Build the matcher.
    pub fn matcher(&self) -> Result<RegexMatcher> {
        match self.engine {
            EngineChoice::PCRE2 => {
                return Err(Error::new("PCRE2 is not available in this build of ripgrep"));
            }
            EngineChoice::Default | EngineChoice::Auto => {}
        }
        let mut config = MatcherConfig::default();
        config.multi_line = true;
        config.unicode = !self.no_unicode;
        config.fixed_strings = self.fixed_strings;
        config.whole_line = self.boundary == Some(BoundaryMode::Line);
        config.word = self.boundary == Some(BoundaryMode::Word);
        match self.case {
            CaseMode::Sensitive => {
                config.case_insensitive = false;
                config.case_smart = false;
            }
            CaseMode::Insensitive => {
                config.case_insensitive = true;
                config.case_smart = false;
            }
            CaseMode::Smart => {
                config.case_insensitive = false;
                config.case_smart = true;
            }
        }
        if self.multiline {
            config.dot_matches_new_line = self.multiline_dotall;
            if self.crlf {
                config.crlf = true;
                config.line_terminator = None;
            } else {
                config.line_terminator = None;
            }
        } else {
            config.line_terminator = Some(LineTerminator::byte(b'\n'));
            config.dot_matches_new_line = false;
            if self.crlf {
                config.crlf = true;
                config.line_terminator = Some(LineTerminator::crlf());
            }
            if self.null_data {
                config.line_terminator = Some(LineTerminator::byte(b'\x00'));
            }
        }
        if let Some(limit) = self.regex_size_limit {
            config.size_limit = limit;
        }
        if let Some(limit) = self.dfa_size_limit {
            config.dfa_size_limit = limit;
        }
        if !self.binary.is_none() {
            config.ban = Some(b'\x00');
        }
        match RegexMatcher::new_many(config, &self.patterns.patterns) {
            Ok(m) => Ok(m),
            Err(err) => Err(suggest(err.to_string())),
        }
    }

    pub fn searcher(&self) -> Searcher {
        let line_term = if self.crlf {
            LineTerminator::crlf()
        } else if self.null_data {
            LineTerminator::byte(b'\x00')
        } else {
            LineTerminator::byte(b'\n')
        };
        let (before, after) = self.context.get_limited();
        let mut config = SearcherConfig::default();
        config.line_term = line_term;
        config.invert_match = self.invert_match;
        config.line_number = self.line_number;
        config.multi_line = self.multiline;
        config.before_context = before;
        config.after_context = after;
        config.passthru = matches!(self.context, ContextMode::Passthru);
        config.stop_on_nonmatch = self.stop_on_nonmatch;
        match self.encoding {
            EncodingMode::Auto => {}
            EncodingMode::Some(enc) => {
                config.encoding = Some(enc);
            }
            EncodingMode::Disabled => {
                config.bom_sniffing = false;
            }
        }
        Searcher::new(config)
    }

    pub fn walk_builder(&self) -> Result<WalkBuilder> {
        let mut builder = WalkBuilder::new(&self.paths.paths[0]);
        for path in self.paths.paths.iter().skip(1) {
            builder.add(path);
        }
        if !self.no_ignore_files {
            for path in self.ignore_file.iter() {
                if let Some(err) = builder.add_ignore(path) {
                    crate::ignore_message!("{}", err);
                }
            }
        }
        builder
            .max_depth(self.max_depth)
            .follow_links(self.follow)
            .max_filesize(self.max_filesize)
            .threads(self.threads)
            .same_file_system(self.one_file_system)
            .skip_stdout(!matches!(self.mode, Mode::Files))
            .hidden(!self.hidden)
            .parents(!self.no_ignore_parent)
            .ignore(!self.no_ignore_dot)
            .git_ignore(!self.no_ignore_vcs)
            .git_global(!self.no_ignore_vcs && !self.no_ignore_global)
            .git_exclude(!self.no_ignore_vcs && !self.no_ignore_exclude)
            .require_git(!self.no_require_git)
            .ignore_case_insensitive(self.ignore_file_case_insensitive);
        builder.overrides(self.clone_globs()?);
        builder.types(types_rebuild(self)?);
        if !self.no_ignore_dot {
            builder.add_custom_ignore_filename(".rgignore");
        }
        match self.sort {
            None => {}
            Some(ref sort) => match sort.kind {
                SortModeKind::Path if sort.reverse => {
                    builder.sort_by_file_name(|a, b| a.cmp(b).reverse());
                }
                SortModeKind::Path => {
                    builder.sort_by_file_name(|a, b| a.cmp(b));
                }
                _ => {}
            },
        }
        Ok(builder)
    }

    fn clone_globs(&self) -> Result<Override> {
        // Overrides aren't Clone; rebuild from the stored low-level globs.
        Ok(self.globs_rebuild()?)
    }

    fn globs_rebuild(&self) -> Result<Override> {
        let (globs, iglobs, ci) = match &self.glob_sources {
            Some(x) => x,
            None => return Ok(Override::empty()),
        };
        if globs.is_empty() && iglobs.is_empty() {
            return Ok(Override::empty());
        }
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let mut builder = OverrideBuilder::new(&cwd);
        if *ci {
            builder.case_insensitive(true);
        }
        for glob in globs.iter() {
            builder.add(glob).map_err(|e| Error::new(e.to_string()))?;
        }
        builder.case_insensitive(true);
        for glob in iglobs.iter() {
            builder.add(glob).map_err(|e| Error::new(e.to_string()))?;
        }
        builder.build().map_err(|e| Error::new(e.to_string()))
    }
}

