fn suggest(msg: String) -> Error {
    if msg.contains("the literal") && msg.contains("not allowed") {
        return Error::new(format!(
            "{msg}

Consider enabling multiline mode with the --multiline flag (or -U for short).
When multiline mode is enabled, new line characters can be matched."
        ));
    }
    if msg.contains("pattern contains \"\\0\"") || msg.contains("pattern contains \"\\x00\"") {
        return Error::new(format!(
            "{msg}

Consider enabling text mode with the --text flag (or -a for short). Otherwise,
binary detection is enabled and matching a NUL byte is impossible."
        ));
    }
    Error::new(msg)
}

impl Patterns {
    fn from_low_args(state: &mut State, low: &mut LowArgs) -> Result<Patterns> {
        if !matches!(low.mode, Mode::Search(_)) {
            return Ok(Patterns { patterns: vec![] });
        }
        if low.patterns.is_empty() {
            if low.positional.is_empty() {
                return Err(Error::new("ripgrep requires at least one pattern to execute a search"));
            }
            let ospat = low.positional.remove(0);
            let pat = match ospat.into_string() {
                Ok(pat) => pat,
                Err(_) => return Err(Error::new("pattern given is not valid UTF-8")),
            };
            return Ok(Patterns { patterns: vec![pat] });
        }
        let mut seen = HashSet::new();
        let mut patterns = Vec::with_capacity(low.patterns.len());
        let mut add = |pat: String| {
            if !seen.contains(&pat) {
                seen.insert(pat.clone());
                patterns.push(pat);
            }
        };
        for source in low.patterns.drain(..) {
            match source {
                PatternSource::Regexp(pat) => add(pat),
                PatternSource::File(path) => {
                    if path == Path::new("-") {
                        if state.stdin_consumed {
                            return Err(Error::new(
                                "error: attempted to read patterns from stdin while also searching stdin",
                            ));
                        }
                        let stdin = io::stdin();
                        for pat in patterns_from_reader(stdin.lock(), None)? {
                            add(pat);
                        }
                        state.stdin_consumed = true;
                    } else {
                        let file = std::fs::File::open(&path)
                            .map_err(|e| Error::new(format!("{}: {}", path.display(), e)))?;
                        for pat in patterns_from_reader(io::BufReader::new(file), Some(&path))? {
                            add(pat);
                        }
                    }
                }
            }
        }
        Ok(Patterns { patterns })
    }
}

fn patterns_from_reader<R: io::BufRead>(mut rdr: R, path: Option<&Path>) -> Result<Vec<String>> {
    let mut patterns = vec![];
    let mut line_number = 0;
    let mut line = vec![];
    loop {
        line.clear();
        let n = rdr.read_until(b'\n', &mut line).map_err(|e| match path {
            Some(p) => Error::new(format!("{}: {}", p.display(), e)),
            None => Error::new(e.to_string()),
        })?;
        if n == 0 {
            break;
        }
        line_number += 1;
        let mut l: &[u8] = &line;
        if l.last() == Some(&b'\n') {
            l = &l[..l.len() - 1];
            if l.last() == Some(&b'\r') {
                l = &l[..l.len() - 1];
            }
        }
        match std::str::from_utf8(l) {
            Ok(s) => patterns.push(s.to_string()),
            Err(e) => {
                let msg = format!(
                    "found invalid UTF-8 in pattern at byte offset {}: {} \
                     (disable Unicode mode and use hex escape sequences to match \
                     arbitrary bytes in a pattern, e.g., '(?-u)\\xFF')",
                    e.valid_up_to(),
                    crate::util::escape_bytes(l)
                );
                return Err(match path {
                    Some(p) => Error::new(format!("{}: line {}: {}", p.display(), line_number, msg)),
                    None => Error::new(format!("line {}: {}", line_number, msg)),
                });
            }
        }
    }
    Ok(patterns)
}

impl Paths {
    fn from_low_args(state: &mut State, _: &Patterns, low: &mut LowArgs) -> Result<Paths> {
        let mut paths = Vec::with_capacity(low.positional.len());
        for osarg in low.positional.drain(..) {
            let path = PathBuf::from(osarg);
            if state.stdin_consumed && path == Path::new("-") {
                return Err(Error::new(
                    "error: attempted to read patterns from stdin while also searching stdin",
                ));
            }
            paths.push(path);
        }
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1083",
            "number of paths given to search: {}",
            paths.len()
        );
        if !paths.is_empty() {
            let is_one_file = paths.len() == 1 && (paths[0] == Path::new("-") || !paths[0].is_dir());
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1094",
                "is_one_file? {:?}",
                is_one_file
            );
            return Ok(Paths { paths, has_implicit_path: false, is_one_file });
        }
        let is_readable_stdin = crate::util::is_readable_stdin();
        let use_cwd = !is_readable_stdin || state.stdin_consumed || !matches!(low.mode, Mode::Search(_));
        crate::log_debug!(
            "rg::flags::hiargs",
            "crates/core/flags/hiargs.rs:1108",
            "using heuristics to determine whether to read from stdin or search ./ \
             (is_readable_stdin={}, stdin_consumed={}, mode={})",
            is_readable_stdin,
            state.stdin_consumed,
            mode_debug(low.mode)
        );
        let (path, is_one_file) = if use_cwd {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1118",
                "heuristic chose to search ./"
            );
            (PathBuf::from("./"), false)
        } else {
            crate::log_debug!(
                "rg::flags::hiargs",
                "crates/core/flags/hiargs.rs:1121",
                "heuristic chose to search stdin"
            );
            (PathBuf::from("-"), true)
        };
        Ok(Paths { paths: vec![path], has_implicit_path: true, is_one_file })
    }
}

fn mode_debug(mode: Mode) -> String {
    match mode {
        Mode::Search(SearchMode::Standard) => "Search(Standard)".to_string(),
        Mode::Search(SearchMode::FilesWithMatches) => "Search(FilesWithMatches)".to_string(),
        Mode::Search(SearchMode::FilesWithoutMatch) => "Search(FilesWithoutMatch)".to_string(),
        Mode::Search(SearchMode::Count) => "Search(Count)".to_string(),
        Mode::Search(SearchMode::CountMatches) => "Search(CountMatches)".to_string(),
        Mode::Search(SearchMode::JSON) => "Search(JSON)".to_string(),
        Mode::Files => "Files".to_string(),
        Mode::Types => "Types".to_string(),
        Mode::Generate(_) => "Generate(..)".to_string(),
    }
}

