//! Decompression via external commands.

use std::ffi::{OsStr, OsString};
use std::io::{self, Read};
use std::path::Path;
use std::process::{Child, Command, Stdio};

use crate::glob::{Glob, GlobMatcher, GlobOptions};

struct DecompressionCommand {
    glob: GlobMatcher,
    bin: OsString,
    args: Vec<OsString>,
}

pub struct DecompressionMatcher {
    commands: Vec<DecompressionCommand>,
}

impl DecompressionMatcher {
    pub fn new() -> DecompressionMatcher {
        let mut builder = DecompressionMatcherBuilder::new();
        builder.add_defaults();
        builder
    }

    pub fn has_command(&self, path: &Path) -> bool {
        self.command(path).is_some()
    }

    fn command(&self, path: &Path) -> Option<&DecompressionCommand> {
        use std::os::unix::ffi::OsStrExt;
        let name = path.file_name()?;
        for cmd in &self.commands {
            if cmd.glob.is_match(name.as_bytes()) {
                return Some(cmd);
            }
        }
        None
    }
}

type DecompressionMatcherBuilder = DecompressionMatcher;

impl DecompressionMatcherBuilder {
    fn add_defaults(&mut self) {
        let defaults: &[(&str, &str, &[&str])] = &[
            ("*.gz", "gzip", &["-d", "-c"]),
            ("*.tgz", "gzip", &["-d", "-c"]),
            ("*.bz2", "bzip2", &["-d", "-c"]),
            ("*.tbz2", "bzip2", &["-d", "-c"]),
            ("*.xz", "xz", &["-d", "-c"]),
