//! Haystacks: things to search.

use std::path::Path;

use crate::gitignore::IgnoreError;
use crate::walk::DirEntry;

#[derive(Clone, Debug)]
pub struct HaystackBuilder {
    strip_dot_prefix: bool,
}

impl HaystackBuilder {
    pub fn new() -> HaystackBuilder {
        HaystackBuilder { strip_dot_prefix: false }
    }

    pub fn strip_dot_prefix(&mut self, yes: bool) -> &mut HaystackBuilder {
        self.strip_dot_prefix = yes;
        self
    }

    pub fn build_from_result(&self, result: Result<DirEntry, IgnoreError>) -> Option<Haystack> {
        match result {
            Ok(dent) => self.build(dent),
            Err(err) => {
                crate::err_message!("{}", err);
                None
            }
        }
    }

    pub fn build(&self, dent: DirEntry) -> Option<Haystack> {
        let hay = Haystack { dent, strip_dot_prefix: self.strip_dot_prefix };
        if let Some(err) = hay.dent.error() {
            crate::ignore_message!("{}", err);
        }
        if hay.is_explicit() {
            return Some(hay);
        }
        if hay.is_file() {
            return Some(hay);
        }
        if !hay.is_dir() {
            crate::log_debug!(
                "rg::haystack",
                "crates/core/haystack.rs:82",
                "ignoring {}: failed to pass haystack filter: \
                 file type: {:?}, metadata: {:?}",
                hay.dent.path().display(),
                hay.dent.file_type(),
                hay.dent.metadata()
            );
        }
        None
    }
}

#[derive(Clone, Debug)]
pub struct Haystack {
    dent: DirEntry,
    strip_dot_prefix: bool,
}

impl Haystack {
    pub fn path(&self) -> &Path {
        if self.strip_dot_prefix && self.dent.path().starts_with("./") {
            self.dent.path().strip_prefix("./").unwrap()
        } else {
            self.dent.path()
        }
    }

    pub fn is_stdin(&self) -> bool {
        self.dent.is_stdin()
    }

    pub fn is_explicit(&self) -> bool {
        self.dent.depth() == 0 && !self.is_dir()
    }

    fn is_dir(&self) -> bool {
        let ft = match self.dent.file_type() {
            None => return false,
            Some(ft) => ft,
        };
        if ft.is_dir() {
            return true;
        }
        self.dent.path_is_symlink() && self.dent.path().is_dir()
    }

    fn is_file(&self) -> bool {
        self.dent.file_type().map_or(false, |ft| ft.is_file())
    }
}
