    pub fn close(&mut self) -> io::Result<()> {
        if self.eof {
            return Ok(());
        }
        self.eof = true;
        let status = self.child.wait()?;
        let stderr = self.stderr.take().map(|h| h.join().unwrap_or_default()).unwrap_or_default();
        if status.success() {
            Ok(())
        } else {
            let msg = String::from_utf8_lossy(&stderr).trim().to_string();
            if msg.is_empty() {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    format!("process exited with status {}", status),
                ))
            } else {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    format!("\n{}\n{}", "-".repeat(79), msg),
                ))
            }
        }
    }
}

impl Read for CommandReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.eof {
            return Ok(0);
        }
        let n = self.stdout.read(buf)?;
        if n == 0 {
            self.close()?;
        }
        Ok(n)
    }
}

impl Drop for CommandReader {
    fn drop(&mut self) {
        if !self.eof {
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
    }
}

/// Build a decompression reader for the given path.
pub fn decompression_reader(matcher: &DecompressionMatcher, path: &Path) -> io::Result<CommandReader> {
    let cmd = match matcher.command(path) {
        None => {
            return Err(io::Error::new(io::ErrorKind::Other, "no decompression command"));
        }
        Some(cmd) => cmd,
    };
    let mut c = Command::new(&cmd.bin);
    c.args(&cmd.args);
    c.arg(path);
    c.stdin(Stdio::null());
    CommandReader::new(&mut c).map_err(|err| {
        io::Error::new(
            io::ErrorKind::Other,
            format!("{}: {}", cmd.bin.to_string_lossy(), err),
        )
    })
}
