/// Build a printer for the given search mode.
pub fn build_printer<W: Write>(args: &HiArgs, mode: SearchMode, wtr: ColorWriter<W>) -> Printer<W> {
    let summary_kind = if args.quiet {
        SummaryKind::Quiet
    } else {
        match mode {
            SearchMode::FilesWithMatches => SummaryKind::PathWithMatch,
            SearchMode::FilesWithoutMatch => SummaryKind::PathWithoutMatch,
            SearchMode::Count => SummaryKind::Count,
            SearchMode::CountMatches => SummaryKind::CountMatches,
            SearchMode::JSON => return Printer::JSON(printer_json(args, wtr)),
