        }
    };
    Printer::Summary(printer_summary(args, wtr, summary_kind))
}

fn printer_standard<W: Write>(args: &HiArgs, wtr: ColorWriter<W>) -> Standard<W> {
    let mut config = StandardConfig::default();
    config.byte_offset = args.byte_offset;
    config.colors = args.colors.clone();
    config.column = args.column;
    config.heading = args.heading;
    config.hyperlink = args.hyperlink_config.clone();
    config.max_columns_preview = args.max_columns_preview;
    config.max_columns = args.max_columns;
    config.only_matching = args.only_matching;
    config.path = args.with_filename;
    config.path_terminator = args.path_terminator;
    config.per_match_one_line = true;
    config.per_match = args.vimgrep;
    config.replacement = std::sync::Arc::new(args.replace.clone().map(|r| r.into()));
    config.separator_context = std::sync::Arc::new(args.context_separator.clone().into_bytes());
    config.separator_field_context = std::sync::Arc::new(args.field_context_separator.clone().into_bytes());
    config.separator_field_match = std::sync::Arc::new(args.field_match_separator.clone().into_bytes());
    config.separator_path = args.path_separator;
    config.separator_search = std::sync::Arc::new(None);
    config.stats = args.stats.is_some();
    config.trim_ascii = args.trim;
    config.max_matches = args.max_count;
    if args.threads == 1 {
        config.separator_search = std::sync::Arc::new(args.file_separator.clone());
    }
    Standard::new(config, wtr)
}

fn printer_summary<W: Write>(args: &HiArgs, wtr: ColorWriter<W>, kind: SummaryKind) -> Summary<W> {
    let mut config = SummaryConfig::default();
    config.kind = kind;
    config.colors = args.colors.clone();
    config.hyperlink = args.hyperlink_config.clone();
    config.stats = args.stats.is_some();
    config.path = args.with_filename;
    config.max_matches = args.max_count;
    config.exclude_zero = !args.include_zero;
    config.separator_field = std::sync::Arc::new(b":".to_vec());
    config.separator_path = args.path_separator;
    config.path_terminator = args.path_terminator;
    Summary::new(config, wtr)
}

fn printer_json<W: Write>(args: &HiArgs, wtr: ColorWriter<W>) -> JSON<W> {
    let config = JSONConfig { pretty: false, max_matches: args.max_count, always_begin_end: false };
    JSON::new(config, wtr)
}

/// Returns true if the given mode is a search mode.
pub fn search_mode(mode: Mode) -> Option<SearchMode> {
    match mode {
        Mode::Search(m) => Some(m),
        _ => None,
    }
}
