//! ripgrep (rg) — a line-oriented search tool.

#[macro_use]
mod messages;
#[macro_use]
mod error;

mod decompress;
mod encoding;
mod encoding_tables;
mod flags;
mod gitignore;
mod glob;
mod haystack;
mod ignore;
