//! ripgrep (rg) — a line-oriented search tool.

#[macro_use]
mod messages;
#[macro_use]
mod error;

mod decompress;
mod encoding;
mod encoding_tables;
mod flags;
mod gitignore;
mod glob;
mod haystack;
mod ignore;
mod matcher;
mod printer;
mod search;
mod searcher;
mod types;
mod util;
mod walk;

use std::io::{self, Write};
use std::process::ExitCode;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Mutex;
use std::time::Instant;

use crate::flags::hiargs::{HiArgs, SearchWorkerConfig};
use crate::flags::{GenerateMode, Mode, ParseResult, SearchMode, SpecialMode};
use crate::haystack::HaystackBuilder;
use crate::printer::ColorWriter;
use crate::search::{build_printer, Printer, SearchWorker};
use crate::walk::{ParallelVisitor, ParallelVisitorBuilder, WalkState};

fn main() -> ExitCode {
    let started_at = Instant::now();
    match run(started_at) {
        Ok(code) => code,
        Err(err) => {
            // Broken pipe errors are silently ignored.
            let msg = err.to_string();
            if msg.contains("Broken pipe") {
                return ExitCode::from(0);
            }
            eprintln_locked!("{}", msg);
            ExitCode::from(2)
        }
    }
}

fn run(started_at: Instant) -> error::Result<ExitCode> {
    let args = match flags::parse() {
        ParseResult::Err(err) => return Err(err),
        ParseResult::Special(mode) => return special(mode),
        ParseResult::Ok(args) => args,
    };
    let matched = match args.mode() {
        Mode::Search(_) if !args.matches_possible() => false,
        Mode::Search(mode) => {
            if args.threads() == 1 {
                search(&args, mode, started_at)?
            } else {
                search_parallel(&args, mode, started_at)?
            }
        }
        Mode::Files => {
            if args.threads() == 1 {
                files(&args)?
            } else {
                files_parallel(&args)?
            }
        }
        Mode::Types => types(&args)?,
        Mode::Generate(mode) => generate(mode)?,
    };
    Ok(if matched && (args.quiet || !messages::errored()) {
        ExitCode::from(0)
    } else if messages::errored() {
        ExitCode::from(2)
    } else {
        ExitCode::from(1)
    })
}

impl HiArgs {
    /// Returns false when no matches are possible (e.g. no patterns in a
    /// search mode). Always true here; kept for structural parity.
    fn matches_possible(&self) -> bool {
        true
    }
}

fn special(mode: SpecialMode) -> error::Result<ExitCode> {
    let mut exit = ExitCode::from(0);
    let output = match mode {
        SpecialMode::HelpShort => flags::doc::HELP_SHORT.to_string(),
        SpecialMode::HelpLong => flags::doc::HELP_LONG.to_string(),
        SpecialMode::VersionShort => format!("{}\n", flags::doc::version_short()),
        SpecialMode::VersionLong => format!("{}\n", flags::doc::version_long()),
        SpecialMode::Pcre2Version => {
            exit = ExitCode::from(1);
            format!("{}\n", flags::doc::pcre2_version())
        }
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(output.as_bytes());
    let _ = lock.flush();
    Ok(exit)
}

fn generate(mode: GenerateMode) -> error::Result<bool> {
    let output = match mode {
        GenerateMode::Man => flags::doc::MAN_PAGE,
        GenerateMode::CompleteBash => flags::doc::COMPLETE_BASH,
        GenerateMode::CompleteZsh => flags::doc::COMPLETE_ZSH,
        GenerateMode::CompleteFish => flags::doc::COMPLETE_FISH,
        GenerateMode::CompletePowerShell => flags::doc::COMPLETE_PS1,
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(output.as_bytes())?;
    lock.flush()?;
    Ok(true)
}

fn types(args: &HiArgs) -> error::Result<bool> {
    let mut count = 0;
    let stdout = io::stdout();
    let mut wtr = io::BufWriter::new(stdout.lock());
    for def in args.types.definitions() {
        count += 1;
        wtr.write_all(def.name().as_bytes())?;
        wtr.write_all(b": ")?;
        let mut first = true;
        for glob in def.globs() {
            if !first {
                wtr.write_all(b", ")?;
            }
            wtr.write_all(glob.as_bytes())?;
            first = false;
        }
        wtr.write_all(b"\n")?;
    }
    wtr.flush()?;
    Ok(count > 0)
}

fn eprint_nothing_searched() {
    err_message!(
        "No files were searched, which means ripgrep probably \
         applied a filter you didn't expect.\n\
         Running with --debug will show why files are being skipped."
    );
}

fn print_stats<W: Write>(mode: SearchMode, stats: &printer::stats::Stats, started: Instant, mut wtr: W) -> io::Result<()> {
    let elapsed = Instant::now().duration_since(started);
    if matches!(mode, SearchMode::JSON) {
        let mut msg = Vec::new();
        printer::json::write_summary(&mut msg, stats, elapsed);
        wtr.write_all(&msg)?;
        wtr.write_all(b"\n")
    } else {
        write!(
            wtr,
            "\n{matches} matches\n{lines} matched lines\n{searches_with_match} files contained matches\n{searches} files searched\n{bytes_printed} bytes printed\n{bytes_searched} bytes searched\n{search_time:0.6} seconds spent searching\n{process_time:0.6} seconds\n",
            matches = stats.matches,
            lines = stats.matched_lines,
            searches_with_match = stats.searches_with_match,
            searches = stats.searches,
            bytes_printed = stats.bytes_printed,
            bytes_searched = stats.bytes_searched,
            search_time = stats.elapsed.as_secs_f64(),
            process_time = elapsed.as_secs_f64(),
        )
    }
}

fn worker_config(args: &HiArgs) -> SearchWorkerConfig {
    SearchWorkerConfig {
        preprocessor: args.pre.clone(),
        preprocessor_globs: args.pre_globs.clone(),
        search_zip: args.search_zip,
        binary: args.binary.clone(),
        mmap: args.mmap,
    }
}

fn stdout_color_writer(args: &HiArgs) -> ColorWriter<Box<dyn Write + Send>> {
    let color = args.color_enabled();
    ColorWriter::new(flags::hiargs::stdout_writer(args), color, color)
}

fn search(args: &HiArgs, mode: SearchMode, started_at: Instant) -> error::Result<bool> {
    let matcher = args.matcher()?;
    let decomp = decompress::DecompressionMatcher::new();
    let wconfig = worker_config(args);
    let haystack_builder = {
        let mut b = HaystackBuilder::new();
        b.strip_dot_prefix(args.has_implicit_path());
        b
    };
    let walker = args.walk_builder()?.build();
    let unsorted = walker.filter_map(|result| haystack_builder.build_from_result(result));
    let haystacks = sort_haystacks(args, unsorted);
    let mut matched = false;
    let mut searched = false;
    let mut stats = args.stats();
    let printer = build_printer(args, mode, stdout_color_writer(args));
    let mut worker = SearchWorker::new(&wconfig, &matcher, args.searcher(), printer, &decomp);
    for haystack in haystacks {
        searched = true;
        let search_result = match worker.search(&haystack) {
            Ok(r) => r,
            Err(err) => {
                if err.kind() == io::ErrorKind::BrokenPipe {
                    break;
                }
                err_message!("{}: {}", haystack.path().display(), err);
                continue;
            }
        };
        matched = matched || search_result.has_match();
        if let Some(ref mut stats) = stats {
            if let Some(s) = search_result.stats() {
                *stats += s;
            }
        }
        if matched && args.quit_after_match() {
            break;
        }
    }
    if args.has_implicit_path() && !searched {
        eprint_nothing_searched();
    }
    if let Some(ref stats) = stats {
        let wtr = worker.printer().get_mut();
        let _ = print_stats(mode, stats, started_at, wtr);
    }
    let _ = worker.printer().get_mut().flush();
    Ok(matched)
}

fn sort_haystacks<'a, I>(args: &HiArgs, haystacks: I) -> Box<dyn Iterator<Item = haystack::Haystack> + 'a>
where
    I: Iterator<Item = haystack::Haystack> + 'a,
{
    use std::cmp::Ordering;
    use std::time::SystemTime;
    use flags::lowargs::SortModeKind;
    fn attach_timestamps<'b>(
        haystacks: impl Iterator<Item = haystack::Haystack> + 'b,
        get: impl Fn(&std::fs::Metadata) -> io::Result<SystemTime> + 'b,
    ) -> impl Iterator<Item = (haystack::Haystack, Option<SystemTime>)> + 'b {
        haystacks.map(move |hy| {
            let md = match hy.path().metadata() {
                Ok(md) => md,
                Err(_) => return (hy, None),
            };
            let t = match get(&md) {
                Ok(t) => t,
                Err(_) => return (hy, None),
            };
            (hy, Some(t))
        })
    }
    let sort = match args.sort {
        None => return Box::new(haystacks),
        Some(sort) => sort,
    };
    let mut with_timestamps: Vec<_> = match sort.kind {
        SortModeKind::Path => return Box::new(haystacks),
        SortModeKind::LastModified => attach_timestamps(haystacks, |md| md.modified()).collect(),
        SortModeKind::LastAccessed => attach_timestamps(haystacks, |md| md.accessed()).collect(),
        SortModeKind::Created => attach_timestamps(haystacks, |md| md.created()).collect(),
    };
    with_timestamps.sort_by(|(_, ref t1), (_, ref t2)| {
        let ordering = match (*t1, *t2) {
            (Some(t1), Some(t2)) => t1.cmp(&t2),
            (Some(_), None) => Ordering::Less,
            (None, Some(_)) => Ordering::Greater,
            (None, None) => Ordering::Equal,
        };
        if sort.reverse {
            ordering.reverse()
        } else {
            ordering
        }
    });
    Box::new(with_timestamps.into_iter().map(|(hy, _)| hy))
}

/// Writes per-file buffers to stdout, inserting separators between them.
struct BufferWriter {
    stdout: Mutex<Box<dyn Write + Send>>,
    printed: AtomicBool,
    separator: Option<Vec<u8>>,
}

impl BufferWriter {
    fn print(&self, buf: &[u8]) -> io::Result<()> {
        if buf.is_empty() {
            return Ok(());
        }
        let mut stdout = self.stdout.lock().unwrap();
        if self.printed.load(Ordering::SeqCst) {
            if let Some(ref sep) = self.separator {
                stdout.write_all(sep)?;
                stdout.write_all(b"\n")?;
            }
        }
        stdout.write_all(buf)?;
        self.printed.store(true, Ordering::SeqCst);
        Ok(())
    }
    fn flush(&self) -> io::Result<()> {
        self.stdout.lock().unwrap().flush()
    }
}

struct SearchVisitorBuilder<'a> {
    args: &'a HiArgs,
    mode: SearchMode,
    matcher: &'a matcher::RegexMatcher,
    decomp: &'a decompress::DecompressionMatcher,
    wconfig: &'a SearchWorkerConfig,
    haystack_builder: &'a HaystackBuilder,
    bufwtr: &'a BufferWriter,
    stats: &'a Option<Mutex<printer::stats::Stats>>,
    matched: &'a AtomicBool,
    searched: &'a AtomicBool,
}

struct SearchVisitor<'a> {
    args: &'a HiArgs,
    worker: SearchWorker<'a, Vec<u8>>,
    haystack_builder: &'a HaystackBuilder,
    bufwtr: &'a BufferWriter,
    stats: &'a Option<Mutex<printer::stats::Stats>>,
    matched: &'a AtomicBool,
    searched: &'a AtomicBool,
}

impl<'a> ParallelVisitorBuilder<'a> for SearchVisitorBuilder<'a> {
    fn build(&mut self) -> Box<dyn ParallelVisitor + 'a> {
        let color = self.args.color_enabled();
        let wtr = ColorWriter::new(Vec::new(), color, color);
        let printer = build_printer(self.args, self.mode, wtr);
        let worker = SearchWorker::new(self.wconfig, self.matcher, self.args.searcher(), printer, self.decomp);
        Box::new(SearchVisitor {
            args: self.args,
            worker,
            haystack_builder: self.haystack_builder,
            bufwtr: self.bufwtr,
            stats: self.stats,
            matched: self.matched,
            searched: self.searched,
        })
    }
}

impl<'a> ParallelVisitor for SearchVisitor<'a> {
    fn visit(&mut self, result: Result<walk::DirEntry, gitignore::IgnoreError>) -> WalkState {
        let haystack = match self.haystack_builder.build_from_result(result) {
            Some(haystack) => haystack,
            None => return WalkState::Continue,
        };
        self.searched.store(true, Ordering::SeqCst);
        self.worker.printer().get_mut().clear();
        let search_result = match self.worker.search(&haystack) {
            Ok(r) => r,
            Err(err) => {
                err_message!("{}: {}", haystack.path().display(), err);
                return WalkState::Continue;
            }
        };
        if search_result.has_match() {
            self.matched.store(true, Ordering::SeqCst);
        }
        if let Some(ref locked_stats) = *self.stats {
            if let Some(s) = search_result.stats() {
                let mut stats = locked_stats.lock().unwrap();
                *stats += s;
            }
        }
        if let Err(err) = self.bufwtr.print(self.worker.printer().get_mut()) {
            if err.kind() == io::ErrorKind::BrokenPipe {
                return WalkState::Quit;
            }
            err_message!("{}: {}", haystack.path().display(), err);
        }
        if self.matched.load(Ordering::SeqCst) && self.args.quit_after_match() {
            WalkState::Quit
        } else {
            WalkState::Continue
        }
    }
}

fn search_parallel(args: &HiArgs, mode: SearchMode, started_at: Instant) -> error::Result<bool> {
    let matcher = args.matcher()?;
    let decomp = decompress::DecompressionMatcher::new();
    let wconfig = worker_config(args);
    let haystack_builder = {
        let mut b = HaystackBuilder::new();
        b.strip_dot_prefix(args.has_implicit_path());
        b
    };
    let bufwtr = BufferWriter {
        stdout: Mutex::new(flags::hiargs::stdout_writer(args)),
        printed: AtomicBool::new(false),
        separator: args.file_separator.clone(),
    };
    let stats = args.stats().map(Mutex::new);
    let matched = AtomicBool::new(false);
    let searched = AtomicBool::new(false);
    let walker = args.walk_builder()?.build_parallel();
    {
        let mut builder = SearchVisitorBuilder {
            args,
            mode,
            matcher: &matcher,
            decomp: &decomp,
            wconfig: &wconfig,
            haystack_builder: &haystack_builder,
            bufwtr: &bufwtr,
            stats: &stats,
            matched: &matched,
            searched: &searched,
        };
        walker.visit(&mut builder);
    }
    if args.has_implicit_path() && !searched.load(Ordering::SeqCst) {
        eprint_nothing_searched();
    }
    if let Some(ref locked_stats) = stats {
        let stats = locked_stats.lock().unwrap();
        let mut buf = Vec::new();
        let _ = print_stats(mode, &stats, started_at, &mut buf);
        let _ = bufwtr.print(&buf);
    }
    let _ = bufwtr.flush();
    Ok(matched.load(Ordering::SeqCst))
}

/// Prints paths for --files.
struct PathPrinter<W: Write> {
    wtr: ColorWriter<W>,
    args_colors: printer::color::ColorSpecs,
    hyperlink: printer::hyperlink::HyperlinkConfig,
    separator: Option<u8>,
    terminator: u8,
}

impl<W: Write> PathPrinter<W> {
    fn new(args: &HiArgs, wtr: ColorWriter<W>) -> PathPrinter<W> {
        PathPrinter {
            wtr,
            args_colors: args.colors.clone(),
            hyperlink: args.hyperlink_config.clone(),
            separator: args.path_separator,
            terminator: args.path_terminator.unwrap_or(b'\n'),
        }
    }

    fn write(&mut self, path: &std::path::Path) -> io::Result<()> {
        let ppath = printer::util::PrinterPath::with_separator(path, self.separator);
        let mut active = false;
        if !self.hyperlink.is_empty() && self.wtr.supports_hyperlinks() {
            if let Some(hpath) = ppath.hyperlink_path() {
                let interp = printer::hyperlink::Interpolator::new(&self.hyperlink);
                let mut uri = vec![];
                interp.interpolate(hpath, None, None, &mut uri);
                self.wtr.set_hyperlink(Some(&uri))?;
                active = true;
            }
        }
        self.wtr.set_color(&self.args_colors.path)?;
        self.wtr.write_all(ppath.as_bytes())?;
        self.wtr.reset()?;
        if active {
            self.wtr.set_hyperlink(None)?;
        }
        self.wtr.write_all(&[self.terminator])
    }
}

fn files(args: &HiArgs) -> error::Result<bool> {
    let haystack_builder = {
        let mut b = HaystackBuilder::new();
        b.strip_dot_prefix(args.has_implicit_path());
        b
    };
    let walker = args.walk_builder()?.build();
    let unsorted = walker.filter_map(|result| haystack_builder.build_from_result(result));
    let haystacks = sort_haystacks(args, unsorted);
    let mut matched = false;
    let mut path_printer = PathPrinter::new(args, stdout_color_writer(args));
    for haystack in haystacks {
        matched = true;
        if args.quit_after_match() {
            break;
        }
        if let Err(err) = path_printer.write(haystack.path()) {
            if err.kind() == io::ErrorKind::BrokenPipe {
                break;
            }
            return Err(err.into());
        }
    }
    let _ = path_printer.wtr.flush();
    Ok(matched)
}

struct FilesVisitorBuilder<'a> {
    args: &'a HiArgs,
    haystack_builder: &'a HaystackBuilder,
    tx: std::sync::mpsc::Sender<haystack::Haystack>,
    matched: &'a AtomicBool,
}

struct FilesVisitor<'a> {
    args: &'a HiArgs,
    haystack_builder: &'a HaystackBuilder,
    tx: std::sync::mpsc::Sender<haystack::Haystack>,
    matched: &'a AtomicBool,
}

impl<'a> ParallelVisitorBuilder<'a> for FilesVisitorBuilder<'a> {
    fn build(&mut self) -> Box<dyn ParallelVisitor + 'a> {
        Box::new(FilesVisitor {
            args: self.args,
            haystack_builder: self.haystack_builder,
            tx: self.tx.clone(),
            matched: self.matched,
        })
    }
}

impl<'a> ParallelVisitor for FilesVisitor<'a> {
    fn visit(&mut self, result: Result<walk::DirEntry, gitignore::IgnoreError>) -> WalkState {
        let haystack = match self.haystack_builder.build_from_result(result) {
            Some(haystack) => haystack,
            None => return WalkState::Continue,
        };
        self.matched.store(true, Ordering::SeqCst);
        if self.args.quit_after_match() {
            WalkState::Quit
        } else if self.tx.send(haystack).is_err() {
            WalkState::Quit
        } else {
            WalkState::Continue
        }
    }
}

fn files_parallel(args: &HiArgs) -> error::Result<bool> {
    let haystack_builder = {
        let mut b = HaystackBuilder::new();
        b.strip_dot_prefix(args.has_implicit_path());
        b
    };
    let matched = AtomicBool::new(false);
    let (tx, rx) = std::sync::mpsc::channel::<haystack::Haystack>();
    let mut path_printer = PathPrinter::new(args, stdout_color_writer(args));
    let print_thread = std::thread::spawn(move || -> io::Result<()> {
        for haystack in rx.iter() {
            path_printer.write(haystack.path())?;
        }
        path_printer.wtr.flush()
    });
    let walker = args.walk_builder()?.build_parallel();
    {
        let mut builder = FilesVisitorBuilder { args, haystack_builder: &haystack_builder, tx, matched: &matched };
        walker.visit(&mut builder);
    }
    // `tx` was moved into the builder which is now dropped; the channel closes
    // once all clones are dropped.
    if let Err(err) = print_thread.join().unwrap() {
        if err.kind() != io::ErrorKind::BrokenPipe {
            return Err(err.into());
        }
    }
    Ok(matched.load(Ordering::SeqCst))
}
