    pub fn close(&mut self) -> io::Result<()> {
        match *self {
            DecompressionReader::Process(ref mut p) => p.close(),
            DecompressionReader::File(_) => Ok(()),
        }
    }
}

impl Read for DecompressionReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match *self {
            DecompressionReader::Process(ref mut p) => p.read(buf),
            DecompressionReader::File(ref mut f) => f.read(buf),
        }
    }
}

/// Build a decompression reader for the given path.
pub fn decompression_reader(matcher: &DecompressionMatcher, path: &Path) -> io::Result<DecompressionReader> {
    let cmd = match matcher.command(path) {
        None => {
            return Ok(DecompressionReader::File(std::fs::File::open(path)?));
        }
        Some(cmd) => cmd,
    };
    let mut c = Command::new(&cmd.bin);
    c.args(&cmd.args);
    c.arg(path);
    c.stdin(Stdio::null());
    match CommandReader::new(&mut c) {
        Ok(rdr) => Ok(DecompressionReader::Process(rdr)),
        Err(err) => {
            crate::log_debug!(
                "grep_cli::decompress",
                "/workspace/crates/cli/src/decompress.rs:234",
                "{}: error spawning command '{:?}': {} (falling back to uncompressed reader)",
                path.display(),
                c,
                err
            );
