#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Iso2022State {
    Ascii,
    Roman,
    Katakana,
    LeadByte,
    TrailByte,
    EscapeStart,
    Escape,
}

#[derive(Debug)]
pub struct MultiByteDecoder {
    enc: Encoding,
    lead: u8,
    // gb18030
    first: u8,
    second: u8,
    third: u8,
    // euc-jp
    jis0212: bool,
    // iso-2022-jp
    state: Iso2022State,
    output_state: Iso2022State,
    output_flag: bool,
}

impl MultiByteDecoder {
    fn new(enc: Encoding) -> MultiByteDecoder {
        MultiByteDecoder {
            enc,
            lead: 0,
            first: 0,
            second: 0,
            third: 0,
            jis0212: false,
            state: Iso2022State::Ascii,
            output_state: Iso2022State::Ascii,
            output_flag: false,
        }
    }

    fn feed(&mut self, b: u8, out: &mut Vec<u8>) {
        match self.enc {
            Encoding::ShiftJis => self.feed_sjis(b, out),
            Encoding::EucJp => self.feed_eucjp(b, out),
            Encoding::EucKr => self.feed_euckr(b, out),
            Encoding::Gb18030 | Encoding::Gbk => self.feed_gb18030(b, out),
            Encoding::Big5 => self.feed_big5(b, out),
            Encoding::Iso2022Jp => self.feed_iso2022jp(b, out),
            _ => out.push(b),
        }
    }

    fn finish(&mut self, out: &mut Vec<u8>) {
        match self.enc {
            Encoding::Gb18030 | Encoding::Gbk => {
                if self.first != 0 || self.second != 0 || self.third != 0 {
                    self.first = 0;
                    self.second = 0;
                    self.third = 0;
                    push_char(out, 0xFFFD);
                }
            }
            Encoding::Iso2022Jp => {
                match self.state {
                    Iso2022State::TrailByte | Iso2022State::EscapeStart | Iso2022State::Escape => {
                        push_char(out, 0xFFFD);
                    }
                    _ => {}
                }
                self.lead = 0;
            }
            _ => {
                if self.lead != 0 {
                    self.lead = 0;
                    push_char(out, 0xFFFD);
                }
            }
        }
    }

    fn feed_sjis(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let offset = if b < 0x7F { 0x40 } else { 0x41 };
            let lead_offset = if lead < 0xA0 { 0x81 } else { 0xC1 };
            if (0x40..=0x7E).contains(&b) || (0x80..=0xFC).contains(&b) {
                let pointer = (lead as usize - lead_offset) * 188 + (b as usize - offset);
                if (8836..=10715).contains(&pointer) {
                    push_char(out, 0xE000 - 8836 + pointer as u32);
                    return;
                }
                if let Some(cp) = idx_get(IDX_JIS0208, pointer) {
                    push_char(out, cp);
                    return;
                }
            }
            push_char(out, 0xFFFD);
            if b < 0x80 {
                self.feed_sjis(b, out);
            }
            return;
        }
        if b <= 0x80 {
            push_char(out, b as u32);
        } else if (0xA1..=0xDF).contains(&b) {
            push_char(out, 0xFF61 - 0xA1 + b as u32);
        } else if (0x81..=0x9F).contains(&b) || (0xE0..=0xFC).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_eucjp(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead == 0x8E && (0xA1..=0xDF).contains(&b) {
            self.lead = 0;
            push_char(out, 0xFF61 - 0xA1 + b as u32);
            return;
        }
        if self.lead == 0x8F && (0xA1..=0xFE).contains(&b) {
            self.jis0212 = true;
            self.lead = b;
            return;
        }
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let mut cp = None;
            if (0xA1..=0xFE).contains(&lead) && (0xA1..=0xFE).contains(&b) {
                let pointer = (lead as usize - 0xA1) * 94 + (b as usize - 0xA1);
                cp = if self.jis0212 { idx_get(IDX_JIS0212, pointer) } else { idx_get(IDX_JIS0208, pointer) };
            }
            self.jis0212 = false;
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
                        self.feed_eucjp(b, out);
                    }
                }
            }
            return;
        }
        if b < 0x80 {
            out.push(b);
        } else if b == 0x8E || b == 0x8F || (0xA1..=0xFE).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_euckr(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let mut cp = None;
            if (0x41..=0xFE).contains(&b) {
                let pointer = (lead as usize - 0x81) * 190 + (b as usize - 0x41);
                cp = idx_get(IDX_EUCKR, pointer);
            }
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
                        self.feed_euckr(b, out);
                    }
                }
            }
            return;
        }
        if b < 0x80 {
            out.push(b);
        } else if (0x81..=0xFE).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_gb18030(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.third != 0 {
            if (0x30..=0x39).contains(&b) {
                let pointer = (self.first as u32 - 0x81) * 12600
                    + (self.second as u32 - 0x30) * 1260
                    + (self.third as u32 - 0x81) * 10
                    + (b as u32 - 0x30);
                self.first = 0;
                self.second = 0;
                self.third = 0;
                match gb18030_ranges_code_point(pointer) {
                    Some(cp) => push_char(out, cp),
                    None => push_char(out, 0xFFFD),
                }
                return;
            }
            let (second, third) = (self.second, self.third);
            self.first = 0;
            self.second = 0;
            self.third = 0;
            push_char(out, 0xFFFD);
            // Reprocess second, third and byte.
            self.feed_gb18030(second, out);
            self.feed_gb18030(third, out);
            self.feed_gb18030(b, out);
            return;
        }
        if self.second != 0 {
            if (0x81..=0xFE).contains(&b) {
                self.third = b;
                return;
            }
            let second = self.second;
            self.first = 0;
            self.second = 0;
            push_char(out, 0xFFFD);
            self.feed_gb18030(second, out);
            self.feed_gb18030(b, out);
            return;
        }
        if self.first != 0 {
            if (0x30..=0x39).contains(&b) {
                self.second = b;
                return;
            }
            let lead = self.first;
            self.first = 0;
            let mut cp = None;
            if (0x40..=0x7E).contains(&b) || (0x80..=0xFE).contains(&b) {
                let offset = if b < 0x7F { 0x40 } else { 0x41 };
                let pointer = (lead as usize - 0x81) * 190 + (b as usize - offset);
                cp = idx_get(IDX_GB18030, pointer);
            }
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
                        self.feed_gb18030(b, out);
                    }
                }
            }
            return;
        }
        if b < 0x80 {
            out.push(b);
        } else if b == 0x80 {
            push_char(out, 0x20AC);
        } else if (0x81..=0xFE).contains(&b) {
            self.first = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_big5(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let mut pointer = None;
            if (0x40..=0x7E).contains(&b) || (0xA1..=0xFE).contains(&b) {
                let offset = if b < 0x7F { 0x40 } else { 0x62 };
                pointer = Some((lead as usize - 0x81) * 157 + (b as usize - offset));
            }
            match pointer {
                Some(1133) => {
                    push_char(out, 0x00CA);
                    push_char(out, 0x0304);
                    return;
                }
                Some(1135) => {
                    push_char(out, 0x00CA);
                    push_char(out, 0x030C);
                    return;
                }
                Some(1164) => {
                    push_char(out, 0x00EA);
                    push_char(out, 0x0304);
                    return;
                }
                Some(1166) => {
                    push_char(out, 0x00EA);
                    push_char(out, 0x030C);
                    return;
                }
                _ => {}
            }
            let cp = pointer.and_then(|p| {
                if p < (0xA1 - 0x81) * 157 {
                    None
                } else {
                    idx_get(IDX_BIG5, p).or_else(|| big5_nonbmp(p))
                }
            });
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
                        self.feed_big5(b, out);
                    }
                }
            }
            return;
        }
        if b < 0x80 {
            out.push(b);
        } else if (0x81..=0xFE).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_iso2022jp(&mut self, b: u8, out: &mut Vec<u8>) {
        use Iso2022State::*;
        match self.state {
            Ascii => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if b <= 0x7F && b != 0x0E && b != 0x0F {
                    self.output_flag = false;
                    out.push(b);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            Roman => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if b == 0x5C {
                    self.output_flag = false;
                    push_char(out, 0x00A5);
                } else if b == 0x7E {
                    self.output_flag = false;
                    push_char(out, 0x203E);
                } else if b <= 0x7F && b != 0x0E && b != 0x0F {
                    self.output_flag = false;
                    out.push(b);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            Katakana => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if (0x21..=0x5F).contains(&b) {
                    self.output_flag = false;
                    push_char(out, 0xFF61 - 0x21 + b as u32);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            LeadByte => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if (0x21..=0x7E).contains(&b) {
                    self.output_flag = false;
                    self.lead = b;
                    self.state = TrailByte;
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            TrailByte => {
                if b == 0x1B {
                    self.state = EscapeStart;
                    push_char(out, 0xFFFD);
                } else if (0x21..=0x7E).contains(&b) {
                    self.state = LeadByte;
                    let pointer = (self.lead as usize - 0x21) * 94 + (b as usize - 0x21);
                    match idx_get(IDX_JIS0208, pointer) {
                        Some(cp) => push_char(out, cp),
                        None => push_char(out, 0xFFFD),
                    }
                } else {
                    self.state = LeadByte;
                    push_char(out, 0xFFFD);
                }
            }
            EscapeStart => {
                if b == 0x24 || b == 0x28 {
                    self.lead = b;
                    self.state = Escape;
                } else {
                    self.output_flag = false;
                    self.state = self.output_state;
                    push_char(out, 0xFFFD);
                    self.feed_iso2022jp(b, out);
                }
            }
            Escape => {
                let lead = self.lead;
                self.lead = 0;
                let new_state = if lead == 0x28 && b == 0x42 {
                    Some(Ascii)
                } else if lead == 0x28 && b == 0x4A {
                    Some(Roman)
                } else if lead == 0x28 && b == 0x49 {
                    Some(Katakana)
                } else if lead == 0x24 && (b == 0x40 || b == 0x42) {
                    Some(LeadByte)
                } else {
                    None
                };
                match new_state {
                    Some(st) => {
                        self.state = st;
                        self.output_state = st;
                        let was_flag = self.output_flag;
                        self.output_flag = true;
                        if was_flag {
                            push_char(out, 0xFFFD);
                        }
                    }
                    None => {
                        self.output_flag = false;
                        self.state = self.output_state;
                        push_char(out, 0xFFFD);
                        // Reprocess lead and byte.
                        self.feed_iso2022jp(lead, out);
                        self.feed_iso2022jp(b, out);
                    }
                }
            }
        }
    }
}
