// ---------------------------------------------------------------------------
// Legacy multi-byte decoders (WHATWG Encoding Standard algorithms).
// ---------------------------------------------------------------------------

static IDX_JIS0208: &[u8] = include_bytes!("../data/idx_jis0208.bin");
static IDX_JIS0212: &[u8] = include_bytes!("../data/idx_jis0212.bin");
static IDX_EUCKR: &[u8] = include_bytes!("../data/idx_euckr.bin");
static IDX_GB18030: &[u8] = include_bytes!("../data/idx_gb18030.bin");
static IDX_BIG5: &[u8] = include_bytes!("../data/idx_big5.bin");
static GB18030_RANGES: &[u8] = include_bytes!("../data/gb18030_ranges.bin");
static BIG5_NONBMP: &[u8] = include_bytes!("../data/big5_nonbmp.bin");

fn idx_get(table: &[u8], pointer: usize) -> Option<u32> {
    let i = pointer * 2;
    if i + 1 >= table.len() {
        return None;
    }
    let v = u16::from_le_bytes([table[i], table[i + 1]]);
    if v == 0 { None } else { Some(v as u32) }
}

fn gb18030_ranges_code_point(pointer: u32) -> Option<u32> {
    if (39420 < pointer && pointer < 189000) || pointer > 1237575 {
        return None;
    }
    if pointer == 7457 {
        return Some(0xE7C7);
    }
    if pointer >= 189000 {
        return Some(0x10000 + (pointer - 189000));
    }
    let n = GB18030_RANGES.len() / 8;
    let mut offset = 0u32;
    let mut cp_offset = 0u32;
    for i in 0..n {
        let p = u32::from_le_bytes([
            GB18030_RANGES[i * 8],
            GB18030_RANGES[i * 8 + 1],
            GB18030_RANGES[i * 8 + 2],
            GB18030_RANGES[i * 8 + 3],
        ]);
        let cp = u32::from_le_bytes([
            GB18030_RANGES[i * 8 + 4],
            GB18030_RANGES[i * 8 + 5],
            GB18030_RANGES[i * 8 + 6],
            GB18030_RANGES[i * 8 + 7],
        ]);
        if p > pointer {
            break;
        }
        offset = p;
        cp_offset = cp;
    }
    Some(cp_offset + pointer - offset)
}

fn big5_nonbmp(pointer: usize) -> Option<u32> {
    let n = BIG5_NONBMP.len() / 8;
    for i in 0..n {
        let p = u32::from_le_bytes([
            BIG5_NONBMP[i * 8],
            BIG5_NONBMP[i * 8 + 1],
            BIG5_NONBMP[i * 8 + 2],
            BIG5_NONBMP[i * 8 + 3],
        ]) as usize;
        if p == pointer {
            return Some(u32::from_le_bytes([
                BIG5_NONBMP[i * 8 + 4],
                BIG5_NONBMP[i * 8 + 5],
                BIG5_NONBMP[i * 8 + 6],
                BIG5_NONBMP[i * 8 + 7],
            ]));
        }
    }
    None
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Iso2022State {
    Ascii,
    Roman,
    Katakana,
    LeadByte,
    TrailByte,
    EscapeStart,
    Escape,
}

#[derive(Debug)]
pub struct MultiByteDecoder {
    enc: Encoding,
    lead: u8,
    // gb18030
    first: u8,
    second: u8,
    third: u8,
    // euc-jp
    jis0212: bool,
    // iso-2022-jp
    state: Iso2022State,
    output_state: Iso2022State,
    output_flag: bool,
}

impl MultiByteDecoder {
    fn new(enc: Encoding) -> MultiByteDecoder {
        MultiByteDecoder {
            enc,
            lead: 0,
            first: 0,
            second: 0,
            third: 0,
            jis0212: false,
            state: Iso2022State::Ascii,
            output_state: Iso2022State::Ascii,
            output_flag: false,
        }
    }

    fn feed(&mut self, b: u8, out: &mut Vec<u8>) {
        match self.enc {
            Encoding::ShiftJis => self.feed_sjis(b, out),
            Encoding::EucJp => self.feed_eucjp(b, out),
            Encoding::EucKr => self.feed_euckr(b, out),
            Encoding::Gb18030 | Encoding::Gbk => self.feed_gb18030(b, out),
            Encoding::Big5 => self.feed_big5(b, out),
            Encoding::Iso2022Jp => self.feed_iso2022jp(b, out),
            _ => out.push(b),
        }
    }

    fn finish(&mut self, out: &mut Vec<u8>) {
        match self.enc {
            Encoding::Gb18030 | Encoding::Gbk => {
                if self.first != 0 || self.second != 0 || self.third != 0 {
                    self.first = 0;
                    self.second = 0;
                    self.third = 0;
                    push_char(out, 0xFFFD);
                }
            }
            Encoding::Iso2022Jp => {
                match self.state {
                    Iso2022State::TrailByte | Iso2022State::EscapeStart | Iso2022State::Escape => {
                        push_char(out, 0xFFFD);
                    }
                    _ => {}
                }
                self.lead = 0;
            }
            _ => {
                if self.lead != 0 {
                    self.lead = 0;
                    push_char(out, 0xFFFD);
                }
            }
        }
    }

    fn feed_sjis(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let offset = if b < 0x7F { 0x40 } else { 0x41 };
            let lead_offset = if lead < 0xA0 { 0x81 } else { 0xC1 };
            if (0x40..=0x7E).contains(&b) || (0x80..=0xFC).contains(&b) {
                let pointer = (lead as usize - lead_offset) * 188 + (b as usize - offset);
                if (8836..=10715).contains(&pointer) {
                    push_char(out, 0xE000 - 8836 + pointer as u32);
                    return;
                }
                if let Some(cp) = idx_get(IDX_JIS0208, pointer) {
                    push_char(out, cp);
                    return;
                }
            }
            push_char(out, 0xFFFD);
            if b < 0x80 {
                self.feed_sjis(b, out);
            }
            return;
        }
        if b <= 0x80 {
            push_char(out, b as u32);
        } else if (0xA1..=0xDF).contains(&b) {
            push_char(out, 0xFF61 - 0xA1 + b as u32);
        } else if (0x81..=0x9F).contains(&b) || (0xE0..=0xFC).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_eucjp(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead == 0x8E && (0xA1..=0xDF).contains(&b) {
            self.lead = 0;
            push_char(out, 0xFF61 - 0xA1 + b as u32);
            return;
        }
        if self.lead == 0x8F && (0xA1..=0xFE).contains(&b) {
            self.jis0212 = true;
            self.lead = b;
            return;
        }
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let mut cp = None;
            if (0xA1..=0xFE).contains(&lead) && (0xA1..=0xFE).contains(&b) {
                let pointer = (lead as usize - 0xA1) * 94 + (b as usize - 0xA1);
                cp = if self.jis0212 { idx_get(IDX_JIS0212, pointer) } else { idx_get(IDX_JIS0208, pointer) };
            }
            self.jis0212 = false;
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
                        self.feed_eucjp(b, out);
                    }
                }
            }
            return;
        }
        if b < 0x80 {
            out.push(b);
        } else if b == 0x8E || b == 0x8F || (0xA1..=0xFE).contains(&b) {
            self.lead = b;
        } else {
            push_char(out, 0xFFFD);
        }
    }

    fn feed_euckr(&mut self, b: u8, out: &mut Vec<u8>) {
        if self.lead != 0 {
            let lead = self.lead;
            self.lead = 0;
            let mut cp = None;
            if (0x41..=0xFE).contains(&b) {
                let pointer = (lead as usize - 0x81) * 190 + (b as usize - 0x41);
                cp = idx_get(IDX_EUCKR, pointer);
            }
            match cp {
                Some(cp) => push_char(out, cp),
                None => {
                    push_char(out, 0xFFFD);
                    if b < 0x80 {
