                    self.output_flag = false;
                    out.push(b);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            Roman => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if b == 0x5C {
                    self.output_flag = false;
                    push_char(out, 0x00A5);
                } else if b == 0x7E {
                    self.output_flag = false;
                    push_char(out, 0x203E);
                } else if b <= 0x7F && b != 0x0E && b != 0x0F {
                    self.output_flag = false;
                    out.push(b);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            Katakana => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if (0x21..=0x5F).contains(&b) {
                    self.output_flag = false;
                    push_char(out, 0xFF61 - 0x21 + b as u32);
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
            }
            LeadByte => {
                if b == 0x1B {
                    self.state = EscapeStart;
                } else if (0x21..=0x7E).contains(&b) {
                    self.output_flag = false;
                    self.lead = b;
                    self.state = TrailByte;
                } else {
                    self.output_flag = false;
                    push_char(out, 0xFFFD);
                }
