            EscapeStart => {
                if b == 0x24 || b == 0x28 {
                    self.lead = b;
                    self.state = Escape;
                } else {
                    self.output_flag = false;
                    self.state = self.output_state;
                    push_char(out, 0xFFFD);
                    self.feed_iso2022jp(b, out);
                }
            }
            Escape => {
                let lead = self.lead;
                self.lead = 0;
                let new_state = if lead == 0x28 && b == 0x42 {
                    Some(Ascii)
                } else if lead == 0x28 && b == 0x4A {
                    Some(Roman)
                } else if lead == 0x28 && b == 0x49 {
                    Some(Katakana)
                } else if lead == 0x24 && (b == 0x40 || b == 0x42) {
                    Some(LeadByte)
                } else {
                    None
                };
                match new_state {
                    Some(st) => {
                        self.state = st;
                        self.output_state = st;
                        let was_flag = self.output_flag;
                        self.output_flag = true;
                        if was_flag {
                            push_char(out, 0xFFFD);
                        }
                    }
                    None => {
                        self.output_flag = false;
                        self.state = self.output_state;
                        push_char(out, 0xFFFD);
                        // Reprocess lead and byte.
                        self.feed_iso2022jp(lead, out);
                        self.feed_iso2022jp(b, out);
                    }
                }
            }
        }
    }
}
